#
# Module
#


class LesionNetworkMapping(ScriptedLoadableModule):
    """Lesion network mapping with a normative connectome (Map workspace of Slicer Studio)."""

    def __init__(self, parent):
        ScriptedLoadableModule.__init__(self, parent)
        self.parent.title = _("Lesion Network Mapping")
        self.parent.categories = [translate("qSlicerAbstractCoreModule", "Quantification")]
        self.parent.dependencies = []
        self.parent.contributors = ["Slicer Studio contributors"]
        self.parent.helpText = _("""
<p>Computes the brain network functionally connected to a lesion, from a normative connectome
(lesion network mapping: Boes et al. 2015; Fox 2018).</p>
<p><b>Method.</b> The lesion (a segment, on an MNI grid) is resampled onto the connectome grid as fractional
occupancy. For every connectome subject the mean time course of the lesion is correlated with every voxel
(Pearson r averaged over runs, Fisher z); the maps are the mean r, the mean Fz and the one-sample T of Fz
over the subjects. The computation runs in a separate process: the application stays responsive, a
partial map is shown every 50 subjects and Stop keeps the latest one, labelled with its N.</p>
<p><b>Thresholds are rules</b>, re-resolved from N and V on every update: FWE (Bonferroni, the default),
the |T| &ge; 7 convention (only for N &ge; 900), an Fz effect size, a custom T, or the top x% of the map
(N-independent). A rule defined for another N shows a banner. Moving a threshold only changes the colour
table's alpha values.</p>
<p><b>Quality checks.</b> Every map is compared with the connectome's hubness (degree) map, and with the maps
of the same lesion relocated elsewhere in the brain (50 relocations by default, in the same pass).
Similar maps for very different lesions are a known limitation of the method (van den Heuvel et al. 2026).</p>
<p><b>Connectomes</b> are never bundled or downloaded automatically. Register a converted bundle (.lnmc folder)
and accept its data use terms; a synthetic demo can be created for trying the module.</p>
<p><b>Research use only — not for clinical decisions.</b> Lesion network mapping specificity is debated
(van den Heuvel et al., 2026; Siddiqi et al., 2026; Zalesky &amp; Cash, 2026).</p>
""")
        self.parent.acknowledgementText = _("""
<p>Boes AD et al. Network localization of neurological symptoms from focal brain lesions. Brain 2015;138:3061-3075.
Fox MD. Mapping symptoms to brain networks with the human connectome. N Engl J Med 2018;379:2237-2245.
van den Heuvel et al. Nat Neurosci 2026, doi:10.1038/s41593-025-02196-7 (the specificity critique);
Siddiqi SH et al. bioRxiv 2026, doi:10.64898/2026.02.24.707529; Zalesky A, Cash RFH. Nat Neurosci 2026, doi:10.1038/s41593-026-02259-3.</p>
<p>The MNI152NLin2009cAsym template is Copyright (C) 1993-2009 Louis Collins, McConnell Brain Imaging Centre,
Montreal Neurological Institute, McGill University (see LICENSE-MNI152NLin2009cAsym.txt in SampleData).</p>
""")
        if not slicer.app.testingEnabled():
            slicer.app.connect("startupCompleted()", registerPaletteProvider)
        if not installSceneMigration():
            slicer.app.connect("startupCompleted()", installSceneMigration)


#
# Scenes of earlier versions: the connectome's absolute path is replaced in the scene, not only in the widget
#

#: Priority of the scene observers of ``installSceneMigration``: before the module widget reads the parameter node
SCENE_MIGRATION_PRIORITY = 10.0


def installSceneMigration():
    """Observe the scene (import and save) to replace a legacy ``connectomePath`` (``migrateLegacyConnectomePaths``)
    and absolute normalization references (``migrateNormalizationReferences``).

    Scenes of earlier versions hold the connectome bundle's absolute path. It is replaced as soon as such a scene
    is loaded, and again before every save, whether or not the Map module was opened, so that a scene saved again
    never holds the path (SPEC 9.7 rule 10). Return False when there is no scene yet.
    """
    scene = getattr(slicer, "mrmlScene", None)
    if scene is None:
        return False
    if getattr(installSceneMigration, "_tags", None) is not None:
        return True

    def onSceneEvent(caller, event):
        try:
            migrateLegacyConnectomePaths(caller)
        except Exception:
            logging.exception("Lesion network mapping: the connectome path of an earlier scene could not be replaced")
        try:
            migrateNormalizationReferences(caller)
        except Exception:
            logging.exception("Lesion network mapping: the normalization references of an earlier scene could not be replaced")

    installSceneMigration._tags = [scene.AddObserver(event, onSceneEvent, SCENE_MIGRATION_PRIORITY)
                                   for event in (slicer.vtkMRMLScene.EndImportEvent, slicer.vtkMRMLScene.StartSaveEvent)]
    return True


def migrateNormalizationReferences(scene=None):
    """Replace absolute ``LNM.Normalization`` / ``LNM.NormLesionWarp`` values of earlier scenes by portable references.

    Scenes of earlier versions hold the absolute path of normalization.json (SPEC 9.7 rule 10). The controller is
    imported only when such a value is found. Return the number of attributes changed.
    """
    scene = scene or slicer.mrmlScene
    for index in range(scene.GetNumberOfNodes()):
        node = scene.GetNthNode(index)
        for attribute in ("LNM.Normalization", "LNM.NormLesionWarp"):
            value = node.GetAttribute(attribute)
            if value and re.match(r"^([A-Za-z]:)?[\\/]", value):
                from LesionNetworkMappingUI import normalize_controller

                return normalize_controller.migrateAbsoluteReferences(scene)
    return 0


def legacyConnectomeName(path):
    """Name-only connectome identifier of a legacy path whose bundle is not on this computer: its folder name."""
    name = re.split(r"[/\\]", (path or "").rstrip("/\\"))[-1]
    return name.replace("#", "") or "connectome"


def migrateLegacyConnectomePaths(scene=None):
    """Replace the legacy ``connectomePath`` of the Map parameter nodes of ``scene`` by a connectome identifier.

    When the bundle is at that path, the identifier is its full ``connectomeIdentifier`` and the bundle is
    registered (``Studio/LNM/Connectomes``), so that it is found again in later sessions; otherwise it is the
    folder name only (``legacyConnectomeName``), which ``resolveConnectome`` matches by name and Map reports as
    missing. The path is cleared in both cases. Return the number of parameter nodes changed.
    """
    scene = scene or slicer.mrmlScene
    nodes = scene.GetNodesByClass("vtkMRMLScriptedModuleNode")
    nodes.UnRegister(None)  # a new collection: release it, or it keeps its nodes alive after removal
    logic, changed = None, 0
    for index in range(nodes.GetNumberOfItems()):
        node = nodes.GetItemAsObject(index)
        if node.GetAttribute("ModuleName") != "LesionNetworkMapping":
            continue
        legacy = node.GetParameter("connectomePath")
        if not legacy:
            continue
        identifier = node.GetParameter("connectome")
        if not identifier:
            if os.path.isfile(os.path.join(legacy, "connectome.json")):
                logic = logic or LesionNetworkMappingLogic()
                try:
                    bundle = logic.openBundle(legacy)
                    identifier = logic.rememberConnectome(bundle)
                    logic.registerConnectome(bundle.path)
                except Exception:
                    logging.warning(f"Lesion network mapping: the connectome bundle of an earlier scene cannot be opened ({legacy})")
                    identifier = ""
            identifier = identifier or legacyConnectomeName(legacy)
            node.SetParameter("connectome", identifier)
        node.SetParameter("connectomePath", "")
        changed += 1
    return changed


#
# Search (palette) entries, Studio only
#


def _openMap(then=None):
    """Show the Map workspace (Studio) or the module (Classic), then call ``then(widget)``."""
    try:
        from StudioLib import shell as shellModule

        shell = shellModule.instance()
    except Exception:
        shell = None
    if shell is not None:
        shell.switchTo("map")
    else:
        slicer.util.selectModule("LesionNetworkMapping")
    widget = slicer.modules.lesionnetworkmapping.widgetRepresentation().self()
    if then is not None:
        then(widget)


def paletteEntries(shell=None):
    """Search entries of the Map module (dict form of the provider contract, SPEC 2.12)."""

    def computeEnabled():
        widget = _existingWidget()
        return widget is None or widget.computeState()[0]

    return [
        {"id": "lnm.open", "title": _("Lesion network mapping"), "category": _("Map"), "synonyms": ["lnm", "network map"],
         "callback": _openMap, "description": _("Open the Map workspace"), "icon": "waypoints"},
        {"id": "lnm.map-network", "title": _("Map network"), "category": _("Map"), "key": "Ctrl+Enter", "synonyms": ["compute network map", "run lnm"],
         "callback": lambda: _openMap(lambda widget: widget.onPrimary()), "enabled": computeEnabled,
         "description": _("Compute the network map of the lesion")},
        {"id": "lnm.add-connectome", "title": _("Add connectome…"), "category": _("Map"), "synonyms": ["connectome bundle", "add bundle", "register connectome"],
         "callback": lambda: _openMap(lambda widget: widget.onAddBundle()), "description": _("Register a connectome bundle (.lnmc folder)")},
        {"id": "lnm.manage-connectomes", "title": _("Manage connectomes…"), "category": _("Map"),
         "synonyms": ["connectome manager", "convert connectome", "lead-dbs connectome", "reference maps", "hubness"],
         "callback": lambda: _openMap(lambda widget: widget.openManager()), "description": _("Add, convert, check and remove connectome bundles")},
        {"id": "lnm.map-cohort", "title": _("Map all lesions (maps only)"), "category": _("Map"), "synonyms": ["cohort maps", "map cohort", "batch lnm"],
         "callback": lambda: _openMap(lambda widget: widget.computeCohort()), "enabled": lambda: (_existingWidget() is None or _existingWidget().cohortComputeState()[0]),
         "description": _("Compute the network map of every analysable lesion of the study")},
    ]


def registerPaletteProvider():
    """Register the Search entries when the Studio palette exists (startupCompleted; never under testing)."""
    try:
        from StudioLib import palette
    except Exception:
        return
    palette.registerProvider(paletteEntries)


def _existingWidget():
    """The module widget if it was created, else None (never creates it)."""
    module = getattr(slicer.modules, "lesionnetworkmapping", None)
    if module is None or not hasattr(slicer.modules, "LesionNetworkMappingWidget"):
        return None
    return slicer.modules.LesionNetworkMappingWidget


#
# Parameter node
#


@parameterNodeWrapper
class LesionNetworkMappingParameterNode:
    """The parameters of the Map module (SPEC 7.2), saved with the scene in a vtkMRMLScriptedModuleNode.

    seedMode - "lesion", "cohort", "coordinates" or "stimulation".
    seedSegmentation, seedSegmentId - the lesion seed (A-03b sets them too).
    studyPath - scenes of earlier versions: a study folder (read, never written: a study chosen with "Open study…" is kept
      in the fork-only setting Studio/LNM/CohortStudy, so scenes never hold its local path; SPEC 9.7 rule 10).
    connectome - the connectome bundle in use, as its portable identifier (``connectomeIdentifier``): scenes and
      .mrb files are shared, so they never hold a local path (SPEC 9.7 rule 10); the bundle folder is found on load
      among the registered bundles (``Studio/LNM/Connectomes``).
    connectomePath - scenes of earlier versions only: the bundle's absolute path, read on load and then cleared.
    subjectsMode - "all" or "preview" (previewN subjects at random with previewSeed).
    thresholdRule - the threshold rule as JSON (thresholds.py).
    statistic - the map shown: "T", "Fz" or "r"; sign - "both", "pos" or "neg".
    opacity - foreground opacity of the map; nullRelocations - relocated lesions of the specificity QA (0: off).
    resultVolume - the map shown.
    sphereSize, sphereSizeKind - the sphere of coordinate and stimulation-point seeds: sphereSize mm given as a "radius" or a
      "diameter" (explicit, both are shown; coords.sphere_radius).
    coordinateNull, coordinateNullK - the random-coordinate control of the Coordinates seed (off; k null sets).
    stimulationKind - "points", "efield" or "vta"; stimulationWeighting - its weighting (coords.STIMULATION_WEIGHTINGS);
    stimulationFlip - multiply the outcome by -1 for the R-map (TMS).
    """

    seedMode: str = "lesion"
    seedSegmentation: vtkMRMLSegmentationNode
    seedSegmentId: str = ""
    studyPath: str = ""
    connectome: str = ""
    connectomePath: str = ""
    subjectsMode: str = "all"
    previewN: int = 100
    previewSeed: int = 0
    thresholdRule: str = DEFAULT_RULE_JSON
    statistic: str = "T"
    sign: str = "both"
    opacity: float = 0.8
    nullRelocations: int = 50
    resultVolume: vtkMRMLScalarVolumeNode
    sphereSize: float = 4.0
    sphereSizeKind: str = "radius"
    coordinateNull: bool = False
    coordinateNullK: int = 1000
    stimulationKind: str = "points"
    stimulationWeighting: str = ""
    stimulationFlip: bool = False


#
# Logic
#


def _settingList(key):
    value = qt.QSettings().value(key)
    if value is None or value == "":
        return []
    if isinstance(value, str):
        return [value]
    return [str(item) for item in value if item]


def _safeName(text, default="lesion"):
    """Letters, digits and dashes of ``text`` (a BIDS-style label), or ``default``."""
    name = re.sub(r"[^A-Za-z0-9-]+", "", text or "")
    return name or default


def _lesionFallbackLabel(segNode, segmentName):
    """The label of a lesion mapped outside a study: its BIDS subject ("sub-01", read from the segmentation's name, the
    segment's name or the file it was loaded from), else the names of the node and the segment (not twice the same name).

    ``_safeName`` drops underscores, which are the separators of BIDS entities: without this a file named
    ``sub-01_space-MNI_desc-lesion_mask`` gave run and export names such as ``sub-01spaceMNIdesc-lesionmask-Lesion_conn-...``.
    """
    candidates = [segNode.GetName(), segmentName]
    storage = segNode.GetStorageNode()
    if storage is not None and storage.GetFileName():
        candidates.append(os.path.basename(storage.GetFileName()))
    try:
        from StudioLib import importer

        for text in candidates:
            subject = importer.bidsSubject(text)
            if subject:
                return subject
    except ImportError:  # Map without the Studio package: the names below
        pass
    nodeName = segNode.GetName()
    return nodeName if segmentName == nodeName else f"{nodeName}-{segmentName}"


class LesionNetworkMappingLogic(ScriptedLoadableModuleLogic):
    """Computation and data handling of the Map module, usable without the GUI (tests, scripts)."""

    #: {connectome identifier: local bundle path} of the bundles opened in this session (shared by all logic instances)
    _knownConnectomes = {}

    def __init__(self):
        ScriptedLoadableModuleLogic.__init__(self)
        self._bundleCache = {}

    def getParameterNode(self):
        return LesionNetworkMappingParameterNode(super().getParameterNode())

    #
    # Connectomes
    #

    @staticmethod
    def registeredConnectomes():
        """Paths of the registered connectome bundles (``Studio/LNM/Connectomes``), in registration order."""
        paths = []
        for path in _settingList(CONNECTOMES_SETTING):
            if path not in paths:
                paths.append(path)
        return paths

    @staticmethod
    def registerConnectome(path):
        """Validate a bundle (``ConnectomeBundle.open``) and add it to the registered list; return the bundle."""
        from LesionNetworkMappingLib.connectome import ConnectomeBundle

        bundle = ConnectomeBundle.open(path)
        paths = LesionNetworkMappingLogic.registeredConnectomes()
        if bundle.path not in paths:
            paths.append(bundle.path)
            qt.QSettings().setValue(CONNECTOMES_SETTING, paths)
        return bundle

    @staticmethod
    def unregisterConnectome(path):
        """Remove a bundle from the registered list (its files are kept).

        The folder is also forgotten among the bundles opened in this session, so ``resolveConnectome`` no longer finds it.
        """
        paths = [item for item in LesionNetworkMappingLogic.registeredConnectomes() if os.path.normpath(item) != os.path.normpath(path)]
        qt.QSettings().setValue(CONNECTOMES_SETTING, paths)
        known = LesionNetworkMappingLogic._knownConnectomes
        for identifier in [key for key, value in known.items() if os.path.normpath(value) == os.path.normpath(path)]:
            del known[identifier]

    @staticmethod
    def connectomeIdentifier(bundle):
        """Portable identifier of a connectome bundle, saved in scenes instead of its local path (SPEC 9.7 rule 10).

        ``"<name>#<fingerprint>"``: the bundle name and the first 16 hex digits of ``export.data_sha256`` (grid,
        subjects and format of connectome.json; no data file is read), so the same bundle in another folder or on
        another computer has the same identifier.
        """
        from LesionNetworkMappingLib.export import data_sha256

        return f"{bundle.name}#{data_sha256(bundle.metadata)[:16]}"

    @staticmethod
    def connectomeIdentifierName(identifier):
        """The bundle name of a connectome identifier (the whole text for one without a fingerprint)."""
        return (identifier or "").rsplit("#", 1)[0]

    def rememberConnectome(self, bundle):
        """Remember where the bundle of this session is (``resolveConnectome``); return its identifier."""
        identifier = self.connectomeIdentifier(bundle)
        LesionNetworkMappingLogic._knownConnectomes[identifier] = bundle.path
        return identifier

    def resolveConnectome(self, identifier):
        """Local folder of the connectome with this identifier, "" if it is not on this computer.

        Looks among the bundles opened in this session and the registered bundles (the fork-only setting
        ``Studio/LNM/Connectomes``, which keeps the local paths out of the scene).
        """
        if not identifier:
            return ""
        name = self.connectomeIdentifierName(identifier)
        nameOnly = "#" not in identifier  # a legacy scene whose bundle was missing: its folder name (legacyConnectomeName)
        known = LesionNetworkMappingLogic._knownConnectomes.get(identifier)
        candidates = ([known] if known else []) + [path for path in self.registeredConnectomes() if path != known]
        for path in candidates:
            try:
                bundle = self.openBundle(path)
            except Exception:
                continue
            if nameOnly:
                if name in (bundle.name, legacyConnectomeName(bundle.path)):
                    return bundle.path
            elif bundle.name == name and self.connectomeIdentifier(bundle) == identifier:
                return bundle.path
        return ""

    def openBundle(self, path):
        """The open ``ConnectomeBundle`` of ``path`` (cached while connectome.json is unchanged)."""
        from LesionNetworkMappingLib.connectome import ConnectomeBundle

        path = os.path.abspath(path)
        manifest = os.path.join(path, "connectome.json")
        stamp = os.stat(manifest).st_mtime_ns if os.path.isfile(manifest) else None
        cached = self._bundleCache.get(path)
        if cached is not None and cached[0] == stamp:
            return cached[1]
        bundle = ConnectomeBundle.open(path)
        self._bundleCache[path] = (stamp, bundle)
        return bundle

    @staticmethod
    def demoPath():
        return os.path.join(slicer.app.cachePath, "LNM", "demo.lnmc")

    def createDemoConnectome(self, path=None, nSubjects=DEMO_SUBJECTS, register=True, shape=DEMO_SHAPE, runs=DEMO_RUNS, seed=0, affine="demo"):
        """Write the synthetic demo connectome (planted networks, ``connectome.make_synthetic``) and register it.

        The default grid covers the MNI brain with 6 mm voxels and records the space ``DEMO_SPACE``;
        ``affine=None`` gives make_synthetic's 2 mm grid around the origin (no space). Returns the ``make_synthetic`` result (path, blobs...). It is labelled
        SYNTHETIC in its name, description and data use terms. This runs on the calling thread: the "Use the demo"
        button runs ``startDemoJob()`` instead.
        """
        result = writeDemoConnectome(path or self.demoPath(), nSubjects=nSubjects, shape=shape, runs=runs, seed=seed, affine=affine)
        self._bundleCache.pop(os.path.abspath(result["path"]), None)
        if register:
            self.registerConnectome(result["path"])
        return result

    def startDemoJob(self, path=None, onEvent=None, onDone=None, nSubjects=DEMO_SUBJECTS):
        """Write the demo connectome in a job of the shared job runner (``python -m LesionNetworkMapping demo``).

        The connectome is not registered here: ``onDone(job)`` does it when ``job.succeeded()``. Return the ``jobrunner.Job``.
        """
        from LesionNetworkMappingUI import jobrunner

        path = os.path.abspath(path or self.demoPath())
        self._bundleCache.pop(path, None)
        spec = jobrunner.JobSpec(
            "LesionNetworkMapping", ["demo", "--out", path, "--subjects", str(int(nSubjects))], title=_("Creating the demo"), heavy=False,
            kind="demo", runRoot=jobrunner.defaultRunRoot(), onEvent=onEvent, onDone=onDone, name="demo")
        return jobrunner.instance().submit(spec)

    @staticmethod
    def isSynthetic(bundle):
        text = f"{bundle.name} {bundle.description}".lower()
        return "synthetic" in text

    @staticmethod
    def manifestSha256(bundle):
        from LesionNetworkMappingLib.export import file_sha256

        return file_sha256(os.path.join(bundle.path, "connectome.json"))

    @staticmethod
    def termsSettingKey(bundle):
        return f"{ACCEPTED_TERMS_SETTING}/{LesionNetworkMappingLogic.manifestSha256(bundle)}"

    @staticmethod
    def termsAccepted(bundle):
        """Whether "I accept these data use terms" was ticked for this bundle (per manifest sha256)."""
        value = qt.QSettings().value(LesionNetworkMappingLogic.termsSettingKey(bundle))
        return str(value).lower() in ("true", "1")

    @staticmethod
    def setTermsAccepted(bundle, accepted):
        settings = qt.QSettings()
        key = LesionNetworkMappingLogic.termsSettingKey(bundle)
        if accepted:
            settings.setValue(key, "true")
        else:
            settings.remove(key)

    @staticmethod
    def connectomeLine(bundle):
        """The metadata line of a bundle, e.g. "GSP1000 v3.0 (doi:…) · N=1000 · 18-36 y · GSR · 292,019 vox · 2 mm · 126 GB"."""
        provenance = getattr(bundle, "provenance", {}) or {}
        source = provenance.get("source") or {}
        population = provenance.get("population") or {}
        gsr = (provenance.get("preprocessing") or {}).get("gsr")
        name = bundle.name
        if source.get("version"):
            name += f" v{source['version']}"
        if source.get("doi"):
            name += f" (doi:{source['doi']})"
        parts = [name, f"N={bundle.n_subjects:,}"]
        if population.get("ageRange"):
            ages = population["ageRange"]
            parts.append(f"{ages[0]}–{ages[1]} y" if isinstance(ages, (list, tuple)) and len(ages) == 2 else f"{ages} y")  # noqa: RUF001
        if gsr is True:
            parts.append("GSR")
        elif gsr is False:
            parts.append("no GSR")
        spacing = [abs(float(value)) for value in bundle.grid.spacing]
        resolution = f"{spacing[0]:g} mm" if max(spacing) - min(spacing) < 1e-3 else " × ".join(f"{value:g}" for value in spacing) + " mm"  # noqa: RUF001
        parts += [f"{bundle.n_voxels:,} vox", resolution, _formatBytes(bundle.data_size_bytes)]
        return " · ".join(parts)

    @staticmethod
    def gsr(bundle):
        """``preprocessing.gsr`` of the bundle as True, False or None (unknown)."""
        value = ((getattr(bundle, "provenance", {}) or {}).get("preprocessing") or {}).get("gsr")
        return value if value in (True, False) else None

    #
    # Seed
    #

    @staticmethod
    def defaultSeed(scene=None):
        """``(segmentationNode, segmentId)`` of the Studio "Lesion" segment, else the first segment; (None, None) when there is none."""
        scene = scene or slicer.mrmlScene
        first = (None, None)
        for node in slicer.util.getNodesByClass("vtkMRMLSegmentationNode", scene):
            segmentation = node.GetSegmentation()
            for index in range(segmentation.GetNumberOfSegments()):
                segmentId = segmentation.GetNthSegmentID(index)
                if segmentation.GetSegment(segmentId).GetName().lower() == "lesion":
                    return node, segmentId
                if first[0] is None:
                    first = (node, segmentId)
        return first

    @staticmethod
    def seedArray(segNode, segmentId):
        """The segment as (data uint8 indexed [i, j, k], 4x4 IJK→RAS affine) on **its own geometry** (the segmentation's reference geometry)."""
        import numpy as np

        labelmap = slicer.mrmlScene.AddNewNodeByClass("vtkMRMLLabelMapVolumeNode", "__lnm_seed__")
        labelmap.SetHideFromEditors(True)
        labelmap.SetSaveWithScene(False)
        try:
            segmentIds = vtk.vtkStringArray()
            segmentIds.InsertNextValue(segmentId)
            if not slicer.modules.segmentations.logic().ExportSegmentsToLabelmapNode(segNode, segmentIds, labelmap, None, slicer.vtkSegmentation.EXTENT_REFERENCE_GEOMETRY):
                raise RuntimeError(f"The segment {segmentId} could not be exported")
            matrix = vtk.vtkMatrix4x4()
            image = labelmap.GetImageData()
            if image is None or image.GetPointData().GetScalars() is None:
                # A segment that was never drawn exports to an image without voxels (zero extent, no scalars):
                # it is an all-zero mask on the segmentation's reference geometry
                geometry = slicer.vtkOrientedImageData()
                serialized = segNode.GetSegmentation().GetConversionParameter(slicer.vtkSegmentationConverter.GetReferenceImageGeometryParameterName())
                if serialized and slicer.vtkSegmentationConverter.DeserializeImageGeometry(serialized, geometry, False):
                    dims = geometry.GetDimensions()
                    geometry.GetImageToWorldMatrix(matrix)
                    return np.zeros((int(dims[0]), int(dims[1]), int(dims[2])), np.uint8), np.array([[matrix.GetElement(row, column) for column in range(4)] for row in range(4)])
                data = np.zeros((0, 0, 0), np.uint8)
            else:
                data = slicer.util.arrayFromVolume(labelmap)  # [k, j, i]
            labelmap.GetIJKToRASMatrix(matrix)
            affine = np.array([[matrix.GetElement(row, column) for column in range(4)] for row in range(4)])
            return (np.transpose(data, (2, 1, 0)) != 0).astype(np.uint8), affine
        finally:
            displayNode = labelmap.GetDisplayNode()
            if displayNode is not None and displayNode.GetColorNode() is not None:
                slicer.mrmlScene.RemoveNode(displayNode.GetColorNode())
            slicer.mrmlScene.RemoveNode(labelmap)

    def exportSeedLesion(self, segNode, segmentId, path):
        """Write the segment as a NIfTI mask at its own geometry (``nifti.write_nifti``); return the path."""
        from LesionNetworkMappingLib import nifti

        data, affine = self.seedArray(segNode, segmentId)
        os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
        nifti.write_nifti(path, data, affine, descrip="Lesion mask (Slicer Studio Map seed)")
        return path

    @staticmethod
    def seedSpace(segNode, data_shape, affine):
        """(space, resolution) of the seed's grid on a known template grid, or None (native space)."""
        try:
            from StudioLib import space as studioSpace

            for node in (segNode, segNode.GetNodeReference(slicer.vtkMRMLSegmentationNode.GetReferenceImageGeometryReferenceRole())):
                if node is not None and node.GetAttribute(studioSpace.SPACE_ATTRIBUTE):
                    return studioSpace.spaceOf(node)
            # A lesion on the grid of a volume whose space is known (one of your templates, also on a built-in grid such
            # as the FSL 2 mm grid added as MNI152Lin) is in that volume's space, not the grid's built-in space
            shared = studioSpace.sharedGridSpace(segNode)
            if shared is not None:
                return shared
        except Exception:
            pass
        from LesionNetworkMappingLib import geometry

        grid = (tuple(int(n) for n in data_shape), affine)
        detected = geometry.detect_space(grid)
        if detected is None:
            # The grid of one of the user's own Slicer Studio templates (also the anisotropic ones that geometry does not
            # register): a lesion file drawn on it and opened later has no Studio.Space attribute
            try:
                from StudioLib import space as studioSpace

                detected = studioSpace.spaceOf(grid)
                if detected is None and segNode is not None:
                    # A lesion on the grid of a volume whose space is known (a template not registered on this computer)
                    detected = studioSpace.spaceOf(segNode)
            except Exception:
                detected = None
        return detected

    @staticmethod
    def familyNotice(seedSpace, connectomeSpace):
        """The note for a lesion on a template of another MNI family than the connectome ("" when the families match or
        the connectome's family is not known). "MNI (other)" templates (space "MNI") are an unknown MNI family.
        """
        if not seedSpace or not connectomeSpace:
            return ""
        from LesionNetworkMappingLib import geometry

        seedName = seedSpace[0] if isinstance(seedSpace, (tuple, list)) else seedSpace
        connectomeFamily = geometry.space_family(connectomeSpace)
        if connectomeFamily in ("native", "unknown") or geometry.space_family(seedName) == connectomeFamily:
            return ""
        shown = _("MNI (other)") if seedName == "MNI" else seedName
        return _("The lesion is on {seed}, the connectome on {connectome}: the template families are a few millimetres apart, "
                 "so the map is approximate near subcortical structures.").format(seed=shown, connectome=connectomeSpace)

    def checkSeed(self, segNode, segmentId, bundle=None):
        """Check a seed against a connectome; return a dict.

        Keys: ``ok`` (bool), ``reason`` (why it cannot be mapped, or ""), ``kind`` ("", "empty", "native",
        "outside", "small"), ``space`` ((name, resolution) or None), ``volumeMl``, ``notice`` (a lesion on a template
        of another MNI family than the connectome, e.g. one of the user's own templates: it maps, with this note), and
        with a bundle ``qc`` (``engine.prepare_lesion``'s voxels_in_mask, weight_total, ...).
        """
        import numpy as np

        result = {"ok": False, "reason": "", "kind": "", "space": None, "volumeMl": 0.0, "qc": None, "notice": ""}
        if segNode is None or not segmentId or segNode.GetSegmentation().GetSegment(segmentId) is None:
            result.update(reason=_("Choose the lesion segment."), kind="none")
            return result
        data, affine = self.seedArray(segNode, segmentId)
        voxels = int(np.count_nonzero(data))
        result["volumeMl"] = voxels * abs(float(np.linalg.det(affine[:3, :3]))) / 1000.0
        if voxels == 0:
            result.update(reason=_("The lesion segment is empty: trace it in Draw first."), kind="empty")
            return result
        result["space"] = self.seedSpace(segNode, data.shape, affine)
        if bundle is None:
            result["ok"] = True
            return result
        from LesionNetworkMappingLib import engine, geometry

        connectomeSpace = geometry.detect_space((bundle.shape, bundle.affine))
        # A connectome on a non-standard grid may declare its template space (connectome.json "space": the demo)
        declaredSpace = (getattr(bundle, "metadata", None) or {}).get("space")
        templateConnectome = connectomeSpace is not None or geometry.space_family(declaredSpace) not in ("native", "unknown")
        if result["space"] is None and templateConnectome:
            result.update(reason=_("Native space: normalize to MNI first (see Normalize to MNI below). The lesion is not on a known MNI grid, so it cannot be mapped with an MNI connectome."), kind="native")
            return result
        if connectomeSpace is None:
            # A connectome on a non-standard grid (the synthetic demo, test bundles): the lesion must lie inside its grid
            gridCorners = np.array([[i, j, k, 1.0] for i in (0, bundle.shape[0] - 1) for j in (0, bundle.shape[1] - 1) for k in (0, bundle.shape[2] - 1)])
            gridBox = (bundle.affine @ gridCorners.T).T[:, :3]
            nonzero = np.argwhere(data)
            world = (affine[:3, :3] @ nonzero.T).T + affine[:3, 3]
            low, high = gridBox.min(axis=0) - 1.0, gridBox.max(axis=0) + 1.0
            if not np.all((world >= low) & (world <= high)):
                result.update(reason=_("The lesion lies outside the connectome's grid: it is not in the connectome's space."), kind="outside")
                return result
        result["notice"] = self.familyNotice(result["space"], connectomeSpace[0] if connectomeSpace else declaredSpace)
        qc = engine.prepare_lesion((data, affine), bundle)[1]
        result["qc"] = qc
        if qc.get("weight_total", 0.0) < 1.0:
            result.update(reason=_("Lesion smaller than one connectome voxel."), kind="small")
            return result
        if int(qc.get("voxels_in_mask", 0)) == 0:
            # On the grid but with no voxel in the connectome's brain mask: no time course to correlate (an all-zero map)
            result.update(reason=_("The lesion lies outside the connectome's brain mask: no connectome voxel to map from."), kind="outside")
            return result
        result["ok"] = True
        return result

    #
    # Runs
    #

    @staticmethod
    def runDirectory(context=None, lesionName="lesion"):
        """A new run folder: ``<study>/derivatives/lnm/runs/<time>_<lesion>`` with a study, else ``<cache>/LNM/runs/<time>_<lesion>``."""
        from LesionNetworkMappingUI import jobrunner

        if context is not None and getattr(context, "study", None) is not None:
            root = os.path.join(context.runRoot(), "runs")
        else:
            root = jobrunner.defaultRunRoot()
        stamp = time.strftime("%Y%m%d-%H%M%S")
        path = os.path.join(root, f"{stamp}_{lesionName}")
        counter = 2
        while os.path.exists(path):
            path = os.path.join(root, f"{stamp}-{counter}_{lesionName}")
            counter += 1
        return path

    @staticmethod
    def engineArguments(bundlePath, lesionPath, runDir, previewN=None, previewSeed=0, nullRelocations=50, rule=None, snapshotEvery=SNAPSHOT_EVERY):
        """Arguments of ``LesionNetworkMappingLib.engine`` for one lesion (the job runner adds --threads)."""
        from LesionNetworkMappingLib import thresholds

        args = ["--bundle", bundlePath, "--lesion", lesionPath, "--out", runDir, "--snapshot-every", str(int(snapshotEvery)),
                "--null-relocations", str(int(nullRelocations)), "--run-json", os.path.join(runDir, "run.json"),
                "--threshold-rule", thresholds.rule_to_json(rule)]
        if previewN:
            args += ["--subjects", str(int(previewN)), "--random", "--seed", str(int(previewSeed)), "--desc-suffix", f"PreviewN{int(previewN)}"]
        return args

    def startRun(self, config, onEvent=None, onDone=None, context=None):
        """Start the engine for one lesion through the shared job runner; return the ``jobrunner.Job``.

        ``config`` keys: bundlePath, lesionPath, runDir, previewN (None for all subjects), previewSeed,
        nullRelocations, rule. Stop is ``job.stop()`` (cancel file, then the worker is terminated).
        """
        from LesionNetworkMappingUI import jobrunner

        args = self.engineArguments(config["bundlePath"], config["lesionPath"], config["runDir"], config.get("previewN"), config.get("previewSeed", 0),
                                    config.get("nullRelocations", 50), config.get("rule"))
        os.makedirs(config["runDir"], exist_ok=True)
        spec = jobrunner.JobSpec(
            "LesionNetworkMapping", ["job", "LesionNetworkMappingLib.engine", *args], title=_("Mapping"), heavy=True, kind="engine",
            runRoot=config.get("runRoot") or os.path.dirname(config["runDir"]), onEvent=onEvent, onDone=onDone, name="engine",
            statusText=_mappingStatusText, nice=ENGINE_NICE, env={"SLICER_LNM_NICE": str(ENGINE_NICE)})
        runner = context.runner if context is not None else jobrunner.instance()
        return runner.submit(spec, context=context)

    @staticmethod
    def parseEvent(line):
        """The JSON event of an engine output line, or None."""
        text = (line or "").strip()
        if not text.startswith("{"):
            return None
        try:
            event = json.loads(text)
        except ValueError:
            return None
        return event if isinstance(event, dict) and isinstance(event.get("event"), str) else None

    @staticmethod
    def mapPaths(runDir, lesionName, bundleName, descSuffix=""):
        """{"AvgR", "AvgFz", "T": path} of a lesion's maps in a run folder."""
        from LesionNetworkMappingLib import engine

        return engine.output_paths(runDir, lesionName, bundleName, descSuffix)

    @staticmethod
    def readMap(path):
        """(data indexed [k, j, i] for Slicer, 4x4 IJK→RAS) of a NIfTI map (3D; a 4D map gives its first volume)."""
        import numpy as np

        from LesionNetworkMappingLib import nifti

        data, affine, _header = nifti.read_nifti(path)
        if data.ndim > 3:
            data = data.reshape(data.shape[:3] + (-1,))[..., 0]
        if data.dtype.kind == "f" and data.dtype != np.float32:
            data = data.astype(np.float32)
        return np.ascontiguousarray(np.transpose(data, (2, 1, 0))), affine

    def loadMap(self, path, name=None, volumeNode=None, saveWithScene=True, attributes=None):
        """Load a map (T/Fz/r, or a group map: uint8 binary, float percent or T) with its NIfTI affine.

        Updates ``volumeNode`` in place (``updateVolumeFromArray``, partial snapshots; one modified event)
        or adds a new scalar volume. The volume gets the node attribute ``LNM.Result`` = "1" (Draw hides
        such volumes) and the given ``attributes`` (a value of None removes the attribute).
        """
        from LesionNetworkMappingLib import display

        data, affine = self.readMap(path)
        if volumeNode is None or volumeNode.GetScene() is None:
            volumeNode = slicer.util.addVolumeFromArray(data, ijkToRAS=affine, name=name or os.path.basename(path), nodeClassName="vtkMRMLScalarVolumeNode")
            wasModifying = volumeNode.StartModify()
        else:
            wasModifying = volumeNode.StartModify()
            matrix = vtk.vtkMatrix4x4()
            for row in range(4):
                for column in range(4):
                    matrix.SetElement(row, column, float(affine[row, column]))
            current = vtk.vtkMatrix4x4()
            volumeNode.GetIJKToRASMatrix(current)
            if any(abs(current.GetElement(row, column) - matrix.GetElement(row, column)) > 1e-9 for row in range(4) for column in range(4)):
                volumeNode.SetIJKToRASMatrix(matrix)
            slicer.util.updateVolumeFromArray(volumeNode, data)
            if name:
                volumeNode.SetName(name)
        volumeNode.SetAttribute(display.RESULT_ATTRIBUTE, "1")
        for key, value in (attributes or {}).items():
            if value is None:
                volumeNode.RemoveAttribute(key)
            else:
                volumeNode.SetAttribute(key, str(value))
        volumeNode.SetSaveWithScene(bool(saveWithScene))
        volumeNode.EndModify(wasModifying)
        return volumeNode

    @staticmethod
    def connectomeSpaceName(bundle):
        """Template space of a connectome's maps (``Studio.Space`` of a Map result), None when it has none.

        The space declared in connectome.json ("space": also on grids that are not standard, such as the demo's, and
        on the user's own conversions), else the standard grid the connectome is on. A native or unknown space gives
        None: the map is then in no template space.
        """
        from LesionNetworkMappingLib import geometry

        if bundle is None:
            return None
        declared = (getattr(bundle, "metadata", None) or {}).get("space")
        if declared and geometry.space_family(declared) not in ("native", "unknown"):
            return str(declared)
        detected = geometry.detect_space((bundle.shape, bundle.affine))
        return str(detected[0]) if detected else None

    @staticmethod
    def maskedValues(volumeOrArray, bundle):
        """Values of a map (volume node, or array [k, j, i]) at the connectome mask voxels, in mask order."""
        import numpy as np

        array = slicer.util.arrayFromVolume(volumeOrArray) if hasattr(volumeOrArray, "GetImageData") else volumeOrArray
        ijk = np.transpose(np.asarray(array), (2, 1, 0))
        if tuple(ijk.shape) != tuple(bundle.shape):
            return np.asarray(array, dtype=np.float64).ravel()
        return ijk.ravel()[bundle.mask_indices].astype(np.float64)

    @staticmethod
    def resolveRule(rule, n, bundle, values=None, note=None):
        """``thresholds.resolve`` with the bundle's V and GSR flag (re-resolved on every N change)."""
        from LesionNetworkMappingLib import thresholds

        return thresholds.resolve(rule, n, bundle.n_voxels, note=note, gsr=LesionNetworkMappingLogic.gsr(bundle), values=values)

    @staticmethod
    def software():
        return {"slicer": slicer.app.applicationVersion, "fork_revision": slicer.app.revision}

    def exportRun(self, runDir, dest, rule=None, resolved=None, partial=False):
        """Export a run folder (maps, one sidecar per lesion, provenance.json, methods.md, reproduce.sh) into ``dest``.

        Like ``export.export_run``, with the resolved threshold of the display (a top-x% rule needs the map values).
        """
        from LesionNetworkMappingLib import export

        runJson = os.path.join(runDir, "run.json")
        if not os.path.isfile(runJson):
            raise FileNotFoundError(f"Run record not found: {runJson}")
        with open(runJson, encoding="utf-8") as f:
            runMeta = json.load(f)
        if runMeta.get("status") != "done":
            if not (partial and runMeta.get("status") == "running" and runMeta.get("snapshot_n") and runMeta.get("maps")):
                raise ValueError(f"The run in {runDir} did not finish (status {runMeta.get('status')!r})")
            runMeta.update({"n": runMeta["snapshot_n"], "cancelled": True, "subject_ids_sha256": None})
        qa = {}
        qaPath = runMeta.get("qa_json") or os.path.join(runDir, "qa.json")
        if runMeta.get("status") == "done" and os.path.isfile(qaPath):
            with open(qaPath, encoding="utf-8") as f:
                qa = json.load(f).get("lesions") or {}
        names = [entry["name"] for entry in runMeta["lesions"]]
        return export.write_run(dest, runMeta["maps"], names, runMeta["bundle"], rule=rule, resolved=resolved, qa=qa, run_meta=runMeta, software=self.software())

    @staticmethod
    def templateVolume(scene=None):
        """A template volume to show under maps (``Studio.Role`` = template), or None."""
        for node in slicer.util.getNodesByClass("vtkMRMLScalarVolumeNode", scene or slicer.mrmlScene):
            if node.GetAttribute("Studio.Role") == "template":
                return node
        return None

    #
    # Cohort
    #

    @staticmethod
    def isTemplateConnectome(bundle):
        """True for a connectome on a template (MNI) grid, or one that declares its template space (the demo)."""
        from LesionNetworkMappingLib import geometry

        if bundle is None:
            return False
        declared = (getattr(bundle, "metadata", None) or {}).get("space")
        return geometry.detect_space((bundle.shape, bundle.affine)) is not None or geometry.space_family(declared) not in ("native", "unknown")

    @classmethod
    def cohortSeeds(cls, study, bundle=None, includeUnreviewed=False):
        """The lesions of a study that the Cohort seed maps, and why the others are not mapped.

        Uses ``cohortmaps.study_lesions`` (``Study.analysis_rows``: include = 1, review approval when the study requires
        it, normalization QC). With a connectome on an MNI grid, lesions in native space are left out (they must be
        normalized to MNI first, as for a single lesion). Returns {lesions [(sid, path)], excluded {reason: [sids]},
        native [sids], groups {group: count}, n}.
        """
        from LesionNetworkMappingLib import cohortmaps
        from LesionNetworkMappingLib.study import detect_file_space, is_missing

        lesions, excluded = cohortmaps.study_lesions(study, includeUnreviewed)
        checkSpace = cls.isTemplateConnectome(bundle)
        kept, native = [], []
        for sid, path, _sha in lesions:
            row = study.subject(sid)
            space = row.get("space") if checkSpace else None
            if checkSpace and is_missing(space):
                try:
                    space = detect_file_space(path)
                except Exception:
                    space = None
            if space == "native":
                native.append(sid)
            else:
                kept.append((sid, path))
        groups = {}
        for sid, _path in kept:
            group = study.subject(sid).get("group") or "n/a"
            groups[group] = groups.get(group, 0) + 1
        return {"lesions": kept, "excluded": excluded, "native": native, "groups": groups, "n": len(kept)}

    @staticmethod
    def cohortOutputDir(studyPath, bundleName, n=None):
        """``<study>/derivatives/lnm/conn-<label>[_n-<N>]/cohort``: the cohort maps (maps.tsv) and the group maps."""
        from LesionNetworkMappingLib import export

        return os.path.join(export.derivatives_dir(studyPath, bundleName, n), COHORT_FOLDER)

    def startCohortMaps(self, config, onEvent=None, onDone=None, context=None):
        """Map the cohort's lesions with ``cohortmaps`` (batched engine passes, per-lesion cache) through the job runner.

        ``config`` keys: studyPath, bundlePath, outDir, lesions [(sid, path)] (written to <outDir>/lesions.tsv with paths
        relative to it), previewN, previewSeed. Returns the ``jobrunner.Job``.
        """
        from LesionNetworkMappingUI import jobrunner

        outDir = config["outDir"]
        os.makedirs(outDir, exist_ok=True)
        tsv = os.path.join(outDir, "lesions.tsv")
        lines = ["participant_id\tlesion"]
        for sid, path in config["lesions"]:
            relative = os.path.relpath(path, outDir) if os.path.splitdrive(path)[0] == os.path.splitdrive(outDir)[0] else path
            lines.append(f"{sid}\t{relative.replace(os.sep, '/')}")
        with open(tsv, "w", encoding="utf-8", newline="\n") as f:
            f.write("\n".join(lines) + "\n")
        args = ["--study", config["studyPath"], "--lesions-tsv", tsv, "--bundle", config["bundlePath"], "--out", outDir, "--resume"]
        if config.get("previewN"):
            args += ["--subjects", str(int(config["previewN"])), "--random", "--seed", str(int(config.get("previewSeed", 0)))]
        spec = jobrunner.JobSpec(
            "LesionNetworkMappingLib.cohortmaps", args, title=_("Mapping the cohort"), heavy=True, kind="cohortmaps", runRoot=config["studyPath"],
            onEvent=onEvent, onDone=onDone, name="cohortmaps", statusText=_mappingStatusText, nice=ENGINE_NICE)
        runner = context.runner if context is not None else jobrunner.instance()
        return runner.submit(spec, context=context)

    #
    # Map files
    #

    @staticmethod
    def mapFileInfo(path):
        """What a map file says about itself: {statistic, n, name, connectome (label), siblings {statistic: path}, sidecar, lesion}.

        The statistic comes from the engine's "desc" label (T, AvgRFz, AvgR), else the NIfTI intent (T for t and z maps);
        N from the sidecar (``<name>_conn-<label>[_desc-<suffix>]_lnm.json``), else from a T map's intent (df = N - 1).
        """
        from LesionNetworkMappingLib import geometry, nifti

        folder, base = os.path.split(os.path.abspath(path))
        match = re.match(r"^(?P<name>.+?)_conn-(?P<label>[A-Za-z0-9]+)_desc-(?P<desc>AvgRFz|AvgR|T)(?P<suffix>[A-Za-z0-9]*)_funcmap\.nii(?:\.gz)?$", base)
        info = {"path": os.path.abspath(path), "statistic": "T", "n": None, "name": re.sub(r"(?i)\.nii(\.gz)?$", "", base), "label": None, "connectome": None, "space": None,
                "siblings": {}, "sidecar": None, "lesion": None, "preview": False}
        if match is not None:
            info.update(statistic=DESC_STATISTICS[match.group("desc")], name=match.group("name"), connectome=match.group("label"), preview=match.group("suffix").startswith("PreviewN"))
            extension = ".nii.gz" if base.endswith(".gz") else ".nii"
            for desc, statistic in DESC_STATISTICS.items():
                sibling = os.path.join(folder, f"{match.group('name')}_conn-{match.group('label')}_desc-{desc}{match.group('suffix')}_funcmap{extension}")
                if os.path.isfile(sibling):
                    info["siblings"][statistic] = sibling
            descText = f"_desc-{match.group('suffix')}" if match.group("suffix") else ""
            sidecar = os.path.join(folder, f"{match.group('name')}_conn-{match.group('label')}{descText}_lnm.json")
            if os.path.isfile(sidecar):
                info["sidecar"] = sidecar
                try:
                    with open(sidecar, encoding="utf-8") as f:
                        record = json.load(f)
                    info["n"] = int(record["N"]) if record.get("N") else None
                    declared = (record.get("connectome") or {}).get("space")
                    if declared and geometry.space_family(declared) not in ("native", "unknown"):
                        info["space"] = str(declared)  # the connectome's template space, also on a non-standard grid
                    lesion = (record.get("lesion") or {}).get("file")
                    if lesion:
                        lesionPath = lesion if os.path.isabs(lesion) else os.path.normpath(os.path.join(folder, *lesion.split("/")))
                        info["lesion"] = lesionPath if os.path.isfile(lesionPath) else None
                except (OSError, ValueError, TypeError):
                    pass
        try:
            header = nifti.read_nifti_header(path)
        except Exception:
            header = None
        if header is not None:
            if match is None and header.get("intent_code") not in (3, 5):
                info["statistic"] = "r" if header.get("intent_code") == 2 else "T"
            if info["n"] is None and header.get("intent_code") == 3 and header["intent_params"][0] > 0:
                info["n"] = round(header["intent_params"][0]) + 1
        if info["n"] is None and info["siblings"].get("T") and os.path.normpath(info["siblings"]["T"]) != info["path"]:
            try:
                header = nifti.read_nifti_header(info["siblings"]["T"])  # an Fz or r map: the N of its T map
                if header.get("intent_code") == 3 and header["intent_params"][0] > 0:
                    info["n"] = round(header["intent_params"][0]) + 1
            except Exception:
                pass
        return info


#: Shortest time between two progress-row updates from job events (QProgressBar.setValue repaints synchronously)
PROGRESS_UPDATE_S = 0.1


def updateProgressQuietly(progressRow, force=False):
    """``progressRow.update()`` at most every 100 ms (``force``: now), with the bar repainted later instead of in the call.

    ``QProgressBar.setValue`` repaints at once; in the Studio inspector that costs about 30 ms per call, and a job's
    events arrive in bursts, so unthrottled updates blocked the application for 0.7 s (W3-08 measurement).
    """
    now = time.monotonic()
    if not force and now - getattr(progressRow, "_lnmUpdatedAt", 0.0) < PROGRESS_UPDATE_S:
        return False
    progressRow._lnmUpdatedAt = now
    bar = progressRow.bar
    bar.setUpdatesEnabled(False)
    try:
        progressRow.update()
    finally:
        bar.setUpdatesEnabled(True)  # schedules an ordinary (asynchronous) repaint
    return True


def _focusKey(focus):
    """Identity of a reported focus (study, position, space), to skip a focus imported twice."""
    return (focus.study, round(float(focus.x), 3), round(float(focus.y), 3), round(float(focus.z), 3), focus.space)


def _ownRadiusText(foci):
    """" · 2 foci use the radius from the file" when foci carry their own sphere radius (it overrides the Sphere row)."""
    own = sum(1 for focus in foci if getattr(focus, "radius_mm", None))
    if not own:
        return ""
    return " · " + (_("1 focus uses the radius from the file") if own == 1 else _("{n} foci use the radius from the file").format(n=own))


def _formatBytes(count):
    from LesionNetworkMappingLib.manager import format_bytes

    return format_bytes(count)


def cohortExcludedText(excluded):
    """"Not mapped: missing lesion (3) · include=0 (1)" from {reason: [participant ids]} ("" when none): the count follows
    the reason, so that no reason needs a plural ("3 missing lesion" was wrong), as in the Library card's "3 not used: ...".
    """
    parts = [f"{reason} ({len(sids)})" for reason, sids in excluded.items() if sids]
    return _("Not mapped: {parts}").format(parts=" · ".join(parts)) if parts else ""


def _mappingStatusText(job):
    """Status chip text of an engine job: "Mapping 34% · 2 min left"."""
    from LesionNetworkMappingUI import jobrunner

    text = _("Mapping")
    if job.progress is not None:
        text += f" {int(job.progress * 100)}%"
    eta = jobrunner.formatEta(job.eta)
    return f"{text} · {eta}" if eta else text


#
# Widget
#


class _FitHeightFilter(qt.QObject):
    """Keeps the minimum height of the module widget at the height its word-wrapped labels need.

    The module panel's scroll area sizes its widget from ``minimumSizeHint()``, which ignores
    height-for-width (wrapped labels); without this the cards would be squeezed below their size.
    """

    def __init__(self, widget):
        qt.QObject.__init__(self, widget)
        self.widget = widget
        self.timer = qt.QTimer(self)
        self.timer.setSingleShot(True)
        self.timer.setInterval(0)
        self.timer.connect("timeout()", self.fit)
        widget.installEventFilter(self)

    def eventFilter(self, obj, event):
        if event.type() in (qt.QEvent.LayoutRequest, qt.QEvent.Resize):
            self.timer.start()
        return False

    def fit(self):
        layout = self.widget.layout()
        if layout is None or not layout.hasHeightForWidth():
            return
        height = layout.totalHeightForWidth(self.widget.width)
        if height > 0 and height != self.widget.minimumHeight:
            self.widget.setMinimumHeight(height)


def _dataDirectory():
    """``Studio/LNM/DataDirectory`` (only read): A-03b's ``normalize_controller.dataDirectory`` (one default for both:
    ``<Slicer Studio folder>/LNM`` when unset, A-09).
    """
    try:
        from LesionNetworkMappingUI import normalize_controller

        return normalize_controller.dataDirectory()
    except ImportError:
        pass
    value = str(qt.QSettings().value(DATA_DIRECTORY_SETTING) or "").strip()
    if value:
        return value
    try:
        from StudioLib import projects

        if projects.isEnabled():
            return projects.lnmFolder()
    except ImportError:
        pass
    if os.environ.get("SLICER_STUDIO_WEB") or os.path.exists("/.dockerenv"):
        return "/data/SlicerStudio"
    documents = qt.QStandardPaths.writableLocation(qt.QStandardPaths.DocumentsLocation) or os.path.expanduser("~")
    return os.path.join(documents, "SlicerStudio")


def _pythonPackagesDirectory():
    """Where optional packages (h5py) are installed after the user agreed: ``<DataDirectory>/python-packages``."""
    return os.path.join(_dataDirectory(), "python-packages")


class ConvertConnectomeDialog(qt.QDialog):
    """Convert… of the connectome manager: the source (a NIfTI time series folder or a Lead-DBS connectome folder),
    its metadata and data use terms, the size and free-space estimate, then a resumable conversion job.
    """

    def __init__(self, manager, parent=None):
        qt.QDialog.__init__(self, parent)
        self.manager = manager
        self.estimateJob = None
        self.estimate = None
        self.setObjectName("LNMConvertDialog")
        self.setWindowTitle(_("Convert into a connectome bundle"))
        self.setMinimumWidth(520)
        layout = qt.QVBoxLayout(self)
        intro = qt.QLabel(_("Converts connectome data that is already on this computer into a bundle (.lnmc folder). Nothing is downloaded. "
                            "A stopped conversion keeps the subjects already written: Convert again with Resume ticked."))
        intro.setWordWrap(True)
        layout.addWidget(intro)
        form = qt.QFormLayout()
        self.sourceCombo = qt.QComboBox()
        self.sourceCombo.setObjectName("LNMConvertSource")
        for source, text in (("nifti", _("NIfTI time series folder")), ("leaddbs", _("Lead-DBS connectome folder"))):  # manager.SOURCES
            self.sourceCombo.addItem(text, source)
        self.sourceCombo.connect("currentIndexChanged(int)", self.onSourceChanged)
        form.addRow(_("Source"), self.sourceCombo)
        self.inputEdit, inputRow = self._pathRow("LNMConvertInput", self.onBrowseInput)
        form.addRow(_("Folder"), inputRow)
        self.maskEdit, self.maskRow = self._pathRow("LNMConvertMask", self.onBrowseMask)
        form.addRow(_("Mask"), self.maskRow)
        self.groupingEdit = qt.QLineEdit()
        self.groupingEdit.setObjectName("LNMConvertGrouping")
        self.groupingEdit.setPlaceholderText(_("optional: (?P<subject>sub-[A-Za-z0-9]+)_run"))
        self.groupingEdit.setToolTip(_("Regular expression: files with the same 'subject' group are runs of one subject"))
        form.addRow(_("Runs of a subject"), self.groupingEdit)
        self.nameEdit = qt.QLineEdit()
        self.nameEdit.setObjectName("LNMConvertName")
        form.addRow(_("Name"), self.nameEdit)
        self.outEdit, outRow = self._pathRow("LNMConvertOut", self.onBrowseOut)
        form.addRow(_("Bundle folder"), outRow)
        self.gsrCombo = qt.QComboBox()
        self.gsrCombo.setObjectName("LNMConvertGsr")
        for text, value in ((_("not stated"), "unknown"), (_("with global signal regression"), "true"), (_("without global signal regression"), "false")):
            self.gsrCombo.addItem(text, value)
        form.addRow(_("Preprocessing"), self.gsrCombo)
        layout.addLayout(form)
        layout.addWidget(qt.QLabel(_("Data use terms (shown before Compute; paste the provider's text):")))
        self.termsEdit = qt.QPlainTextEdit()
        self.termsEdit.setObjectName("LNMConvertTerms")
        self.termsEdit.setMaximumHeight(90)
        layout.addWidget(self.termsEdit)
        self.resumeCheckBox = qt.QCheckBox(_("Resume an interrupted conversion into this folder"))
        self.resumeCheckBox.setObjectName("LNMConvertResume")
        layout.addWidget(self.resumeCheckBox)
        self.estimateLabel = qt.QLabel("")
        self.estimateLabel.setObjectName("LNMConvertEstimate")
        self.estimateLabel.setWordWrap(True)
        layout.addWidget(self.estimateLabel)
        buttons = qt.QHBoxLayout()
        self.estimateButton = qt.QPushButton(_("Estimate size"))
        self.estimateButton.setObjectName("LNMConvertEstimateButton")
        self.estimateButton.connect("clicked()", self.runEstimate)
        buttons.addWidget(self.estimateButton)
        buttons.addStretch(1)
        self.convertButton = qt.QPushButton(_("Convert"))
        self.convertButton.setObjectName("LNMConvertButton")
        self.convertButton.setProperty("slicerRole", "primary")
        self.convertButton.connect("clicked()", self.onConvert)
        buttons.addWidget(self.convertButton)
        closeButton = qt.QPushButton(_("Cancel"))
        closeButton.connect("clicked()", self.close)
        buttons.addWidget(closeButton)
        layout.addLayout(buttons)
        self.onSourceChanged(0)

    def _pathRow(self, objectName, callback):
        row = qt.QWidget()
        rowLayout = qt.QHBoxLayout(row)
        rowLayout.setContentsMargins(0, 0, 0, 0)
        edit = qt.QLineEdit()
        edit.setObjectName(objectName)
        edit.connect("editingFinished()", self._inputsChanged)
        rowLayout.addWidget(edit, 1)
        button = qt.QToolButton()
        button.setText("…")
        button.connect("clicked()", callback)
        rowLayout.addWidget(button)
        return edit, row

    def source(self):
        return self.sourceCombo.currentData or "nifti"

    def onSourceChanged(self, index):
        nifti = self.source() == "nifti"
        self.maskRow.setEnabled(nifti)
        self.groupingEdit.setEnabled(nifti)
        self._inputsChanged()

    def _inputsChanged(self):
        self.estimate = None
        self.estimateLabel.setText(_("Estimate the size before converting: a GSP1000-size bundle needs about 126 GB."))
        path = self.inputEdit.text.strip()
        if path and not self.nameEdit.text.strip():
            self.nameEdit.setText(os.path.basename(path.rstrip("/\\")) or "connectome")
        if path and not self.outEdit.text.strip():
            name = LesionNetworkMappingLogic.connectomeIdentifierName(self.nameEdit.text.strip() or "connectome")
            self.outEdit.setText(os.path.join(_dataDirectory(), "connectomes", f"{_safeName(name, 'connectome')}.lnmc"))

    def onBrowseInput(self):
        path = qt.QFileDialog.getExistingDirectory(self, _("Choose the folder of the time series") if self.source() == "nifti" else _("Choose the Lead-DBS connectome folder"),
                                                   self.inputEdit.text)
        if path:
            self.inputEdit.setText(path)
            self._inputsChanged()

    def onBrowseMask(self):
        path = qt.QFileDialog.getOpenFileName(self, _("Choose the mask of the connectome grid"), self.inputEdit.text, "NIfTI (*.nii.gz *.nii)")
        if path:
            self.maskEdit.setText(path)
            self._inputsChanged()

    def onBrowseOut(self):
        path = qt.QFileDialog.getExistingDirectory(self, _("Choose where the bundle folder is written"), os.path.dirname(self.outEdit.text))
        if path:
            name = _safeName(self.nameEdit.text.strip() or "connectome", "connectome")
            self.outEdit.setText(os.path.join(path, f"{name}.lnmc"))
            self._inputsChanged()

    def sourceArguments(self):
        args = ["--source", self.source(), "--input", self.inputEdit.text.strip()]
        if self.source() == "nifti" and self.maskEdit.text.strip():
            args += ["--mask", self.maskEdit.text.strip()]
        packages = _pythonPackagesDirectory()
        if os.path.isdir(packages):
            args += ["--python-packages", packages]
        return args

    def runEstimate(self, then=None):
        """The size of the bundle and the free space (a light job that reads only headers)."""
        from LesionNetworkMappingUI import jobrunner

        if not self.inputEdit.text.strip():
            self.estimateLabel.setText(_("Choose the folder to convert."))
            return None
        args = ["estimate", *self.sourceArguments()]
        if self.outEdit.text.strip():
            args += ["--out", self.outEdit.text.strip()]
        self.estimateLabel.setText(_("Estimating…"))

        def onDone(job):
            self.estimateJob = None
            result = next((event for event in job.results if event.get("kind") == "estimate"), None)
            if not job.succeeded() or result is None:
                self.estimateLabel.setText(_("The estimate failed: {reason}").format(reason=job.failureReason or _("unknown error")))
                self.manager.offerPackages(job)
                return
            self.estimate = result
            self.estimateLabel.setText(self.estimateText(result))
            if then is not None:
                then()

        spec = jobrunner.JobSpec("LesionNetworkMappingLib.manager", args, title=_("Estimate"), heavy=False, kind="convert-estimate", name="estimate",
                                 runRoot=jobrunner.defaultRunRoot(), onDone=onDone)
        self.estimateJob = jobrunner.instance().submit(spec)
        return self.estimateJob

    @staticmethod
    def estimateText(estimate):
        text = _("About {size} for {runs} runs ({points:,} time points, {voxels:,} voxels)").format(
            size=estimate["size"], runs=estimate["runs"], points=estimate["time_points"], voxels=estimate["n_voxels"])
        if not estimate.get("exact"):
            text += " " + _("(estimated from a sample of the runs)")
        if estimate.get("free"):
            text += " · " + _("{free} free").format(free=estimate["free"])
            if estimate.get("enough") is False:
                text += " · " + _("not enough space")
        return text

    def onConvert(self):
        if self.estimate is None:
            self.runEstimate(then=self.onConvert)
            return
        if self.estimate.get("enough") is False and not self.resumeCheckBox.checked:
            slicer.util.errorDisplay(self.estimateText(self.estimate), windowTitle=_("Not enough free space"))
            return
        args = ["convert", *self.sourceArguments(), "--out", self.outEdit.text.strip(), "--gsr", self.gsrCombo.currentData or "unknown"]
        if self.nameEdit.text.strip():
            args += ["--name", self.nameEdit.text.strip()]
        if self.source() == "nifti" and self.groupingEdit.text.strip():
            args += ["--runs-grouping", self.groupingEdit.text.strip()]
        terms = self.termsEdit.toPlainText().strip()
        if terms:
            from LesionNetworkMappingUI import jobrunner

            folder = os.path.join(jobrunner.defaultRunRoot(), "convert")
            os.makedirs(folder, exist_ok=True)
            termsPath = os.path.join(folder, f"terms-{time.strftime('%Y%m%d-%H%M%S')}.txt")  # read by the job into connectome.json
            with open(termsPath, "w", encoding="utf-8") as f:
                f.write(terms + "\n")
            args += ["--terms-file", termsPath]
        if self.resumeCheckBox.checked:
            args.append("--resume")
        self.manager.startConversion(args, self.outEdit.text.strip())
        self.close()


class ConnectomeManagerDialog(qt.QDialog):
    """The connectome manager (Manage… of the Connectome card): the registered bundles and their actions.

    Lists every bundle registered on this computer (``Studio/LNM/Connectomes``: local paths stay in the settings, never
    in scenes) with its subjects, time points, voxels, size, space, terms and reference maps, and the provenance line of
    the selected one. Actions: Add bundle…, Convert… (a resumable job), Build reference maps… (time and disk estimate
    first, never automatic: D-A20), Build hubness map (the degree job), Remove from the list (the files are kept),
    Create synthetic demo, and the ``manager_*.py`` plug-in actions (the catalog and fetcher of later work packages).
    Non-modal; every job runs through the shared job runner with progress and Stop.
    """

    COLUMNS = (_("Name"), _("Subjects"), _("Time points"), _("Voxels"), _("Size"), _("Space"), _("Terms"), _("Reference"))

    def __init__(self, widget, parent=None):
        qt.QDialog.__init__(self, parent)
        self.widget = widget
        self.logic = widget.logic
        self.job = None
        self.rows = []
        self.convertDialog = None
        self.setObjectName("LNMConnectomeManager")
        self.setWindowTitle(_("Connectomes"))
        self.setMinimumSize(720, 420)
        layout = qt.QVBoxLayout(self)
        intro = qt.QLabel(_("Connectome bundles registered on this computer. Connectomes are never bundled or downloaded automatically; "
                            "register a bundle you have, or convert data you have into one."))
        intro.setWordWrap(True)
        layout.addWidget(intro)
        self.table = widget.widgets.tableView(list(self.COLUMNS))
        self.table.setObjectName("LNMManagerTable")
        self.table.connect("itemSelectionChanged()", self.onSelectionChanged)
        layout.addWidget(self.table, 1)
        self.provenanceLabel = qt.QLabel("")
        self.provenanceLabel.setObjectName("LNMManagerProvenance")
        self.provenanceLabel.setWordWrap(True)
        self.provenanceLabel.setTextInteractionFlags(qt.Qt.TextSelectableByMouse)
        layout.addWidget(self.provenanceLabel)
        rowA = qt.QHBoxLayout()
        self.addButton = self._button(rowA, _("Add bundle…"), "LNMManagerAddButton", widget.onAddBundle, _("Register a bundle folder (.lnmc) on this computer"))
        self.convertButton = self._button(rowA, _("Convert…"), "LNMManagerConvertButton", self.openConvert, _("Convert NIfTI time series or a Lead-DBS connectome into a bundle"))
        self.demoButton = self._button(rowA, _("Create synthetic demo"), "LNMManagerDemoButton", widget.onCreateDemo, _("SYNTHETIC — not real data"))
        rowA.addStretch(1)
        layout.addLayout(rowA)
        rowB = qt.QHBoxLayout()
        self.referenceButton = self._button(rowB, _("Build reference maps…"), "LNMManagerReferenceButton", self.buildReference,
                                            _("μC_r, PC1-3 and hubness of the selected connectome (lnm-reference-v1), for the QA of every map"))
        self.hubnessButton = self._button(rowB, _("Build hubness map"), "LNMManagerHubnessButton", self.buildHubness, _("The degree map (mean |Fz| to 1000 seeds)"))
        self.removeButton = self._button(rowB, _("Remove from the list"), "LNMManagerRemoveButton", self.removeSelected, _("Unregister the bundle (its files are kept)"))
        self.pluginButtons = []
        try:
            from LesionNetworkMappingUI import discoverManagerActions

            for spec in discoverManagerActions():
                button = self._button(rowB, str(spec["label"]), f"LNMManagerAction_{spec['id']}", lambda spec=spec: self.runPluginAction(spec), "")
                # "always": the action needs no selected connectome (Get a connectome… is how a first one is obtained)
                button.setProperty("lnmAlways", bool(spec.get("always")))
                self.pluginButtons.append(button)
        except Exception:
            logging.exception("Lesion network mapping: the connectome actions could not be discovered")
        rowB.addStretch(1)
        layout.addLayout(rowB)
        self.progress = widget.widgets.progressRow(objectNamePrefix="LNMManager")
        self.progress.widget.hide()
        layout.addWidget(self.progress.widget)
        self.statusLabel = qt.QLabel("")
        self.statusLabel.setObjectName("LNMManagerStatus")
        self.statusLabel.setWordWrap(True)
        layout.addWidget(self.statusLabel)
        closeRow = qt.QHBoxLayout()
        closeRow.addStretch(1)
        closeButton = qt.QPushButton(_("Close"))
        closeButton.connect("clicked()", self.close)
        closeRow.addWidget(closeButton)
        layout.addLayout(closeRow)
        self.refresh()

    def _button(self, row, text, objectName, callback, toolTip):
        button = qt.QPushButton(text)
        button.setObjectName(objectName)
        button.setProperty("slicerRole", "secondary")
        if toolTip:
            button.setToolTip(toolTip)
        button.connect("clicked()", callback)
        row.addWidget(button)
        return button

    def refresh(self, select=None):
        """Re-read the registered bundles (``manager.bundle_summary``) and fill the table."""
        from LesionNetworkMappingLib import manager as managerLib

        current = select or self.selectedPath() or self.widget.connectomePath()
        self.rows = [managerLib.bundle_summary(path) for path in self.logic.registeredConnectomes()]
        table = self.table
        table.setRowCount(len(self.rows))
        selectRow = -1
        for index, row in enumerate(self.rows):
            if row.get("error"):
                values = [row["name"], "—", "—", "—", "—", "—", "—", _("cannot be opened")]
                terms = None
            else:
                try:
                    accepted = self.logic.termsAccepted(self.logic.openBundle(row["path"]))
                except Exception:
                    accepted = False
                terms = _("accepted") if accepted else _("not accepted")
                name = row["name"] + (f" ({DEMO_LABEL})" if row.get("synthetic") else "")
                values = [name, f"{row['n_subjects']:,}", f"{row['time_points']:,}", f"{row['n_voxels']:,}", row["size"], row.get("space") or "—", terms,
                          _("yes") if row.get("has_reference") else _("no")]
            for column, value in enumerate(values):
                item = qt.QTableWidgetItem(str(value))
                item.setToolTip(row["path"] if column == 0 else str(value))
                table.setItem(index, column, item)
            if current and os.path.normpath(row["path"]) == os.path.normpath(current):
                selectRow = index
        if selectRow < 0 and self.rows:
            selectRow = 0
        if selectRow >= 0:
            table.selectRow(selectRow)
        self.onSelectionChanged()

    def selectedRow(self):
        rows = self.table.selectionModel().selectedRows() if self.table.selectionModel() is not None else []
        index = rows[0].row() if rows else -1
        return self.rows[index] if 0 <= index < len(self.rows) else None

    def selectedPath(self):
        row = self.selectedRow()
        return row["path"] if row is not None else None

    def onSelectionChanged(self):
        from LesionNetworkMappingLib import manager as managerLib

        row = self.selectedRow()
        busy = self.job is not None and not self.job.isFinished()
        ok = row is not None and not row.get("error")
        self.provenanceLabel.setText(managerLib.provenance_line(row) if row is not None else _("No connectome registered: Get a connectome…, Add bundle…, Convert… or Create synthetic demo."))
        self.referenceButton.setEnabled(ok and not busy)
        self.hubnessButton.setEnabled(ok and not busy and not row.get("has_degree"))
        self.hubnessButton.setToolTip(_("This connectome has a hubness (degree) map") if ok and row.get("has_degree") else _("The degree map (mean |Fz| to 1000 seeds)"))
        self.removeButton.setEnabled(row is not None)
        self.convertButton.setEnabled(not busy)
        for button in self.pluginButtons:
            button.setEnabled(ok or bool(button.property("lnmAlways")))

    #
    # Jobs
    #

    def detachJobs(self):
        """Stop calling back into this dialog (and its Convert dialog): the module is cleaned up while a job may still run."""
        jobs = [self.job]
        if self.convertDialog is not None:
            jobs.append(self.convertDialog.estimateJob)
            self.convertDialog.estimateJob = None
        for job in jobs:
            if job is not None and not job.isFinished():
                job.spec.onDone = None
                job.spec.onEvent = None
        self.job = None
        self.progress.setJob(None)

    def _submit(self, spec, done):
        from LesionNetworkMappingUI import jobrunner

        def onDone(job):
            updateProgressQuietly(self.progress, force=True)
            self.job = None
            try:
                done(job)
            finally:
                self.onSelectionChanged()

        spec.onDone = onDone
        spec.onEvent = lambda event: updateProgressQuietly(self.progress, force=event.get("event") != "progress")
        self.job = jobrunner.instance().submit(spec)
        self.progress.setJob(self.job)
        self.progress.widget.show()
        self.onSelectionChanged()
        return self.job

    def openConvert(self):
        if self.convertDialog is None:
            self.convertDialog = ConvertConnectomeDialog(self, self)
        self.convertDialog.show()
        self.convertDialog.raise_()
        return self.convertDialog

    def startConversion(self, args, outPath):
        """Run ``manager convert`` (resumable, with progress and Stop); register the bundle when it is written."""
        from LesionNetworkMappingUI import jobrunner

        self.statusLabel.setText(_("Converting into {path}…").format(path=outPath))

        def done(job):
            if job.succeeded():
                try:
                    bundle = self.logic.registerConnectome(outPath)
                except Exception as exc:
                    self.statusLabel.setText(_("The bundle was written but cannot be opened: {error}").format(error=exc))
                    return
                self.statusLabel.setText(_("Converted and registered: {name}. Accept its data use terms in the Connectome card to map.").format(name=bundle.name))
                self.widget.refreshConnectomes(select=bundle.path)
                self.refresh(select=bundle.path)
            elif job.state == "cancelled":
                self.statusLabel.setText(_("Stopped: the subjects already written are kept. Convert again with Resume ticked to continue."))
            else:
                self.statusLabel.setText(_("The conversion failed: {reason}").format(reason=job.failureReason))
                self.offerPackages(job, retry=lambda: self.startConversion(self._withPackages(args), outPath))

        spec = jobrunner.JobSpec("LesionNetworkMappingLib.manager", args, title=_("Converting the connectome"), heavy=True, kind="convert", name="convert",
                                 runRoot=jobrunner.defaultRunRoot())
        return self._submit(spec, done)

    @staticmethod
    def _withPackages(args):
        args = list(args)
        if "--python-packages" not in args:
            args += ["--python-packages", _pythonPackagesDirectory()]
        return args

    def offerPackages(self, job, retry=None):
        """A MATLAB v7.3 connectome needs h5py: install it only after the user agrees (never under tests)."""
        error = job.errorEvent or {}
        if error.get("needs") != "h5py" or slicer.app.testingEnabled():
            return False
        target = _pythonPackagesDirectory()
        if not slicer.util.confirmYesNoDisplay(
                _("These MATLAB v7.3 files can be read with the h5py package (a few MB from the Python Package Index, PyPI). "
                  "Install h5py into {folder}? It is used only by connectome conversions.").format(folder=target), windowTitle=_("Install h5py")):
            return False
        try:
            os.makedirs(target, exist_ok=True)
            with slicer.util.WaitCursor():
                slicer.util.pip_install(["--no-deps", "--target", target, "h5py"])
        except Exception as exc:
            slicer.util.errorDisplay(_("h5py could not be installed: {error}").format(error=exc), windowTitle=_("Install h5py"))
            return False
        if retry is not None:
            retry()
        return True

    def buildHubness(self):
        """The degree ("hubness") map of the selected connectome (``qa degree``)."""
        from LesionNetworkMappingUI import jobrunner

        path = self.selectedPath()
        if not path:
            return None
        self.statusLabel.setText(_("Building the hubness map…"))

        def done(job):
            self.statusLabel.setText(_("Hubness map built.") if job.succeeded() else _("The hubness map could not be built: {reason}").format(reason=job.failureReason))
            self.refresh()

        spec = jobrunner.JobSpec("LesionNetworkMapping", ["job", "LesionNetworkMappingLib.qa", "degree", "--bundle", path], title=_("Hubness map"), heavy=True,
                                 kind="degree", name="degree", runRoot=jobrunner.defaultRunRoot())
        return self._submit(spec, done)

    def buildReference(self, confirm=True):
        """Reference maps (``reference build``): estimate the time and disk use first and ask (D-A20); never automatic."""
        from LesionNetworkMappingUI import jobrunner

        path = self.selectedPath()
        if not path:
            return None
        self.statusLabel.setText(_("Estimating the reference build…"))

        def estimated(job):
            info = next((event for event in job.results if event.get("kind") == "estimate"), None)
            if not job.succeeded() or info is None:
                self.statusLabel.setText(_("The reference build cannot be estimated: {reason}").format(reason=job.failureReason))
                return
            seconds = info.get("seconds")
            minutes = max(1, round(seconds / 60)) if seconds else None
            disk = int(info.get("output_bytes") or 0) + int(info.get("n_voxels", 0)) * 4 * int(info.get("columns") or 10) * 2
            text = _("Build reference maps ({time})? They read the connectome {passes} times ({read}) and use about {disk} of disk in the bundle folder.").format(
                time=_("~{m} min").format(m=minutes) if minutes else _("time unknown"), passes=info.get("passes"), read=_formatBytes(int(info.get("read_bytes") or 0)),
                disk=_formatBytes(disk))
            self.lastReferenceEstimate = dict(info, disk_bytes=disk, text=text)
            if confirm and not slicer.util.confirmYesNoDisplay(text, windowTitle=_("Build reference maps")):
                self.statusLabel.setText(_("Reference maps not built."))
                return
            self._startReference(path)

        spec = jobrunner.JobSpec("LesionNetworkMapping", ["job", "LesionNetworkMappingLib.reference", "estimate", "--bundle", path], title=_("Estimate"), heavy=False,
                                 kind="reference-estimate", name="reference-estimate", runRoot=jobrunner.defaultRunRoot(), onDone=estimated)
        self.job = jobrunner.instance().submit(spec)
        return self.job

    def _startReference(self, path):
        from LesionNetworkMappingUI import jobrunner

        self.statusLabel.setText(_("Building the reference maps…"))

        def done(job):
            if job.succeeded():
                self.statusLabel.setText(_("Reference maps built."))
            elif job.state == "cancelled":
                self.statusLabel.setText(_("Stopped: Build reference maps again to resume."))
            else:
                self.statusLabel.setText(_("The reference maps could not be built: {reason}").format(reason=job.failureReason))
            self.refresh()

        spec = jobrunner.JobSpec("LesionNetworkMappingLib.reference", ["build", "--bundle", path, "--resume"], title=_("Reference maps"), heavy=True,
                                 kind="reference", name="reference", runRoot=path)
        return self._submit(spec, done)

    def removeSelected(self):
        path = self.selectedPath()
        if not path:
            return
        inUse = False
        if os.path.normpath(path) == os.path.normpath(self.widget.connectomePath() or ""):
            inUse = self.widget.onRemoveBundle()
        else:
            self.logic.unregisterConnectome(path)
            self.widget.refreshConnectomes()
        text = _("Removed from the list (the files are kept): {path}").format(path=path)
        if inUse:
            text += " " + _("The open project uses this connectome: it keeps naming it (shown as not registered) until you add its folder again with Add bundle…")
        self.statusLabel.setText(text)
        self.refresh()

    def runPluginAction(self, spec):
        try:
            spec["factory"](self.widget.ctx, self.selectedPath())
        except Exception as exc:
            logging.exception(f"Lesion network mapping: the connectome action {spec['id']} failed")
            slicer.util.errorDisplay(str(exc), windowTitle=str(spec["label"]))
        self.refresh()


class LesionNetworkMappingWidget(ScriptedLoadableModuleWidget, VTKObservationMixin):
    """The Map inspector: Seed, Connectome, Compute and Result cards, plug-in cards and the disclaimer footer."""

    def __init__(self, parent=None):
        ScriptedLoadableModuleWidget.__init__(self, parent)
        VTKObservationMixin.__init__(self)
        self.logic = None
        self.ctx = None
        self._parameterNode = None
        self.bundle = None
        self.bundleError = None
        #: Local folder of the connectome in use (the parameter node holds its portable identifier only)
        self._connectomePath = ""
        self.seedCheck = None
        self.job = None
        self.lesionName = None
        self.runDir = None
        self.runOutputs = {}
        self.runN = None
        self.runPartial = False
        self.runPreviewN = None
        self.runDescSuffix = ""
        #: {"runDir", "reason", "outputsFailed"} of the last run that failed after a map ("_shownRunFailure()")
        self._runFailure = None
        #: The connectome the shown run was computed with: its V, mask and name belong to the run, not to the one selected later
        self._runBundle = None
        #: {connectome folder: run state} of runs parked when another connectome was chosen (they come back with their connectome)
        self._parkedRuns = {}
        self.resolved = None
        self.lastPassing = None
        self._mapStamp = {}
        self._valuesCache = {}
        self._previousRun = None
        self._outlineState = None
        self._observedSeed = None
        self._updatingGui = False
        self._controllers = []
        self._cardWidgets = {}
        #: {step key: (state, summary)} last shown by _updateSteps(): Studio collapses a step when it becomes done
        self._stepStates = {}
        #: Studio: the row above the steps that holds the seed modes (they stay at hand when Seed collapses)
        self._seedModeRow = None
        #: The panel has the Studio look (``setStudioPresentation``): set when Map is entered in Studio, cleared when left
        self._studioLook = False
        self._statusChipText = None
        self._footerInShell = False
        self._ruleOverride = False
        self._entered = False
        self._peaksPending = False
        self._seedDirty = True
        self._pendingProgress = None
        self._pendingReload = False
        self._refreshGeneration = 0
        self._preloading = False
        self._pumpTimer = None
        #: Cohort seed: the study, what it maps (``cohortSeeds``), the cohort map job and its maps.tsv
        self.cohortStudy = None
        self.cohortInfo = None
        self.cohortJob = None
        self.cohortMapsPath = None
        #: Coordinates and Stimulation seeds: their finished seed maps (maps.tsv) and the null and R-map jobs
        self.coordinateMapsPath = None
        self.stimulationMapsPath = None
        self.coordinateNullJob = None
        self._coordNullReasonShown = False
        self.stimulationRmapJob = None
        #: A map shown from a file or found in the scene, not from a run of this session ({path, statistic, n, name, ...})
        self.loadedMap = None
        self.managerDialog = None

    #
    # Setup
    #

    def setup(self):
        ScriptedLoadableModuleWidget.setup(self)
        from LesionNetworkMappingUI import context as contextModule
        from LesionNetworkMappingUI import widgets

        self.widgets = widgets
        self.logic = LesionNetworkMappingLogic()
        self.ctx = contextModule.MapContext(logic=self.logic)
        self.ctx.setFocusCardHandler(self._focusCard)
        self.ctx.computeEnabledChanged.append(self.updateComputeState)
        self.ctx.primaryOverrideChanged.append(lambda mode: self.updateComputeState())
        slicer.modules.LesionNetworkMappingWidget = self

        self.seedTimer = qt.QTimer()
        self.seedTimer.setSingleShot(True)
        self.seedTimer.setInterval(400)
        self.seedTimer.connect("timeout()", self.updateSeed)
        self.progressTimer = qt.QTimer()
        self.progressTimer.setSingleShot(True)
        self.progressTimer.setInterval(100)
        self.progressTimer.connect("timeout()", self._showPendingProgress)
        self.refreshTimer = qt.QTimer()
        self.refreshTimer.setSingleShot(True)
        self.refreshTimer.setInterval(0)
        self.refreshTimer.connect("timeout()", self._onRefreshTimer)

        self._buildCards()

        # Footer: the research-only disclaimer, outside every card and always visible
        self.footer = widgets.disclaimerLabel()
        self.layout.addStretch(1)
        self.layout.addWidget(self.footer)
        self.shellFooter = None
        self._pinnedPrimarySlot = None
        #: (index of the primary button, index of its reason line) in the Compute card while they are pinned in the footer
        self._pinnedIndexes = None
        self._fitFilter = _FitHeightFilter(self.parent)

        self.addObserver(slicer.mrmlScene, slicer.mrmlScene.StartCloseEvent, self.onSceneStartClose)
        self.addObserver(slicer.mrmlScene, slicer.mrmlScene.EndCloseEvent, self.onSceneEndClose)
        self.addObserver(slicer.mrmlScene, slicer.mrmlScene.NodeAddedEvent, self.onNodeAdded)
        self.initializeParameterNode()
        self.refreshConnectomes()
        if self._shell() is not None:
            # Created while Studio is shown: the Studio look from the start (the inspector width is measured on it)
            self.setStudioPresentation(True, refresh=False)

    def _buildCards(self):
        """Main cards and discovered plug-in cards, in order (SPEC 7.9 card order)."""
        import LesionNetworkMappingUI as plugins

        main = [
            {"id": "seed", "order": plugins.ORDER_SEED, "build": self._buildSeedCard, "kind": "card", "modes": plugins.SEED_MODES},
            {"id": "connectome", "order": plugins.ORDER_CONNECTOME, "build": self._buildConnectomeCard, "kind": "card", "modes": plugins.SEED_MODES},
            {"id": "compute", "order": plugins.ORDER_COMPUTE, "build": self._buildComputeCard, "kind": "card", "modes": plugins.SEED_MODES},
            {"id": "result", "order": plugins.ORDER_RESULT, "build": self._buildResultCard, "kind": "card", "modes": plugins.SEED_MODES},
        ]
        try:
            self.pluginSpecs = plugins.discoverCards()
        except Exception:
            logging.exception("Lesion network mapping: card discovery failed")
            self.pluginSpecs = []
        mainIds = {spec["id"] for spec in main}
        specs = main + [spec for spec in self.pluginSpecs if spec["id"] not in mainIds]
        specs.sort(key=lambda spec: (spec["order"], spec["id"]))
        self.cardSpecs = specs
        for spec in specs:
            if "build" in spec:
                widget = spec["build"]()
                self.ctx.registerCard(spec["id"], widget)
            else:
                widget = self._buildPluginCard(spec)
                if widget is None:
                    continue
            self._cardWidgets[spec["id"]] = (spec, widget)
            self.layout.addWidget(widget)
        self.updateCardVisibility()

    def _buildPluginCard(self, spec):
        try:
            controller = spec["factory"](self.ctx)
        except Exception:
            logging.exception(f"Lesion network mapping: the card {spec['id']} could not be created and is skipped")
            return None
        widget = getattr(controller, "widget", controller)
        if widget is None or not hasattr(widget, "setVisible"):
            logging.error(f"Lesion network mapping: the card {spec['id']} has no widget; it is skipped")
            return None
        if spec.get("kind") == "card" and widget.property("collapsed") is None:
            card = self.widgets.card(spec.get("title", spec["id"]), objectName=f"LNM{spec['id'].capitalize()}Card")
            qt.QVBoxLayout(card).addWidget(widget)
            widget = card
        self._controllers.append(controller)
        self.ctx.registerCard(spec["id"], controller)
        return widget

    def _shell(self):
        return self.ctx.shell() if self.ctx is not None else None

    def _classic(self):
        return self._shell() is None

    def seedMode(self):
        node = self._parameterNode
        return node.seedMode if node is not None and node.seedMode else "lesion"

    def updateCardVisibility(self):
        from LesionNetworkMappingUI import visibleSpecs

        visible = {spec["id"] for spec in visibleSpecs([spec for spec, _widget in self._cardWidgets.values()], self.seedMode(), self._classic())}
        if self.seedMode() in ("cohort", *SEED_SET_MODES) and self.loadedMap is None:
            visible.discard("result")  # the cohort's maps are in the Cohort card; Result shows a browsed lesion map
        if self.seedMode() in SEED_SET_MODES and getattr(self.ctx, "cohortMaps", None) and "cohort" in self._cardWidgets:
            visible.add("cohort")  # the seed maps go through the Cohort card (overlap, browsing) like a cohort's lesion maps
        for cardId, (spec, widget) in self._cardWidgets.items():
            widget.setVisible(cardId in visible)

    def _focusCard(self, cardId):
        entry = self._cardWidgets.get(str(cardId))
        if entry is None:
            return False
        widget = entry[1]
        widget.setVisible(True)
        if widget.property("collapsed") is not None:
            widget.setProperty("collapsed", False)
        scrollArea = None
        parent = widget.parentWidget()
        while parent is not None:
            if hasattr(parent, "ensureWidgetVisible"):
                scrollArea = parent
                break
            parent = parent.parentWidget()
        if scrollArea is not None:
            scrollArea.ensureWidgetVisible(widget)
        widget.setFocus()
        return True

    def _revealCard(self, cardId):
        """Scroll a card into view in its scroll area (no focus change, no expansion)."""
        entry = self._cardWidgets.get(str(cardId))
        if entry is None:
            return
        parent = entry[1].parentWidget()
        while parent is not None and not hasattr(parent, "ensureWidgetVisible"):
            parent = parent.parentWidget()
        if parent is not None:
            parent.ensureWidgetVisible(entry[1])

    def _notifyControllers(self, method, *args):
        for controller in list(self._controllers):
            callback = getattr(controller, method, None)
            if callable(callback):
                try:
                    callback(*args)
                except Exception:
                    logging.exception(f"Lesion network mapping: {method} of a card failed")

    #
    # Cards: Seed
    #

    def _label(self, text="", role=None, wrap=True, objectName=None):
        label = qt.QLabel(text)
        label.setWordWrap(wrap)
        if role:
            label.setProperty("slicerRole", role)
        if objectName:
            label.setObjectName(objectName)
        label.setSizePolicy(qt.QSizePolicy.Ignored, qt.QSizePolicy.Preferred)
        return label

    def _buildSeedCard(self):
        import LesionNetworkMappingUI as plugins

        card = self.widgets.card(_("Seed"), objectName="LNMSeedCard")
        layout = qt.QVBoxLayout(card)
        # Seed modes offered by this build: Lesion, the modes that plug-ins implement (Cohort: W3-08/A-04c), and Coordinates
        # and Stimulation, whose seeds this card makes (coords.py, L-49) and the cohort maps job maps
        pluginModes = [mode for mode in plugins.SEED_MODES[1:] if any(mode in spec.get("modes", ()) and tuple(spec.get("modes", ())) != plugins.SEED_MODES for spec in self.pluginSpecs)]
        modes = ["lesion"] + [mode for mode in plugins.SEED_MODES[1:] if mode in pluginModes or mode in SEED_SET_MODES]
        self.seedModeLabels = {"lesion": _("Lesion"), "cohort": _("Cohort"), "coordinates": _("Coordinates"), "stimulation": _("Stimulation")}
        self.seedModes = modes
        self.seedModeFrame, self.seedModeGroup = self.widgets.segmented([self.seedModeLabels[mode] for mode in modes])
        self.seedModeFrame.setObjectName("LNMSeedModeSegmented")
        self.seedModeFrame.setVisible(len(modes) > 1)
        self.seedModeGroup.connect("idClicked(int)", self.onSeedModeClicked)
        layout.addWidget(self.seedModeFrame)

        self.lesionSeedPanel = qt.QWidget()
        self.lesionSeedPanel.setObjectName("LNMLesionSeedPanel")
        lesionLayout = qt.QVBoxLayout(self.lesionSeedPanel)
        lesionLayout.setContentsMargins(0, 0, 0, 0)
        layout.addWidget(self.lesionSeedPanel)
        self.cohortSeedPanel = self._buildCohortSeedPanel()
        self.cohortSeedPanel.hide()
        layout.addWidget(self.cohortSeedPanel)
        self.coordinateSeedPanel = self._buildCoordinateSeedPanel()
        self.coordinateSeedPanel.hide()
        layout.addWidget(self.coordinateSeedPanel)
        self.stimulationSeedPanel = self._buildStimulationSeedPanel()
        self.stimulationSeedPanel.hide()
        layout.addWidget(self.stimulationSeedPanel)
        layout = lesionLayout

        form = qt.QFormLayout()
        self.segmentationSelector = slicer.qMRMLNodeComboBox()
        self.segmentationSelector.setObjectName("LNMSeedSegmentationSelector")
        self.segmentationSelector.nodeTypes = ["vtkMRMLSegmentationNode"]
        self.segmentationSelector.addEnabled = False
        self.segmentationSelector.removeEnabled = False
        self.segmentationSelector.renameEnabled = False
        self.segmentationSelector.noneEnabled = True
        self.segmentationSelector.noneDisplay = _("Choose a segmentation")
        self.segmentationSelector.setMRMLScene(slicer.mrmlScene)
        self.segmentationSelector.setToolTip(_("Segmentation that holds the lesion"))
        self.segmentationSelector.connect("currentNodeChanged(vtkMRMLNode*)", self.onSegmentationChanged)
        form.addRow(_("Segmentation"), self.segmentationSelector)
        self.segmentSelector = qt.QComboBox()
        self.segmentSelector.setObjectName("LNMSeedSegmentSelector")
        self.segmentSelector.setToolTip(_("The lesion segment (default: the segment named Lesion)"))
        self.segmentSelector.connect("currentIndexChanged(int)", self.onSegmentChanged)
        form.addRow(_("Segment"), self.segmentSelector)
        layout.addLayout(form)

        row = qt.QHBoxLayout()
        self.seedSwatch = qt.QLabel()
        self.seedSwatch.setFixedSize(12, 12)
        row.addWidget(self.seedSwatch)
        self.seedNameLabel = self._label("", wrap=False, objectName="LNMSeedName")
        row.addWidget(self.seedNameLabel, 1)
        self.seedSpaceChip = self.widgets.chip("", "neutral")
        self.seedSpaceChip.setObjectName("LNMSeedSpaceChip")
        self.seedSpaceChip.hide()
        row.addWidget(self.seedSpaceChip)
        layout.addLayout(row)
        self.seedGeometryLabel = self._label("", role="secondaryText", objectName="LNMSeedGeometry")
        layout.addWidget(self.seedGeometryLabel)
        # A lesion drawn on a template of another MNI family than the connectome (A-10): it maps, with this note
        self.seedFamilyLabel = self._label("", role="secondaryText", objectName="LNMSeedFamilyNotice")
        self.seedFamilyLabel.setWordWrap(True)
        self.seedFamilyLabel.hide()
        layout.addWidget(self.seedFamilyLabel)
        self.seedErrorBanner = self.widgets.banner("", (), level="warn")
        self.seedErrorBanner.hide()
        layout.addWidget(self.seedErrorBanner)
        self.seedActions = qt.QHBoxLayout()
        self.normalizeLinkButton = qt.QPushButton(_("Normalize to MNI…"))
        self.normalizeLinkButton.setObjectName("LNMNormalizeButton")
        self.normalizeLinkButton.setProperty("slicerRole", "secondary")
        self.normalizeLinkButton.connect("clicked()", self.onNormalize)
        self.normalizeLinkButton.hide()
        self.seedActions.addWidget(self.normalizeLinkButton)
        self.seedActions.addStretch(1)
        layout.addLayout(self.seedActions)
        return card

    #: Short labels of the seed modes in Studio: the four fit the 340 px inspector (the full names are the tooltips)
    SEED_MODE_SHORT_LABELS = {"lesion": "Lesion", "cohort": "Cohort", "coordinates": "Coords", "stimulation": "Stim"}

    def setStudioPresentation(self, studio, refresh=True):
        """The Studio look of the panel (``True``: Map entered in Studio) or the Classic one (Studio left while Map stays in
        the module panel): the seed modes row, the opacity percentage, the compact header rows of the cards. The steps
        collapse only in Studio (``_applyStepCollapse``).
        """
        lookChanged = bool(studio) != self._studioLook
        self._studioLook = bool(studio)
        self._placeSeedModes(studio)
        self._applyResultPresentation(studio)
        self._notifyControllers("onPresentationChanged", studio)
        if lookChanged:
            # The steps take their Studio state again: those already done (a connectome remembered from an earlier
            # session, a lesion checked before Map was shown) collapse now, not at their next change
            self._stepStates = {}
            if studio:
                self._updateSteps()
        if refresh and hasattr(self, "resultNotice"):
            self.refreshResult(reloadMaps=False)

    def _seedModeLabel(self, mode):
        """The label of a seed mode button: short in Studio, the full name in Classic."""
        full = self.seedModeLabels.get(mode, mode)
        return _(self.SEED_MODE_SHORT_LABELS.get(mode, full)) if getattr(self, "_seedModesStudio", False) else full

    def legendState(self):
        """What the Studio map legend and layer chips show (``StudioLib.mappage``), or None without a map in the views:
        ``{statistic, window (half-width), level, threshold (None: unthresholded), thresholdText, sign, opacity, outline}``.

        While the QA card shows a derived map in the views (the debiased view or the analytic z), the legend describes
        that map: its own window, no threshold (both are descriptive) and ``"derived"`` set to its kind.
        """
        state = self.resultLegendState()
        overlay = self._shownDerivedOverlay() if state is not None else None
        if overlay is None:
            return state
        volume = overlay["volume"]
        displayNode = volume.GetDisplayNode()
        state.update({"statistic": overlay["statistic"], "window": displayNode.GetWindow() / 2.0 if displayNode is not None else 0.0,
                      "level": displayNode.GetLevel() if displayNode is not None else 0.0, "threshold": None, "thresholdText": _("Descriptive"),
                      "derived": overlay["kind"]})
        return state

    def _shownDerivedOverlay(self):
        """The QA card's derived map (``{"kind", "volume", "statistic"}``) while it is the foreground of a slice view, else None."""
        qa = self.ctx.card("qa") if self.ctx is not None else None
        overlay = qa.shownOverlay() if qa is not None and hasattr(qa, "shownOverlay") else None
        if overlay is None:
            return None
        volumeID = overlay["volume"].GetID()
        for composite in slicer.util.getNodesByClass("vtkMRMLSliceCompositeNode"):
            if composite.GetForegroundVolumeID() == volumeID:
                return overlay
        return None

    def onDerivedOverlayChanged(self):
        """The QA card showed or hid a derived map: the legend, the layer chips and the peak table's header follow."""
        if hasattr(self, "peaksTable"):
            self._setPeakValueHeader(self.currentStatistic())
        self._refreshMapOverlay()

    def _setPeakValueHeader(self, statistic):
        """The peak table's value column: the statistic, or "<statistic> map" while the views show a QA derived map (the
        peaks stay those of the map, not of the derived map).
        """
        header = self.peaksTable.horizontalHeaderItem(2)
        if header is None:
            return
        text, tip = statistic, ""
        if self._shownDerivedOverlay() is not None:
            text = _("{statistic} map").format(statistic=statistic)
            tip = _("Peaks of the {statistic} map; the views show a descriptive map from the QA card").format(statistic=statistic)
        if str(header.text()) != text:
            header.setText(text)
        header.setToolTip(tip)

    def restoreSceneResult(self):
        """Make the map of a reloaded scene (a reopened project) available without showing Map; return True when the Result
        card has a map afterwards.

        The parameter node, the connectome and the scene's result volume are normally picked up when Map is first entered
        (``enter``), so that until then the threshold rule applied to the map cannot be read (the NIfTI export of the project
        needs it). This does the same steps as ``enter`` without its presentation; entering Map afterwards still shows the peak
        table of a map adopted here. Without a map volume in the scene it changes nothing.
        """
        if self._hasResult():
            return True
        if not any(volume.GetAttribute("LNM.Statistic") for volume in slicer.util.getNodesByClass("vtkMRMLScalarVolumeNode")):
            return False
        self.initializeParameterNode()
        self.refreshConnectomes()
        if not self._adoptSceneResult():
            return self._hasResult()
        self._peaksPending = True  # enter() computes the peak table of the adopted map
        self._displayWindow(self._parameterNode.resultVolume, False)
        self.refreshResult(reloadMaps=False)
        return self._hasResult()

    def resultLegendState(self):
        """``legendState()`` of the map itself (``parameterNode.resultVolume``), whatever the views show: its window and the
        threshold rule applied to it (the NIfTI export masks the map with it).
        """
        from LesionNetworkMappingLib import display, thresholds

        node = self._parameterNode
        volume = node.resultVolume if node is not None else None
        if volume is None or volume.GetScene() is None or not self._hasResult():
            return None
        displayNode = volume.GetDisplayNode()
        try:
            # The half-width of the window the colours are shown in (it may be wider than the map's own, LNM.Window)
            window = displayNode.GetWindow() / 2.0 if displayNode is not None else float(volume.GetAttribute(display.WINDOW_ATTRIBUTE) or 0.0)
        except ValueError:
            window = 0.0
        # The centre of the colours (0 for the maps Map shows)
        level = displayNode.GetLevel() if displayNode is not None else 0.0
        statistic = self.currentStatistic()
        rule = self.currentRule()
        resolved = self.resolved
        threshold = None
        thresholdText = _("Unthresholded")
        if self._ruleHidesShownMap():
            # The colours show nothing (the Result card says so): the legend must not claim the whole map is shown
            thresholdText = _("Rule not applied")
        if self._ruleAppliesToShownMap():
            threshold = float(resolved.value)
            quantity = {"both": f"|{statistic}|", "pos": statistic, "neg": f"−{statistic}"}.get(self._sign(), statistic)  # noqa: RUF001
            label = thresholds.RULE_LABELS.get(rule["kind"], rule["kind"])
            # The value as the derived line writes it (never rounded to one decimal: Fz 0.05 is not 0.1, a 0.0304 cut not 0.0)
            thresholdText = f"{label} · {quantity} ≥ {thresholds.format_value(resolved)}"
        return {"statistic": statistic, "window": window, "level": level, "threshold": threshold, "thresholdText": thresholdText, "sign": self._sign(),
                "opacity": float(node.opacity) if node is not None else 0.8, "outline": self._outlineState is not None}

    def studioMenuActions(self):
        """Items of the Map ⋯ menu in Studio (``StudioLib.mappage.moreMenuActions``): the recipes and the reporting checks,
        whose header rows Studio shows only with a study (VISUAL 4.5).
        """
        items = []
        recipe = self.ctx.card("recipe") if self.ctx is not None else None
        recipeItems = recipe.menuItems() if recipe is not None and hasattr(recipe, "menuItems") else []
        if recipeItems:
            items.append((_("Recipe"), recipeItems))
        if self.ctx is not None and self.ctx.card("report") is not None:
            items.append((_("Reporting checks…"), lambda: self.ctx.focusCard("report"), None))
        return items

    def _placeSeedModes(self, studio):
        """Studio: the seed modes are a row above the steps (Seed collapses to its row once done; the modes stay at hand)
        with short labels; Classic: the first row of the Seed card with the full labels.
        """
        frame = getattr(self, "seedModeFrame", None)
        seedCard = self._cardWidgets.get("seed", (None, None))[1]
        if frame is None or seedCard is None:
            return
        self._seedModesStudio = bool(studio)
        for mode, button in zip(self.seedModes, self.seedModeGroup.buttons(), strict=False):
            full = self.seedModeLabels.get(mode, mode)
            text = self._seedModeLabel(mode)
            if mode == "cohort" and self.cohortInfo:
                text += f" ({self.cohortInfo['n']})"
            if str(button.text) != text:
                button.setText(text)
            button.setToolTip(full if not str(text).startswith(full) else "")
            button.setAccessibleName(full)
        if studio:
            if self._seedModeRow is None:
                self._seedModeRow = qt.QWidget()
                self._seedModeRow.setObjectName("LNMSeedModeRow")
                rowLayout = qt.QHBoxLayout(self._seedModeRow)
                rowLayout.setContentsMargins(6, 0, 6, 2)
                rowLayout.setSpacing(0)
            if frame.parentWidget() is not self._seedModeRow:
                seedCard.layout().removeWidget(frame)
                self._seedModeRow.layout().addWidget(frame, 1)
            # The Seed card (ctkCollapsibleButton) filters the events of the widgets added to it and hides them while it is
            # collapsed; it keeps that filter on the frame after the move, so the frame would vanish with the collapsed card
            frame.removeEventFilter(seedCard)
            if self.layout.indexOf(self._seedModeRow) < 0:
                self.layout.insertWidget(self.layout.indexOf(seedCard), self._seedModeRow)
            frame.setSizePolicy(qt.QSizePolicy.Expanding, qt.QSizePolicy.Fixed)
            # Ignored: the buttons share the row equally and never widen the inspector (four modes with a count are
            # wider than the 340 px inspector at their size hints)
            for button in self.seedModeGroup.buttons():
                button.setSizePolicy(qt.QSizePolicy.Ignored, qt.QSizePolicy.Fixed)
            self._seedModeRow.setVisible(len(self.seedModes) > 1)
            # The frame may come from a collapsed Seed card, which hid it with its other contents
            self._showSeedModeFrame()
        elif frame.parentWidget() is not seedCard:
            if self._seedModeRow is not None:
                self._seedModeRow.layout().removeWidget(frame)
                self._seedModeRow.hide()
            frame.setSizePolicy(qt.QSizePolicy.Fixed, qt.QSizePolicy.Fixed)
            for button in self.seedModeGroup.buttons():
                button.setSizePolicy(qt.QSizePolicy.Preferred, qt.QSizePolicy.Fixed)
            seedCard.layout().insertWidget(0, frame)
            frame.setVisible(len(self.seedModes) > 1 and not bool(getattr(seedCard, "collapsed", False)))

    def _showSeedModeFrame(self):
        """Studio: the seed modes row shows its segmented control (a collapsed Seed card may have hidden it)."""
        frame = getattr(self, "seedModeFrame", None)
        if frame is None or not getattr(self, "_seedModesStudio", False) or frame.parentWidget() is not self._seedModeRow:
            return
        if frame.isHidden() and len(self.seedModes) > 1:
            frame.show()

    def _buildCohortSeedPanel(self):
        """Seed = Cohort: the study and what it maps (its analysable lesions, the excluded and native ones)."""
        panel = qt.QWidget()
        panel.setObjectName("LNMCohortSeedPanel")
        layout = qt.QVBoxLayout(panel)
        layout.setContentsMargins(0, 0, 0, 0)
        self.cohortStudyLabel = self._label("", objectName="LNMCohortStudy")
        layout.addWidget(self.cohortStudyLabel)
        self.cohortExcludedLabel = self._label("", role="secondaryText", objectName="LNMCohortExcluded")
        layout.addWidget(self.cohortExcludedLabel)
        self.cohortNativeBanner = self.widgets.banner("", ((_("Normalize in Library"), self.onNormalizeInLibrary),), level="warn")
        self.cohortNativeBanner.setObjectName("LNMCohortNativeBanner")
        self.cohortNativeBanner.hide()
        layout.addWidget(self.cohortNativeBanner)
        row = qt.QHBoxLayout()
        self.cohortOpenStudyButton = qt.QPushButton(_("Open study…"))
        self.cohortOpenStudyButton.setObjectName("LNMCohortOpenStudyButton")
        self.cohortOpenStudyButton.setProperty("slicerRole", "secondary")
        self.cohortOpenStudyButton.setToolTip(_("Choose a study folder (study.json and participants.tsv)"))
        self.cohortOpenStudyButton.connect("clicked()", self.onOpenCohortStudy)
        row.addWidget(self.cohortOpenStudyButton)
        row.addStretch(1)
        layout.addLayout(row)
        return panel

    def onSeedModeClicked(self, index):
        if self._parameterNode is None or index < 0 or index >= len(self.seedModes):
            return
        self._parameterNode.seedMode = self.seedModes[index]
        self._showSeedMode()
        self.updateCardVisibility()
        self.updateComputeState()
        self._notifyControllers("onCohortMapsChanged", getattr(self.ctx, "cohortMaps", None))

    #
    # Seed: coordinates and stimulation (coords.py; mapped by the cohort maps job, shown by the Cohort card)
    #

    def _buildSphereRow(self, objectNamePrefix):
        """A sphere size row: [Radius | Diameter] + mm, and a line that states both (the sizes are never ambiguous)."""
        row = qt.QHBoxLayout()
        kindCombo = qt.QComboBox()
        kindCombo.setObjectName(f"{objectNamePrefix}SphereKind")
        kindCombo.addItem(_("Radius"), "radius")
        kindCombo.addItem(_("Diameter"), "diameter")
        kindCombo.setToolTip(_("Is the size a radius or a diameter? Studies differ (Darby 2019: 4 mm radius; Ji 2025: 6 mm diameter)."))
        row.addWidget(kindCombo)
        sizeSpin = qt.QDoubleSpinBox()
        sizeSpin.setObjectName(f"{objectNamePrefix}SphereSize")
        sizeSpin.setRange(0.5, 60.0)
        sizeSpin.setDecimals(1)
        sizeSpin.setSingleStep(0.5)
        sizeSpin.setSuffix(" mm")
        sizeSpin.setValue(4.0)
        row.addWidget(sizeSpin)
        row.addStretch(1)
        textLabel = self._label("", role="secondaryText", objectName=f"{objectNamePrefix}SphereText")
        kindCombo.connect("currentIndexChanged(int)", lambda index: self.onSphereChanged())
        sizeSpin.connect("valueChanged(double)", lambda value: self.onSphereChanged())
        return row, kindCombo, sizeSpin, textLabel

    def _buildCoordinateSeedPanel(self):
        """Seed = Coordinates: a table of reported foci (study, x, y, z, space) mapped as study-level union spheres."""
        panel = qt.QWidget()
        panel.setObjectName("LNMCoordinateSeedPanel")
        layout = qt.QVBoxLayout(panel)
        layout.setContentsMargins(0, 0, 0, 0)
        row = qt.QHBoxLayout()
        self.coordImportButton = qt.QPushButton(_("Import coordinates…"))
        self.coordImportButton.setObjectName("LNMCoordImportButton")
        self.coordImportButton.setProperty("slicerRole", "secondary")
        self.coordImportButton.setToolTip(_("A table (x, y, z and optionally radius, study, space), a BrainMap Sleuth text file or a NiMARE dataset JSON"))
        self.coordImportButton.connect("clicked()", self.onImportCoordinates)
        row.addWidget(self.coordImportButton)
        self.coordMarkupsSelector = slicer.qMRMLNodeComboBox()
        self.coordMarkupsSelector.setObjectName("LNMCoordMarkupsSelector")
