    def _buildStimulationSeedPanel(self):
        """Seed = Stimulation: per-patient stimulation sites (points with a sphere, E-field or VTA NIfTIs) and an outcome."""
        from LesionNetworkMappingLib import coords

        panel = qt.QWidget()
        panel.setObjectName("LNMStimulationSeedPanel")
        layout = qt.QVBoxLayout(panel)
        layout.setContentsMargins(0, 0, 0, 0)
        form = qt.QFormLayout()
        self.stimKindCombo = qt.QComboBox()
        self.stimKindCombo.setObjectName("LNMStimKind")
        for kind, label in (("points", _("Points + sphere (TMS sites)")), ("efield", _("E-field NIfTI (SimNIBS)")), ("vta", _("VTA NIfTI (Lead-DBS)"))):
            self.stimKindCombo.addItem(label, kind)
        self.stimKindCombo.connect("currentIndexChanged(int)", self.onStimulationKindChanged)
        form.addRow(_("Sites"), self.stimKindCombo)
        self.stimWeightingCombo = qt.QComboBox()
        self.stimWeightingCombo.setObjectName("LNMStimWeighting")
        self.stimWeightingCombo.connect("currentIndexChanged(int)", lambda index: self.onStimulationWeightingChanged())
        form.addRow(_("Weighting"), self.stimWeightingCombo)
        sphereRow, self.stimSphereKindCombo, self.stimSphereSizeSpin, self.stimSphereLabel = self._buildSphereRow("LNMStim")
        self.stimSphereRowLabel = qt.QLabel(_("Sphere"))
        form.addRow(self.stimSphereRowLabel, sphereRow)
        self.stimThresholdSpin = qt.QDoubleSpinBox()
        self.stimThresholdSpin.setObjectName("LNMStimThreshold")
        self.stimThresholdSpin.setRange(0.0, 1000.0)
        self.stimThresholdSpin.setDecimals(2)
        self.stimThresholdSpin.setSuffix(" V/m")
        self.stimThresholdSpin.setSpecialValueText(_("Half the maximum"))
        self.stimThresholdSpin.setToolTip(_("E-field strength of the seed (0: half the maximum of each field)"))
        self.stimThresholdRowLabel = qt.QLabel(_("Threshold"))
        form.addRow(self.stimThresholdRowLabel, self.stimThresholdSpin)
        layout.addLayout(form)
        layout.addWidget(self.stimSphereLabel)
        row = qt.QHBoxLayout()
        self.stimImportButton = qt.QPushButton(_("Import sites…"))
        self.stimImportButton.setObjectName("LNMStimImportButton")
        self.stimImportButton.setProperty("slicerRole", "secondary")
        self.stimImportButton.setToolTip(_("A table with participant_id and x, y, z (points) or file (an E-field or VTA NIfTI, relative to the table), "
                                           "and optionally an outcome column"))
        self.stimImportButton.connect("clicked()", self.onImportStimulation)
        row.addWidget(self.stimImportButton)
        row.addStretch(1)
        layout.addLayout(row)
        self.stimTable = self.widgets.tableView([_("Patient"), _("Site"), _("Outcome")])
        self.stimTable.setObjectName("LNMStimTable")
        self.stimTable.setMaximumHeight(150)
        layout.addWidget(self.stimTable)
        self.stimSummaryLabel = self._label("", role="secondaryText", objectName="LNMStimSummary")
        layout.addWidget(self.stimSummaryLabel)
        form = qt.QFormLayout()
        self.stimOutcomeCombo = qt.QComboBox()
        self.stimOutcomeCombo.setObjectName("LNMStimOutcome")
        self.stimOutcomeCombo.setToolTip(_("The per-patient outcome (for example % improvement) of the R-map"))
        self.stimOutcomeCombo.connect("currentIndexChanged(int)", lambda index: self._showStimulation())
        form.addRow(_("Outcome"), self.stimOutcomeCombo)
        layout.addLayout(form)
        self.stimFlipCheckBox = qt.QCheckBox(_("Flip the sign (TMS: anticorrelation predicts response)"))
        self.stimFlipCheckBox.setObjectName("LNMStimFlip")
        self.stimFlipCheckBox.connect("toggled(bool)", self.onStimulationFlipToggled)
        layout.addWidget(self.stimFlipCheckBox)
        row = qt.QHBoxLayout()
        self.stimRmapButton = qt.QPushButton(_("Compute R-map"))
        self.stimRmapButton.setObjectName("LNMStimRmapButton")
        self.stimRmapButton.setProperty("slicerRole", "secondary")
        self.stimRmapButton.setToolTip(_("Correlation of each voxel's connectivity (Fz) with the outcome over the patients, with permutation inference (sLNM)"))
        self.stimRmapButton.connect("clicked()", self.runStimulationRmap)
        row.addWidget(self.stimRmapButton)
        row.addStretch(1)
        layout.addLayout(row)
        self.stimRmapProgress = self.widgets.progressRow(objectNamePrefix="LNMStimRmap")
        self.stimRmapProgress.widget.hide()
        layout.addWidget(self.stimRmapProgress.widget)
        self.stimRmapReasonLabel = self._label("", role="secondaryText", objectName="LNMStimRmapReason")
        layout.addWidget(self.stimRmapReasonLabel)
        self.stimCaption = self._label(_("Research use only: stimulation-site maps describe connectivity; they do not choose treatment targets."),
                                       role="caption", objectName="LNMStimCaption")
        layout.addWidget(self.stimCaption)
        self.stimulationItems = []
        self.stimulationSource = None
        self.stimulationColumns = []
        self._fillStimulationWeightings(coords.STIMULATION_KINDS[0])
        self._showStimulation()
        return panel

    # Sphere size (shared by both panels and the parameter node)

    def sphereSettings(self):
        """(radius_mm, diameter_mm) of the sphere settings: exactly one is set (coords.sphere_radius)."""
        node = self._parameterNode
        size = float(node.sphereSize) if node is not None else float(self.coordSphereSizeSpin.value)
        kind = node.sphereSizeKind if node is not None else "radius"
        return (None, size) if kind == "diameter" else (size, None)

    def onSphereChanged(self):
        if self._updatingGui or self._parameterNode is None:
            return
        sender = "stim" if self.seedMode() == "stimulation" else "coord"
        kindCombo = self.stimSphereKindCombo if sender == "stim" else self.coordSphereKindCombo
        sizeSpin = self.stimSphereSizeSpin if sender == "stim" else self.coordSphereSizeSpin
        self._parameterNode.sphereSizeKind = kindCombo.currentData or "radius"
        self._parameterNode.sphereSize = float(sizeSpin.value)
        self._showSphere()
        self._showCoordinates()

    def _showSphere(self):
        """Both sphere rows show the parameter node's size, and a line that states the radius and the diameter."""
        from LesionNetworkMappingLib import coords

        node = self._parameterNode
        if node is None or not hasattr(self, "coordSphereKindCombo"):
            return
        wasUpdating, self._updatingGui = self._updatingGui, True
        try:
            for kindCombo, sizeSpin in ((self.coordSphereKindCombo, self.coordSphereSizeSpin), (self.stimSphereKindCombo, self.stimSphereSizeSpin)):
                index = kindCombo.findData(node.sphereSizeKind or "radius")
                kindCombo.setCurrentIndex(max(index, 0))
                sizeSpin.setValue(float(node.sphereSize))
        finally:
            self._updatingGui = wasUpdating
        try:
            text = coords.sphere_text(coords.sphere_radius(*self.sphereSettings())[1])
        except ValueError as exc:
            text = str(exc)
        for label in (self.coordSphereLabel, self.stimSphereLabel):
            label.setText(_("Sphere: {text}").format(text=text))

    # Coordinates

    def setCoordinates(self, foci, source=None):
        """Use these foci (``coords.Focus``) for the Coordinates seed; ``source`` is the file they came from (or None)."""
        self.coordinateFoci = list(foci)
        self.coordinateSource = source
        self.coordinateMapsPath = None
        self._publishCohortMaps()
        self._showCoordinates()
        self.updateCardVisibility()
        self.updateComputeState()
        self._notifyControllers("onCohortMapsChanged", getattr(self.ctx, "cohortMaps", None))

    def onImportCoordinates(self):
        path = qt.QFileDialog.getOpenFileName(slicer.util.mainWindow(), _("Import coordinates"), "", COORDINATE_FILTER)
        if path:
            self.importCoordinates(path)

    def importCoordinates(self, path):
        """Read a coordinate file (CSV/TSV, Sleuth text or NiMARE JSON) and append its foci; return them, or None on an error."""
        from LesionNetworkMappingLib import coords

        try:
            foci = coords.read_foci(path)
        except (OSError, ValueError) as exc:
            slicer.util.errorDisplay(_("The coordinates cannot be read: {error}").format(error=exc), windowTitle=_("Import coordinates"))
            return None
        # Importing the same foci again (the same file twice) would add foci to the null sets of their study
        known = {_focusKey(focus) for focus in self.coordinateFoci}
        new = []
        for focus in foci:
            if _focusKey(focus) not in known:
                known.add(_focusKey(focus))
                new.append(focus)
        self.setCoordinates(self.coordinateFoci + new, path if not self.coordinateFoci else None)
        skipped = len(foci) - len(new)
        if skipped:
            self.coordSummaryLabel.setText(self.coordSummaryLabel.text + " · " + (_("1 focus already in the list was skipped") if skipped == 1 else
                                                                                  _("{n} foci already in the list were skipped").format(n=skipped)))
        return new

    def onAddMarkupsCoordinates(self):
        node = self.coordMarkupsSelector.currentNode()
        if node is None:
            return
        self.addMarkupsCoordinates(node)

    def addMarkupsCoordinates(self, node, study=None):
        """Append the control points of a point list (RAS = MNI mm) as one study (named after the list)."""
        from LesionNetworkMappingLib import coords

        points = []
        for index in range(node.GetNumberOfControlPoints()):
            position = [0.0, 0.0, 0.0]
            node.GetNthControlPointPositionWorld(index, position)
            points.append(position)
        if not points:
            return []
        foci = coords.foci_from_points(points, study=study or node.GetName())
        self.setCoordinates(self.coordinateFoci + foci, None)
        return foci

    def _showCoordinates(self):
        from LesionNetworkMappingLib import coords

        if not hasattr(self, "coordTable"):
            return
        foci = self.coordinateFoci
        self.coordTable.setRowCount(len(foci))
        for row, focus in enumerate(foci):
            for column, value in enumerate((focus.study, f"{focus.x:g}", f"{focus.y:g}", f"{focus.z:g}", "Talairach" if focus.space == "TAL" else "MNI")):
                item = qt.QTableWidgetItem(value)
                item.setFlags(qt.Qt.ItemIsSelectable | qt.Qt.ItemIsEnabled)
                self.coordTable.setItem(row, column, item)
        self.coordTable.setVisible(bool(foci))
        self.coordClearButton.setVisible(bool(foci))
        studies = coords.group_by_study(foci)
        if not foci:
            self.coordSummaryLabel.setText(_("Import reported coordinates (or add a point list): the foci of each study make one seed."))
        else:
            talairach = sum(1 for focus in foci if focus.space == "TAL")
            text = _("{studies} studies · {foci} foci").format(studies=len(studies), foci=len(foci))
            if talairach:
                text += " · " + (_("1 Talairach focus will be converted to MNI (Lancaster et al. 2007)") if talairach == 1 else
                                 _("{n} Talairach foci will be converted to MNI (Lancaster et al. 2007)").format(n=talairach))
            text += _ownRadiusText(foci)
            self.coordSummaryLabel.setText(text)
        checked = self._parameterNode is not None and self._parameterNode.coordinateNull
        self.coordNullPanel.setVisible(checked)
        self.coordNullRunButton.setVisible(checked)
        self.coordNullCaption.setVisible(checked)
        self.coordNullCostLabel.setVisible(checked)
        if checked:
            k = int(self.coordNullKSpin.value)
            passes = coords.null_cost(max(len(studies), 1), k, self.bundle.n_voxels if self.bundle is not None else 0, self._nullColumnsPerPass())
            self.coordNullCostLabel.setText(_("{k} null sets × {studies} studies = {seeds:,} seeds, about {passes:,} connectome passes").format(  # noqa: RUF001
                k=k, studies=len(studies), seeds=k * len(studies), passes=passes))
            enabled, reason = self.coordinateNullState()
            self.coordNullRunButton.setEnabled(enabled)
            self.coordNullRunButton.setToolTip(reason)
            # A template-family mismatch is shown inline (not only as a tooltip); other reasons are self-evident
            familyReason = reason if not enabled and "family" in reason and os.path.isfile(self.coordGmPathEdit.currentPath or "") else ""
            if familyReason:
                self.coordNullResultLabel.setText(familyReason)
                self.coordNullResultLabel.show()
            elif self._coordNullReasonShown:
                self.coordNullResultLabel.hide()
            self._coordNullReasonShown = bool(familyReason)

    def _nullColumnsPerPass(self):
        from LesionNetworkMappingLib import cohortmaps

        return cohortmaps.batch_size(self.bundle.n_voxels) if self.bundle is not None else 100

    def onCoordinateNullToggled(self, checked):
        if self._parameterNode is not None and not self._updatingGui:
            self._parameterNode.coordinateNull = bool(checked)
        self._showCoordinates()

    def _onCoordinateNullSettings(self):
        if self._parameterNode is not None and not self._updatingGui:
            self._parameterNode.coordinateNullK = int(self.coordNullKSpin.value)
        # Deferred: ctkPathLineEdit reports a new path before currentPath returns it
        qt.QTimer.singleShot(0, self._showCoordinates)

    def coordinateNullState(self):
        """(enabled, reason) of the random-coordinate control."""
        from LesionNetworkMappingLib import coords

        if self.coordinateNullJob is not None and not self.coordinateNullJob.isFinished():
            return False, _("The random-coordinate control is running…")
        if len(coords.group_by_study(self.coordinateFoci)) < 2:
            return False, _("The control compares the overlap of at least 2 studies.")
        if self.bundle is None or not self.acceptTermsCheckBox.checked:
            return False, _("Choose a connectome and accept its data use terms.")
        gmPath = self.coordGmPathEdit.currentPath or ""
        if not os.path.isfile(gmPath):
            return False, _("Choose a gray-matter probability map of the connectome's template family.")
        # The template family is checked before running (the job would refuse it): the reason shows next to the button
        from LesionNetworkMappingLib import circuits

        try:
            circuits.check_families(coords.grid_space(self.bundle), circuits.space_of_file(gmPath))
        except circuits.FamilyError as exc:
            return False, str(exc).replace("circuit", "connectome grid")
        return True, ""

    # Stimulation

    def _fillStimulationWeightings(self, kind):
        from LesionNetworkMappingLib import coords

        labels = {"binary": _("Binary"), "graded": _("Graded (centre 1, edge 0)"), "normalized": _("Normalized (E / max E)"),
                  "threshold": _("Threshold"), "probabilistic": _("Probabilistic")}
        wasUpdating, self._updatingGui = self._updatingGui, True
        try:
            self.stimWeightingCombo.clear()
            for weighting in coords.STIMULATION_WEIGHTINGS[kind]:
                self.stimWeightingCombo.addItem(labels[weighting], weighting)
            node = self._parameterNode
            current = node.stimulationWeighting if node is not None else ""
            index = self.stimWeightingCombo.findData(current)
            self.stimWeightingCombo.setCurrentIndex(max(index, 0))
        finally:
            self._updatingGui = wasUpdating

    def stimulationKind(self):
        return self.stimKindCombo.currentData or "points"

    def onStimulationKindChanged(self, index):
        kind = self.stimulationKind()
        if self._parameterNode is not None and not self._updatingGui:
            self._parameterNode.stimulationKind = kind
            self._parameterNode.stimulationWeighting = ""
            self.stimulationItems, self.stimulationSource, self.stimulationColumns = [], None, []
            self.stimulationMapsPath = None
            self._publishCohortMaps()
        self._fillStimulationWeightings(kind)
        self._showStimulation()
        self.updateCardVisibility()
        self.updateComputeState()

    def onStimulationWeightingChanged(self):
        if self._parameterNode is not None and not self._updatingGui:
            self._parameterNode.stimulationWeighting = self.stimWeightingCombo.currentData or ""
        self._showStimulation()

    def onStimulationFlipToggled(self, checked):
        if self._parameterNode is not None and not self._updatingGui:
            self._parameterNode.stimulationFlip = bool(checked)

    def onImportStimulation(self):
        path = qt.QFileDialog.getOpenFileName(slicer.util.mainWindow(), _("Import stimulation sites"), "", "Tables (*.csv *.tsv *.txt);;All files (*)")
        if path:
            self.importStimulation(path)

    def importStimulation(self, path):
        """Read a stimulation table for the current kind; return its rows, or None on an error."""
        from LesionNetworkMappingLib import coords

        try:
            items = coords.read_stimulation_table(path, self.stimulationKind())
            columns = coords.numeric_columns(path)
        except (OSError, ValueError) as exc:
            slicer.util.errorDisplay(_("The stimulation sites cannot be read: {error}").format(error=exc), windowTitle=_("Import stimulation sites"))
            return None
        self.stimulationItems, self.stimulationSource, self.stimulationColumns = items, path, columns
        self.stimulationMapsPath = None
        wasUpdating, self._updatingGui = self._updatingGui, True
        try:
            self.stimOutcomeCombo.clear()
            self.stimOutcomeCombo.addItem(_("None"), "")
            for column in columns:
                self.stimOutcomeCombo.addItem(column, column)
            self.stimOutcomeCombo.setCurrentIndex(1 if columns else 0)
        finally:
            self._updatingGui = wasUpdating
        self._publishCohortMaps()
        self._showStimulation()
        self.updateCardVisibility()
        self.updateComputeState()
        self._notifyControllers("onCohortMapsChanged", getattr(self.ctx, "cohortMaps", None))
        return items

    def stimulationOutcomes(self):
        """{participant_id: outcome text} of the chosen outcome column ({} without one)."""
        from LesionNetworkMappingLib import coords

        column = self.stimOutcomeCombo.currentData if self.stimOutcomeCombo.count else ""
        if not column or not self.stimulationSource:
            return {}
        _columns, rows = coords.read_table(self.stimulationSource)
        return {row["participant_id"]: row.get(column) for row in rows if row.get("participant_id")}

    def _showStimulation(self):
        if not hasattr(self, "stimTable"):
            return
        kind = self.stimulationKind()
        points = kind == "points"
        for widget in (self.stimSphereRowLabel, self.stimSphereKindCombo, self.stimSphereSizeSpin, self.stimSphereLabel):
            widget.setVisible(points)
        threshold = kind == "efield" and (self.stimWeightingCombo.currentData or "") == "threshold"
        self.stimThresholdRowLabel.setVisible(threshold)
        self.stimThresholdSpin.setVisible(threshold)
        outcomes = self.stimulationOutcomes() if self.stimulationItems else {}
        self.stimTable.setRowCount(len(self.stimulationItems))
        for row, item in enumerate(self.stimulationItems):
            if item.get("points"):
                site = ", ".join(f"({p.x:g}, {p.y:g}, {p.z:g})" for p in item["points"])
            else:
                site = os.path.basename(item.get("image") or "")
            for column, value in enumerate((item["participant_id"], site, str(outcomes.get(item["participant_id"], "") or ""))):
                cell = qt.QTableWidgetItem(value)
                cell.setFlags(qt.Qt.ItemIsSelectable | qt.Qt.ItemIsEnabled)
                self.stimTable.setItem(row, column, cell)
        self.stimTable.setVisible(bool(self.stimulationItems))
        patients = len({item["participant_id"] for item in self.stimulationItems})
        if not self.stimulationItems:
            self.stimSummaryLabel.setText(_("Import a table of stimulation sites: one seed per patient, mapped like lesions."))
        else:
            text = _("{n} patients · {rows} rows").format(n=patients, rows=len(self.stimulationItems))
            if points:
                text += _ownRadiusText([p for item in self.stimulationItems for p in item.get("points") or ()])
            self.stimSummaryLabel.setText(text)
        enabled, reason = self.stimulationRmapState()
        self.stimRmapButton.setEnabled(enabled)
        self.stimRmapReasonLabel.setText(reason)
        self.stimRmapReasonLabel.setVisible(bool(reason))
        node = self._parameterNode
        if node is not None:
            wasUpdating, self._updatingGui = self._updatingGui, True
            try:
                self.stimFlipCheckBox.setChecked(bool(node.stimulationFlip))
            finally:
                self._updatingGui = wasUpdating

    def stimulationRmapState(self):
        """(enabled, reason) of Compute R-map: seed maps, an outcome column and no R-map job running."""
        if self.stimulationRmapJob is not None and not self.stimulationRmapJob.isFinished():
            return False, _("Computing the R-map…")
        if not self.stimulationItems:
            return False, ""
        if not (self.stimOutcomeCombo.currentData if self.stimOutcomeCombo.count else ""):
            return False, _("Choose the outcome column for an R-map.")
        if not self._seedSetMaps("stimulation"):
            return False, _("Map the stimulation seeds first.")
        return True, ""

    # Compute: seed sets

    def _seedSetMaps(self, mode):
        """maps.tsv of the finished seed maps of a seed-set mode, or None."""
        path = self.coordinateMapsPath if mode == "coordinates" else self.stimulationMapsPath if mode == "stimulation" else None
        if path and os.path.isfile(path):
            try:
                with open(os.path.join(os.path.dirname(path), "cohortmaps.json"), encoding="utf-8") as f:
                    if json.load(f).get("status") == "done":
                        return path
            except (OSError, ValueError):
                return None
        return None

    def _publishCohortMaps(self):
        """The maps the Cohort card shows: the study's cohort maps (Cohort), or the seed maps (Coordinates, Stimulation)."""
        if self.ctx is None:
            return
        mode = self.seedMode()
        self.ctx.cohortMaps = self._seedSetMaps(mode) if mode in SEED_SET_MODES else self.cohortMapsPath

    def seedSetCount(self, mode=None):
        """Number of seeds the current seed-set mode would map (studies, or patients)."""
        from LesionNetworkMappingLib import coords

        mode = mode or self.seedMode()
        if mode == "coordinates":
            return len(coords.group_by_study(self.coordinateFoci))
        if mode == "stimulation":
            return len({item["participant_id"] for item in self.stimulationItems})
        return 0

    def seedSetComputeState(self):
        """(enabled, reason) of mapping the seeds of the Coordinates or Stimulation mode."""
        from LesionNetworkMappingUI import jobrunner

        if self.cohortJob is not None and (self.cohortJob.isRunning() or self.cohortJob.isQueued()):
            return False, _("Mapping the seeds…")
        if self.seedSetCount() == 0:
            return False, _("Import coordinates first.") if self.seedMode() == "coordinates" else _("Import stimulation sites first.")
        try:
            from LesionNetworkMappingLib import coords

            coords.sphere_radius(*self.sphereSettings())
        except ValueError as exc:
            return False, str(exc)
        if self.bundle is None:
            return False, _("Add a connectome, or use the demo, to map.")
        if not self.acceptTermsCheckBox.checked:
            return False, _("Accept the data use terms of {name} to map.").format(name=self.bundle.name)
        if not self.ctx.computeEnabled():
            return False, " ".join(self.ctx.computeDisabledReasons()) or _("Not ready")
        if jobrunner.instance().isBusy():
            return True, _("Another computation is running: this one will wait for it.")
        return True, ""

    def _seedSetButtonText(self):
        n = self.seedSetCount()
        if self.seedMode() == "coordinates":
            return _("Map the study seed") if n == 1 else _("Map {n} study seeds").format(n=n) if n else _("Map study seeds")
        return _("Map the stimulation seed") if n == 1 else _("Map {n} stimulation seeds").format(n=n) if n else _("Map stimulation seeds")

    def prepareSeedSet(self, runDir, checkMask=True):
        """Write the seeds of the current seed-set mode in ``runDir`` (coords.py); return lesions.tsv.

        ``checkMask``: refuse seeds with no weight in the connectome's brain mask, naming them (coords.OutsideMaskError,
        a ValueError): their maps would be all zero and fail the whole run.
        """
        from LesionNetworkMappingLib import coords

        mode = self.seedMode()
        radius, diameter = self.sphereSettings()
        maskIndices = self.bundle.mask_indices if checkMask else None
        os.makedirs(runDir, exist_ok=True)
        if mode == "coordinates":
            # The foci as a plain table in the run folder: the seeds' source and the null's input (no local path is kept)
            fociPath = os.path.join(runDir, "foci.tsv")
            with open(fociPath, "w", encoding="utf-8", newline="\n") as f:
                f.write("study\tx\ty\tz\tspace\tradius\n")
                for focus in self.coordinateFoci:
                    f.write(f"{focus.study}\t{focus.x!r}\t{focus.y!r}\t{focus.z!r}\t{focus.space}\t{'' if focus.radius_mm is None else repr(focus.radius_mm)}\n")
            return coords.prepare_coordinates(runDir, self.coordinateFoci, self.bundle.grid, radius, diameter, source=fociPath, grid_space=coords.grid_space(self.bundle),
                                              mask_indices=maskIndices)
        outcomes = self.stimulationOutcomes()
        column = self.stimOutcomeCombo.currentData if self.stimOutcomeCombo.count else ""
        safeColumn = column if column and re.fullmatch(r"[A-Za-z][A-Za-z0-9_]*", column) else "outcome"
        items = [dict(item, outcome=outcomes.get(item["participant_id"]) if column else None) for item in self.stimulationItems]
        kind = self.stimulationKind()
        threshold = float(self.stimThresholdSpin.value) or None
        return coords.prepare_stimulation(runDir, items, self.bundle.grid, kind, radius if kind == "points" else None, diameter if kind == "points" else None,
                                          self.stimWeightingCombo.currentData or None, threshold, safeColumn, mask_indices=maskIndices)

    def computeSeedSet(self):
        """Make the seeds of the Coordinates or Stimulation mode and map them with ``cohortmaps``; return the job or None."""
        from LesionNetworkMappingLib import coords
        from LesionNetworkMappingUI import jobrunner

        mode = self.seedMode()
        enabled, reason = self.seedSetComputeState()
        if not enabled:
            self.computeReasonLabel.setText(reason)
            self.computeReasonLabel.setVisible(bool(reason))
            return None
        if not self._preflight():
            return None
        node = self._parameterNode
        runDir = self.logic.runDirectory(self.ctx, mode)
        try:
            lesionsTsv = self.prepareSeedSet(runDir)
        except (OSError, ValueError) as exc:
            self.widgets.setBannerText(self.computeBanner, _("The seeds cannot be made: {error}").format(error=exc))
            self.computeBanner.show()
            return None
        previewN = self.plannedN() if node.subjectsMode == "preview" and self.plannedN() < self.bundle.n_subjects else None
        args = coords.cohortmaps_arguments(lesionsTsv, self.bundle.path, runDir, previewN, node.previewSeed)
        title = _("Mapping the study seeds") if mode == "coordinates" else _("Mapping the stimulation seeds")
        spec = jobrunner.JobSpec("LesionNetworkMappingLib.cohortmaps", args, title=title, heavy=True, kind="cohortmaps", runRoot=os.path.dirname(runDir),
                                 onEvent=self.onCohortEvent, onDone=lambda job, mode=mode, runDir=runDir: self.onSeedSetDone(job, mode, runDir),
                                 name="cohortmaps", statusText=_mappingStatusText, nice=ENGINE_NICE)
        self.widgets.setBannerText(self.computeBanner, "")
        self.computeBanner.hide()
        self.cohortJob = self.ctx.submit(spec)
        self.progress.setJob(self.cohortJob)
        self.progress.widget.show()
        self.updateComputeState()
        self._notifyControllers("onCohortJobStarted", self.cohortJob)
        return self.cohortJob

    def onSeedSetDone(self, job, mode, runDir):
        from LesionNetworkMappingUI import jobrunner

        updateProgressQuietly(self.progress, force=True)
        if job.state == "failed":
            self._showRunFailure(job)
        mapsTsv = os.path.join(runDir, "maps.tsv")
        if job.state == "done" and os.path.isfile(mapsTsv):
            if mode == "coordinates":
                self.coordinateMapsPath = mapsTsv
            else:
                self.stimulationMapsPath = mapsTsv
        self._publishCohortMaps()
        qt.QTimer.singleShot(jobrunner.FINISHED_CHIP_MS + 200, self._refreshStatusChip)
        self.updateCardVisibility()
        self.updateComputeState()
        self._showStimulation()
        self._showCoordinates()
        self._notifyControllers("onCohortMapsChanged", getattr(self.ctx, "cohortMaps", None))
        shell = self._shell()
        if shell is not None and job.state == "done":
            done = job.doneEvent or {}
            shell.toast(_("{n} seed maps ready · see the Cohort card").format(n=done.get("n", "?")), 3000)

    def runCoordinateNull(self):
        """Run the random-coordinate control (``coords null``) in the job runner; return the job or None."""
        from LesionNetworkMappingLib import thresholds
        from LesionNetworkMappingUI import jobrunner

        enabled, reason = self.coordinateNullState()
        if not enabled:
            self.coordNullResultLabel.setText(reason)
            self.coordNullResultLabel.show()
            return None
        node = self._parameterNode
        runDir = os.path.dirname(self.coordinateMapsPath) if self.coordinateMapsPath else self.logic.runDirectory(self.ctx, "coordinates")
        fociPath = os.path.join(runDir, "foci.tsv")
        if not os.path.isfile(fociPath):
            try:
                # Only foci.tsv is needed here (the null makes its own seeds): no brain-mask check
                self.prepareSeedSet(runDir, checkMask=False)
            except (OSError, ValueError) as exc:
                self.coordNullResultLabel.setText(_("The seeds cannot be made: {error}").format(error=exc))
                self.coordNullResultLabel.show()
                return None
        outDir = os.path.join(runDir, "null")
        radius, diameter = self.sphereSettings()
        args = ["null", "--foci", fociPath, "--bundle", self.bundle.path, "--gm-mask", self.coordGmPathEdit.currentPath, "--out", outDir,
                "--k", str(int(self.coordNullKSpin.value)), "--seed", "0", "--rule", thresholds.rule_to_json(self.currentRule()), "--sign", self._sign()]
        args += ["--diameter", f"{diameter:g}"] if diameter is not None else ["--radius", f"{radius:g}"]
        previewN = self.plannedN() if node.subjectsMode == "preview" and self.plannedN() < self.bundle.n_subjects else None
        if previewN:
            args += ["--subjects", str(int(previewN)), "--random", "--subject-seed", str(int(node.previewSeed))]
        spec = jobrunner.JobSpec("LesionNetworkMappingLib.coords", args, title=_("Random-coordinate control"), heavy=True, kind="coords-null", runRoot=os.path.dirname(runDir),
                                 onEvent=lambda event: updateProgressQuietly(self.coordNullProgress, force=event.get("event") != "progress"),
                                 onDone=lambda job, outDir=outDir: self.onCoordinateNullDone(job, outDir), name="coords-null", nice=ENGINE_NICE)
        self.coordinateNullJob = self.ctx.submit(spec)
        self.coordNullProgress.setJob(self.coordinateNullJob)
        self.coordNullProgress.widget.show()
        self.coordNullResultLabel.hide()
        self._showCoordinates()
        return self.coordinateNullJob

    def onCoordinateNullDone(self, job, outDir):
        from LesionNetworkMappingLib import coords

        updateProgressQuietly(self.coordNullProgress, force=True)
        if job.state == "done":
            try:
                with open(os.path.join(outDir, coords.NULL_JSON), encoding="utf-8") as f:
                    record = json.load(f)
                text = _("Random-coordinate control (k={k}): peak overlap {peak:.0f}% of studies, percentile {pct:.1f} of the null peaks, p = {p:.3g}").format(
                    k=record["k"], peak=record["observed_peak_pct"], pct=record["percentile"], p=record["p_peak"])
            except (OSError, ValueError, KeyError) as exc:
                text = _("The random-coordinate control has no result: {error}").format(error=exc)
        elif job.state == "failed":
            text = _("The random-coordinate control failed: {reason}").format(reason=job.failureReason or _("unknown error"))
        else:
            text = _("The random-coordinate control was stopped.")
        self.coordNullResultLabel.setText(text)
        self.coordNullResultLabel.show()
        self._showCoordinates()

    def runStimulationRmap(self):
        """Run the R-map of the stimulation seeds (sLNM on Fz with the outcome; ``--flip`` for TMS); return the job or None."""
        from LesionNetworkMappingLib import coords
        from LesionNetworkMappingUI import jobrunner

        if not self.stimulationRmapState()[0]:
            return None
        mapsTsv = self._seedSetMaps("stimulation")
        runDir = os.path.dirname(mapsTsv)
        record = coords.read_seed_record(runDir) or {}
        column = record.get("outcome_column") or "outcome"
        outcomes = os.path.join(runDir, coords.OUTCOMES_TSV)
        if not os.path.isfile(outcomes):
            self.stimRmapReasonLabel.setText(_("The seeds were mapped without an outcome: map them again with an outcome column."))
            self.stimRmapReasonLabel.show()
            return None
        flip = bool(self._parameterNode.stimulationFlip) if self._parameterNode is not None else False
        outDir = os.path.join(runDir, "rmap-" + column + ("-flip" if flip else ""))
        args = coords.slnm_arguments(mapsTsv, outcomes, column, os.path.join(self.bundle.path, "mask.nii.gz"), outDir, flip=flip, bundle=self.bundle.path)
        spec = jobrunner.JobSpec("LesionNetworkMappingLib.slnm", args, title=_("R-map"), heavy=True, kind="slnm", runRoot=os.path.dirname(runDir),
                                 onEvent=lambda event: updateProgressQuietly(self.stimRmapProgress, force=event.get("event") != "progress"),
                                 onDone=lambda job, outDir=outDir: self.onStimulationRmapDone(job, outDir), name="rmap", nice=ENGINE_NICE)
        self.stimulationRmapJob = self.ctx.submit(spec)
        self.stimRmapProgress.setJob(self.stimulationRmapJob)
        self.stimRmapProgress.widget.show()
        self._showStimulation()
        return self.stimulationRmapJob

    def onStimulationRmapDone(self, job, outDir):
        updateProgressQuietly(self.stimRmapProgress, force=True)
        self._showStimulation()
        if job.state != "done":
            self.stimRmapReasonLabel.setText(_("The R-map failed: {reason}").format(reason=job.failureReason or _("unknown error")))
            self.stimRmapReasonLabel.show()
            return
        maps = sorted(name for name in os.listdir(outDir) if re.search(r"_desc-slnm[A-Za-z0-9]*R_map\.nii\.gz$", name)) if os.path.isdir(outDir) else []
        if maps:
            try:
                self.showMapFile(os.path.join(outDir, maps[0]), label=_("R-map"))
            except Exception:
                logging.exception("Lesion network mapping: the R-map could not be shown")

    def _showSeedMode(self):
        mode = self.seedMode()
        cohort = mode == "cohort"
        self.lesionSeedPanel.setVisible(mode == "lesion")
        self.cohortSeedPanel.setVisible(cohort)
        self.coordinateSeedPanel.setVisible(mode == "coordinates")
        self.stimulationSeedPanel.setVisible(mode == "stimulation")
        self.nullCheckBox.setVisible(mode == "lesion")
        if cohort and self.cohortInfo is None:
            self.refreshCohort()
        self._publishCohortMaps()

    #
    # Seed: cohort
    #

    def _sessionStudy(self):
        shell = self._shell()
        session = getattr(shell, "studySession", None) if shell is not None else None
        return getattr(session, "study", None) if session is not None else None

    def refreshCohort(self):
        """The study of the Cohort seed (the Studio study session's, else the one chosen with Open study…) and its lesions."""
        from LesionNetworkMappingLib.study import Study

        study = self._sessionStudy()
        if study is None:
            path = self.cohortStudy.path if self.cohortStudy is not None else str(qt.QSettings().value(COHORT_STUDY_SETTING) or "")
            node = self._parameterNode
            if not path and node is not None and node.studyPath:
                path = node.studyPath  # scenes of earlier versions
            if path and os.path.isfile(os.path.join(path, "study.json")):
                try:
                    study = self.cohortStudy if self.cohortStudy is not None and self.cohortStudy.path == os.path.abspath(path) else Study.open(path)
                except Exception:
                    logging.exception("Lesion network mapping: the cohort study could not be opened")
                    study = None
        self.cohortStudy = study
        self.cohortInfo = None
        if study is not None:
            try:
                self.cohortInfo = self.logic.cohortSeeds(study, self.bundle)
            except Exception as exc:
                logging.exception("Lesion network mapping: the cohort could not be read")
                self.cohortInfo = {"lesions": [], "excluded": {}, "native": [], "groups": {}, "n": 0, "error": str(exc)}
            self._findCohortMaps()
        if study is not None and study is not self.ctx.study:
            self.ctx.setStudy(study)
            self._notifyControllers("onStudyChanged")
        self._showCohort()
        self.updateComputeState()
        self._notifyControllers("onCohortChanged")

    def _showCohort(self):
        info, study = self.cohortInfo, self.cohortStudy
        if "cohort" in self.seedModes:
            label = self._seedModeLabel("cohort") + (f" ({info['n']})" if info else "")
            self.seedModeGroup.button(self.seedModes.index("cohort")).setText(label)
        self.cohortOpenStudyButton.setVisible(self._sessionStudy() is None)
        self.cohortOpenStudyButton.setText(_("Open study…") if study is None else _("Other study…"))
        if study is None:
            self.cohortStudyLabel.setText(_("Open a study to map its lesions (a study folder made in Library, with participants.tsv)."))
            self.cohortExcludedLabel.hide()
            self.cohortNativeBanner.hide()
            return
        groups = info.get("groups", {}) if info else {}
        groupText = ""
        if groups.get("case") or groups.get("control"):
            groupText = " · " + _("{cases} cases / {controls} controls").format(cases=groups.get("case", 0), controls=groups.get("control", 0))
        self.cohortStudyLabel.setText((_("Study “{name}” · 1 lesion to map") if info and info["n"] == 1 else _("Study “{name}” · {n} lesions to map")).format(name=study.name, n=info["n"] if info else 0) + groupText)
        excluded = (info or {}).get("excluded") or {}
        if excluded or (info or {}).get("error"):
            text = cohortExcludedText(excluded)
            if info.get("error"):
                text = _("The study cannot be read: {error}").format(error=info["error"])
            self.cohortExcludedLabel.setText(text)
            self.cohortExcludedLabel.setVisible(bool(text))
        else:
            self.cohortExcludedLabel.hide()
        native = (info or {}).get("native") or []
        if native:
            self.widgets.setBannerText(self.cohortNativeBanner, _("{n} native lesions not yet normalized (not mapped): normalize them to MNI first.").format(n=len(native)))
        self.cohortNativeBanner.setVisible(bool(native))

    def onOpenCohortStudy(self):
        """Choose the study of the Cohort seed (kept in Studio/LNM/CohortStudy, never in the scene)."""
        start = self.cohortStudy.path if self.cohortStudy is not None else str(qt.QSettings().value(COHORT_STUDY_SETTING) or "")
        path = qt.QFileDialog.getExistingDirectory(slicer.util.mainWindow(), _("Choose a study folder"), start)
        if not path:
            return
        self.openCohortStudy(path)

    def openCohortStudy(self, path):
        """Use the study at ``path`` for the Cohort seed; return the study, or None when the folder is not a study."""
        from LesionNetworkMappingLib.study import Study

        if not os.path.isfile(os.path.join(path, "study.json")):
            slicer.util.errorDisplay(_("This folder is not a study (it has no study.json). Create the study in Library first."), windowTitle=_("Open study"))
            return None
        try:
            study = Study.open(path)
        except Exception as exc:
            slicer.util.errorDisplay(_("The study cannot be opened: {error}").format(error=exc), windowTitle=_("Open study"))
            return None
        qt.QSettings().setValue(COHORT_STUDY_SETTING, study.path)
        self.cohortStudy = study
        self.cohortMapsPath = None
        self.refreshCohort()
        return study

    def onNormalizeInLibrary(self):
        """Native lesions of the cohort: Library's batch normalization (Studio), else the Studio module (Classic)."""
        shell = self._shell()
        if shell is not None:
            shell.switchTo("library")
        elif hasattr(slicer.modules, "studio"):
            slicer.util.selectModule("Studio")

    def _findCohortMaps(self):
        """The finished cohort maps (maps.tsv) of this study, connectome and subjects (All, or the Preview N), if any."""
        study, bundle = self.cohortStudy, self.bundle
        self.cohortMapsPath = None
        if study is not None and bundle is not None:
            candidate = os.path.join(self.cohortOutputDir(), "maps.tsv")
            if os.path.isfile(candidate) and os.path.isfile(os.path.join(os.path.dirname(candidate), "cohortmaps.json")):
                self.cohortMapsPath = candidate
        self._publishCohortMaps()
        return self.cohortMapsPath

    def onSegmentationChanged(self, node):
        if self._updatingGui:
            return
        self._populateSegments(node)
        segmentId = self.segmentSelector.currentData if self.segmentSelector.count else ""
        self._setSeed(node, segmentId)

    def onSegmentChanged(self, index):
        if self._updatingGui or index < 0:
            return
        self._setSeed(self.segmentationSelector.currentNode(), self.segmentSelector.itemData(index) or "")

    def _setSeed(self, node, segmentId):
        if self._parameterNode is None:
            return
        self.ctx.setSeed(node, segmentId)
        self._observeSeed(node)
        self.scheduleSeedUpdate()

    def _populateSegments(self, node, selectId=None):
        wasBlocked = self.segmentSelector.blockSignals(True)
        self.segmentSelector.clear()
        lesionIndex = -1
        if node is not None:
            segmentation = node.GetSegmentation()
            for index in range(segmentation.GetNumberOfSegments()):
                segmentId = segmentation.GetNthSegmentID(index)
                name = segmentation.GetSegment(segmentId).GetName()
                self.segmentSelector.addItem(name, segmentId)
                if name.lower() == "lesion" and lesionIndex < 0:
                    lesionIndex = index
        target = self.segmentSelector.findData(selectId) if selectId else -1
        if target < 0:
            target = lesionIndex if lesionIndex >= 0 else (0 if self.segmentSelector.count else -1)
        self.segmentSelector.setCurrentIndex(target)
        self.segmentSelector.blockSignals(wasBlocked)

    def _observeSeed(self, node):
        if self._observedSeed is not None:
            for event in self._seedEvents():
                self.removeObserver(self._observedSeed, event, self.onSeedModified)
        self._observedSeed = node
        if node is not None:
            for event in self._seedEvents():
                self.addObserver(node, event, self.onSeedModified)

    @staticmethod
    def _seedEvents():
        return (slicer.vtkSegmentation.SegmentAdded, slicer.vtkSegmentation.SegmentRemoved, slicer.vtkSegmentation.SegmentModified,
                slicer.vtkSegmentation.SourceRepresentationModified)

    def onSeedModified(self, caller=None, event=None):
        if caller is not None and caller is self.segmentationSelector.currentNode():
            current = self.segmentSelector.currentData if self.segmentSelector.count else None
            self._populateSegments(caller, current)
            segmentId = self.segmentSelector.currentData if self.segmentSelector.count else ""
            if self._parameterNode is not None and segmentId != (self._parameterNode.seedSegmentId or ""):
                self.ctx.setSeed(caller, segmentId)
        self.scheduleSeedUpdate()

    def scheduleSeedUpdate(self):
        """Check the seed soon; while Map is not shown only remember it (no labelmap export while drawing in Draw)."""
        if not self._entered:
            self._seedDirty = True
            return
        self.seedTimer.start()

    def updateSeed(self):
        """Check the seed against the connectome (geometry line, errors) and refresh the Compute state."""
        self.seedTimer.stop()
        self._seedDirty = False
        segNode, segmentId = self.ctx.seed() if self.ctx is not None else (None, None)
        try:
            self.seedCheck = self.logic.checkSeed(segNode, segmentId, self.bundle)
        except Exception as exc:
            logging.exception("Lesion network mapping: the seed could not be checked")
            self.seedCheck = {"ok": False, "reason": _("The lesion could not be read: {error}").format(error=exc), "kind": "error", "space": None, "volumeMl": 0.0, "qc": None}
        self._showSeed(segNode, segmentId)
        self.updateComputeState()
        self._notifyControllers("onSeedChecked", self.seedCheck)

    def _showSeed(self, segNode, segmentId):
        check = self.seedCheck or {}
        segment = segNode.GetSegmentation().GetSegment(segmentId) if segNode is not None and segmentId else None
        if segment is not None:
            r, g, b = segment.GetColor()
            self.seedSwatch.setStyleSheet(f"background-color: rgb({int(r * 255)},{int(g * 255)},{int(b * 255)}); border-radius: 2px;")
            self.seedSwatch.show()
            self.seedNameLabel.setText(f"{segment.GetName()} · {check.get('volumeMl', 0.0):.2f} mL")
        else:
            self.seedSwatch.hide()
            self.seedNameLabel.setText(_("No lesion selected"))
        space = check.get("space")
        if space:
            name, resolution = space
            self.widgets.setChipLevel(self.seedSpaceChip, "ok", f"{name}" + (f" {resolution:g} mm" if isinstance(resolution, (int, float)) else ""))
            self.seedSpaceChip.show()
        elif check.get("kind") in ("native",) or (segment is not None and check.get("kind") not in ("empty", "none") and self.bundle is None):
            self.widgets.setChipLevel(self.seedSpaceChip, "warn", _("Native space"))
            self.seedSpaceChip.show()
        else:
            self.seedSpaceChip.hide()
        qcValues = check.get("qc")
        if qcValues and self.bundle is not None:
            spacing = abs(float(self.bundle.grid.spacing[0]))
            self.seedGeometryLabel.setText(_("On connectome grid ({spacing:g} mm): {voxels:,} voxels · fractional sum {total:.1f}").format(
                spacing=spacing, voxels=int(qcValues.get("voxels_in_mask", 0)), total=float(qcValues.get("weight_total", 0.0))))
            self.seedGeometryLabel.show()
        else:
            self.seedGeometryLabel.setText("")
            self.seedGeometryLabel.setVisible(False)
        notice = check.get("notice") or ""
        self.seedFamilyLabel.setText(notice)
        self.seedFamilyLabel.setVisible(bool(notice))
        self._updateFamilyNotice()
        reason = check.get("reason") if not check.get("ok") and check.get("kind") not in ("none",) else ""
        self.widgets.setBannerText(self.seedErrorBanner, reason or "")
        self.seedErrorBanner.setVisible(bool(reason))
        self.normalizeLinkButton.setVisible(check.get("kind") == "native")

    def _updateFamilyNotice(self):
        """Show the family notice of the lesion (A-10) where the user maps and reads the result, not only in the Seed card.

        The Seed card collapses to its row as soon as the lesion is done, and the notice usually becomes known later (when a
        connectome is chosen), so the Compute card (before and while the map runs) and the Result card (after) repeat it.
        Only in Seed = Lesion: the other seeds have no lesion template.
        """
        notice = str(self.seedFamilyLabel.text) if hasattr(self, "seedFamilyLabel") and self.seedMode() == "lesion" else ""
        for name in ("computeFamilyLabel", "resultFamilyLabel"):
            label = getattr(self, name, None)
            if label is not None:
                label.setText(notice)
                label.setVisible(bool(notice))

    def onNormalize(self):
        """The native-space action: A-03's one-click normalization when present, else the Normalize to MNI card."""
        segNode, segmentId = self.ctx.seed()
        try:
            from LesionNetworkMappingUI import normalize_controller
        except ImportError:
            normalize_controller = None
        if normalize_controller is not None and hasattr(normalize_controller, "offerNormalize"):
            try:
                normalize_controller.offerNormalize(self.ctx, segNode, segmentId)
                return
            except TypeError:
                normalize_controller.offerNormalize(segNode, segmentId)
                return
        if not self.ctx.focusCard("normalize"):
            slicer.util.infoDisplay(
                _("This lesion is not on an MNI grid (it was traced on a patient scan). Normalize it to MNI space first, for example with "
                  "a registration module, then trace or resample the lesion on the MNI template. One-click normalization arrives with a later update."),
                windowTitle=_("Normalize to MNI"))

    #
    # Cards: Connectome
    #

    def _buildConnectomeCard(self):
        card = self.widgets.card(_("Connectome"), objectName="LNMConnectomeCard")
        layout = qt.QVBoxLayout(card)
        row = qt.QHBoxLayout()
        self.connectomeCombo = qt.QComboBox()
        self.connectomeCombo.setObjectName("LNMConnectomeCombo")
        self.connectomeCombo.setSizeAdjustPolicy(qt.QComboBox.AdjustToMinimumContentsLengthWithIcon)
        self.connectomeCombo.setMinimumContentsLength(12)
        self.connectomeCombo.connect("activated(int)", self.onConnectomeActivated)
        row.addWidget(self.connectomeCombo, 1)
        self.manageButton = qt.QToolButton()
        self.manageButton.setObjectName("LNMConnectomeManageButton")
        self.manageButton.setText(_("Manage…"))
        self.manageButton.setToolButtonStyle(qt.Qt.ToolButtonTextOnly)
        self.manageButton.setProperty("popupMode", qt.QToolButton.InstantPopup)
        self.manageMenu = qt.QMenu(self.manageButton)
        self.manageMenu.connect("aboutToShow()", self._fillManageMenu)
        self.manageButton.setMenu(self.manageMenu)
        row.addWidget(self.manageButton)
        layout.addLayout(row)
        self.connectomeLineLabel = self._label("", role="secondaryText", objectName="LNMConnectomeLine")
        layout.addWidget(self.connectomeLineLabel)

        # Data use terms: a summary, the full text in a popover and the acceptance tick that gates Compute
        termsRow = qt.QHBoxLayout()
        self.termsSummaryLabel = self._label("", objectName="LNMTermsSummary")
        termsRow.addWidget(self.termsSummaryLabel, 1)
        self.termsButton = qt.QToolButton()
        self.termsButton.setObjectName("LNMTermsButton")
        self.termsButton.setText(_("Full terms…"))
        self.termsButton.setAutoRaise(True)
        self.termsButton.setProperty("slicerRole", "ghost")
        self.termsButton.connect("clicked()", self.onShowTerms)
        termsRow.addWidget(self.termsButton, 0, qt.Qt.AlignTop)
        layout.addLayout(termsRow)
        self.acceptTermsCheckBox = qt.QCheckBox(_("I accept these data use terms"))
        self.acceptTermsCheckBox.setObjectName("LNMAcceptTermsCheckBox")
        self.acceptTermsCheckBox.connect("toggled(bool)", self.onAcceptTermsToggled)
        layout.addWidget(self.acceptTermsCheckBox)

        # Empty state (SPEC 7.9, USABILITY M5): how to get a connectome; never fetched here
        self.connectomeEmpty = qt.QWidget()
        self.connectomeEmpty.setObjectName("LNMConnectomeEmptyState")
        emptyLayout = qt.QVBoxLayout(self.connectomeEmpty)
        emptyLayout.setContentsMargins(0, 0, 0, 0)
        # One line (VISUAL 4.5); where GSP1000 comes from and its terms are the tooltip and an item of the ⋯ menu
        self.connectomeEmptyLabel = self._label(_("Map needs a connectome."), objectName="LNMConnectomeEmptyText")
        self.connectomeEmptyLabel.setToolTip(GSP_EMPTY_TEXT)
        emptyLayout.addWidget(self.connectomeEmptyLabel)
        # One row: Get a connectome… (primary), Use the demo, and ⋯ for the other ways (add a bundle, convert)
        buttons = qt.QHBoxLayout()
        buttons.setSpacing(6)
        # The way a first-time user obtains one: the catalog (manager_catalog, D-L1), which downloads only after an explicit click and the
        # acceptance of the provider's live terms text; without the plug-in the button is hidden
        self.getConnectomeButton = qt.QPushButton(_("Get a connectome…"))
        self.getConnectomeButton.setObjectName("LNMGetConnectomeButton")
        self.getConnectomeButton.setProperty("slicerRole", "primary")
        self.getConnectomeButton.setToolTip(_("The connectomes that can be obtained from their providers, with their terms and size; nothing is downloaded until you ask"))
        self.getConnectomeButton.connect("clicked()", self.onGetConnectome)
        self.getConnectomeButton.setVisible(self._hasManagerAction("getConnectome"))
        buttons.addWidget(self.getConnectomeButton, 1)
        self.connectomeMoreButton = qt.QToolButton()
        self.connectomeMoreButton.setObjectName("LNMConnectomeMoreButton")
        self.connectomeMoreButton.setText("⋯")
        self.connectomeMoreButton.setToolTip(_("Other ways to add a connectome"))
        self.connectomeMoreButton.setAccessibleName(_("More connectome actions"))
        self.connectomeMoreButton.setPopupMode(qt.QToolButton.InstantPopup)
        self.connectomeMoreButton.setStyleSheet("QToolButton::menu-indicator { image: none; width: 0px; }")
        self.connectomeMoreButton.setProperty("slicerRole", "ghost")
        moreMenu = qt.QMenu(self.connectomeMoreButton)
        moreMenu.setObjectName("LNMConnectomeMoreMenu")
        moreMenu.addAction(_("Add connectome…")).connect("triggered()", self.onAddBundle)
        moreMenu.addAction(_("Use the demo")).connect("triggered()", self.onCreateDemo)
        moreMenu.addAction(_("Convert…")).connect("triggered()", lambda: self.openManager().openConvert())
        moreMenu.addSeparator()
        moreMenu.addAction(_("GSP1000 on the Harvard Dataverse")).connect("triggered()", lambda: self.widgets.openLink(GSP_DATAVERSE_URL))
        self.connectomeMoreButton.setMenu(moreMenu)
        buttons.addWidget(self.connectomeMoreButton)
        emptyLayout.addLayout(buttons)
        # The demo, for a first try, as a quiet button under the row (the inspector keeps its width)
        self.demoButton = qt.QPushButton(_("Use the demo"))
        self.demoButton.setObjectName("LNMUseDemoButton")
        self.demoButton.setProperty("slicerRole", "ghost")
        self.demoButton.setToolTip(_("Create a small synthetic connectome (SYNTHETIC — not real data) to try Map"))
        self.demoButton.connect("clicked()", self.onCreateDemo)
        emptyLayout.addWidget(self.demoButton, 0, qt.Qt.AlignLeft)
        # The buttons of the other ways (Classic scripts and tests use them): in the ⋯ menu, never shown
        self.addBundleButton = qt.QPushButton(_("Add connectome…"))
        self.addBundleButton.setObjectName("LNMAddConnectomeButton")
        self.addBundleButton.setToolTip(_("Choose a connectome bundle folder (.lnmc) on this computer"))
        self.addBundleButton.connect("clicked()", self.onAddBundle)
        self.convertEmptyButton = qt.QPushButton(_("Convert…"))
        self.convertEmptyButton.setObjectName("LNMConvertConnectomeButton")
        self.convertEmptyButton.setToolTip(_("Convert NIfTI time series or a Lead-DBS connectome that is on this computer into a bundle"))
        self.convertEmptyButton.connect("clicked()", lambda: self.openManager().openConvert())
        for hidden in (self.addBundleButton, self.convertEmptyButton):
            hidden.setParent(self.connectomeEmpty)
            hidden.hide()
        layout.addWidget(self.connectomeEmpty)
        self.connectomeErrorBanner = self.widgets.banner("", (), level="warn")
        self.connectomeErrorBanner.hide()
        layout.addWidget(self.connectomeErrorBanner)
        return card

    def _fillManageMenu(self):
        from LesionNetworkMappingUI import discoverManagerActions

        menu = self.manageMenu
        menu.clear()
        menu.addAction(_("Manage connectomes…"), self.openManager)
        menu.addSeparator()
        menu.addAction(_("Add bundle…"), self.onAddBundle)
        menu.addAction(_("Convert…"), lambda: self.openManager().openConvert())
        menu.addAction(_("Create synthetic demo"), self.onCreateDemo)
        path = self._connectomePath
        removeAction = menu.addAction(_("Remove from the list"), self.onRemoveBundle)
        removeAction.setEnabled(bool(path))
        try:
            actions = discoverManagerActions()
        except Exception:
            logging.exception("Lesion network mapping: the connectome actions could not be discovered")
            actions = []
        if actions:
            menu.addSeparator()
        for spec in actions:
            action = menu.addAction(str(spec["label"]))
            action.connect("triggered()", lambda spec=spec: self._runManagerAction(spec))
            # "always": the action needs no connectome (Get a connectome… is how a first one is obtained)
            action.setEnabled(bool(path) or bool(spec.get("always")))

    def _hasManagerAction(self, actionId):
        from LesionNetworkMappingUI import discoverManagerActions

        try:
            return any(spec["id"] == actionId for spec in discoverManagerActions())
        except Exception:
            logging.exception("Lesion network mapping: the connectome actions could not be discovered")
            return False

    def onGetConnectome(self):
        """Open the catalog of connectomes that can be obtained (manager_catalog, D-L1): nothing is downloaded until the user asks there."""
        try:
            from LesionNetworkMappingUI import manager_catalog

            manager_catalog.openCatalog(self.ctx)
        except Exception as exc:
            logging.exception("Lesion network mapping: the connectome catalog could not be opened")
            slicer.util.errorDisplay(str(exc), windowTitle=_("Get a connectome"))

    def _runManagerAction(self, spec):
        path = self._connectomePath
        try:
            spec["factory"](self.ctx, path)
        except Exception as exc:
            logging.exception(f"Lesion network mapping: the connectome action {spec['id']} failed")
            slicer.util.errorDisplay(str(exc), windowTitle=str(spec["label"]))

    def connectomePath(self):
        """Local folder of the connectome bundle in use ("" without one)."""
        return self._connectomePath

    def openManager(self):
        """Show the connectome manager (non-modal, one per module widget); return it."""
        if self.managerDialog is None:
            self.managerDialog = ConnectomeManagerDialog(self, slicer.util.mainWindow())
        else:
            self.managerDialog.refresh()
        self.managerDialog.show()
        self.managerDialog.raise_()
        return self.managerDialog

    def refreshConnectomes(self, select=None):
        """Fill the connectome combo from the registered bundles and open the selected one.

        Without ``select``, the parameter node's connectome (its identifier, resolved on this computer) is opened;
        a connectome that is not found is reported and the parameter node keeps it (no other bundle is chosen silently).
        """
        paths = self.logic.registeredConnectomes()
        node = self._parameterNode
        current, missing = select or "", ""
        if not current and node is not None:
            if node.connectome:
                current = self.logic.resolveConnectome(node.connectome)
                missing = "" if current else self.logic.connectomeIdentifierName(node.connectome)
            elif node.connectomePath:
                # A scene of an earlier version: the bundle's absolute path (replaced by the identifier once opened)
                legacy = node.connectomePath
                current = legacy if os.path.isfile(os.path.join(legacy, "connectome.json")) else ""
                missing = "" if current else os.path.basename(legacy.rstrip("/\\")) or legacy
        if current and current not in paths and os.path.isdir(current):
            paths.append(current)
        wasBlocked = self.connectomeCombo.blockSignals(True)
        self.connectomeCombo.clear()
        for path in paths:
            label = os.path.basename(path.rstrip("/\\")) or path
            try:
                bundle = self.logic.openBundle(path)
                label = bundle.name + (f" ({DEMO_LABEL})" if self.logic.isSynthetic(bundle) else "")
            except Exception:
                label += " " + _("(cannot be opened)")
            self.connectomeCombo.addItem(label, path)
            self.connectomeCombo.setItemData(self.connectomeCombo.count - 1, path, qt.Qt.ToolTipRole)
        index = self.connectomeCombo.findData(current) if current else -1
        if index < 0 and self.connectomeCombo.count and not missing:
            index = 0
        self.connectomeCombo.setCurrentIndex(index)
        self.connectomeCombo.blockSignals(wasBlocked)
        if self.managerDialog is not None and self.managerDialog.isVisible():
            self.managerDialog.refresh()
        if missing:
            self._showMissingConnectome(missing)
            return
        self._selectConnectome(self.connectomeCombo.itemData(index) if index >= 0 else "")

    def onConnectomeActivated(self, index):
        self._selectConnectome(self.connectomeCombo.itemData(index) if index >= 0 else "")

    def _selectConnectome(self, path):
        self._connectomePath = path or ""
        self.bundle, self.bundleError = None, None
        identifier = ""
        if path:
            try:
                self.bundle = self.logic.openBundle(path)
                identifier = self.logic.rememberConnectome(self.bundle)
            except Exception as exc:
                self.bundle = None
                self.bundleError = str(exc)
        node = self._parameterNode
        if node is not None:
            # The scene keeps the identifier, never the local path (SPEC 9.7 rule 10)
            if (node.connectome or "") != identifier:
                node.connectome = identifier
            if node.connectomePath:
                node.connectomePath = ""
        self._afterConnectomeChanged()

    def _showMissingConnectome(self, name):
        """The scene's connectome is not on this computer: say so, keep the parameter node as it is."""
        self._connectomePath = ""
        self.bundle = None
        self.bundleError = _("the scene uses the connectome “{name}”, which is not registered on this computer. "
                             "Add its folder with Manage > Add bundle…").format(name=name)
        self._afterConnectomeChanged()

    def _afterConnectomeChanged(self):
        self._valuesCache.clear()
        # A run belongs to its connectome (its V, mask and the threshold of its sidecar): another connectome parks it
        changed = self._parkRunOfOtherConnectome()
        self.ctx.setBundle(self.bundle)
        changed = self._restoreParkedRun() or changed
        self._showConnectome()
        self.scheduleSeedUpdate()
        if self.seedMode() == "cohort" and getattr(self, "cohortSeedPanel", None) is not None:
            self.refreshCohort()
        self.updateComputeState()
        if changed:
            self._refreshAfterPark()
        else:
            # The planned threshold rule (and the chip) depend on the connectome: re-resolve them now, not on the next action
            self.refreshResult(reloadMaps=False)

    def _refreshAfterPark(self):
        node = self._parameterNode
        volume = node.resultVolume if node is not None else None
        # A run that finished while another connectome was chosen never had its map loaded (its volume is still "computing")
        self.refreshResult(reloadMaps=volume is not None and volume.GetAttribute(COMPUTING_ATTRIBUTE) is not None and bool(self.runOutputs))

    @staticmethod
    def _connectomeKey(path):
        return os.path.normcase(os.path.normpath(os.path.abspath(path))) if path else ""

    def _runConnectomeSelected(self):
        """True when the shown run was computed with the selected connectome (or there is no run)."""
        if self._runBundle is None:
            return True
        return self.bundle is not None and self._connectomeKey(self.bundle.path) == self._connectomeKey(self._runBundle.path)

    def _runState(self):
        return (self.lesionName, self.runDir, self.runOutputs, self.runN, self.runPartial, self.runPreviewN, self.runDescSuffix)

    def _parkRunOfOtherConnectome(self):
        """Another connectome was chosen after a run: the Result card, the current run (Export and the cards that read it)
        and the rule no longer use that run, whose V and mask are its own connectome's; it comes back when its connectome
        is chosen again (``_restoreParkedRun``). The map volume stays in the scene. Return whether a run was parked.
        """
        if not self.runOutputs or self._runConnectomeSelected() or (self.job is not None and not self.job.isFinished()):
            return False
        node = self._parameterNode
        self._parkedRuns[self._connectomeKey(self._runBundle.path)] = {
            "volume": node.resultVolume if node is not None else None, "ctxVolume": self.ctx.resultVolume, "run": self.ctx.currentRun,
            "mapStamp": dict(self._mapStamp), "state": self._runState(), "runBundle": self._runBundle}
        self.runOutputs, self.runN, self.runPartial, self.runPreviewN, self.runDescSuffix = {}, None, False, None, ""
        self._runBundle = None
        self._mapStamp.clear()
        self._valuesCache.clear()
        self.resolved = None
        if node is not None:
            node.resultVolume = None
        self.ctx.setResultVolume(None)
        self.ctx.setCurrentRun(None)
        return True

    def _parkedRunShown(self):
        """The latest parked run whose map is still in the scene (the Result card names it), or None."""
        for parked in reversed(list(self._parkedRuns.values())):
            volume = parked.get("volume")
            if volume is not None and volume.GetScene() is not None:
                return parked
        return None

    def _restoreParkedRun(self):
        """The connectome of a parked run was chosen again, and the Result card shows nothing else: show that run again."""
        if self.bundle is None or self.runOutputs or self.loadedMap is not None or (self.job is not None and not self.job.isFinished()):
            return False
        parked = self._parkedRuns.pop(self._connectomeKey(self.bundle.path), None)
        volume = parked["volume"] if parked is not None else None
        if volume is None or volume.GetScene() is None:
            return False
        (self.lesionName, self.runDir, self.runOutputs, self.runN, self.runPartial, self.runPreviewN, self.runDescSuffix) = parked["state"]
        self._runBundle = parked["runBundle"]
        self._mapStamp.clear()
        self._mapStamp.update(parked["mapStamp"])
        self._valuesCache.clear()
        node = self._parameterNode
        if node is not None:
            node.resultVolume = volume
        ctxVolume = parked["ctxVolume"]
        self.ctx.setResultVolume(ctxVolume if ctxVolume is not None and ctxVolume.GetScene() is not None else None)
        self.ctx.setCurrentRun(parked["run"])
        self._showLayers(volume)
        return True

    def _showConnectome(self):
        bundle = self.bundle
        hasAny = self.connectomeCombo.count > 0
        self.connectomeEmpty.setVisible(not hasAny)
        self.connectomeCombo.setVisible(hasAny)
        self.manageButton.setVisible(hasAny)
        self.widgets.setBannerText(self.connectomeErrorBanner, _("This connectome cannot be opened: {error}").format(error=self.bundleError) if self.bundleError else "")
        self.connectomeErrorBanner.setVisible(bool(self.bundleError))
        for widget in (self.connectomeLineLabel, self.termsSummaryLabel, self.termsButton, self.acceptTermsCheckBox):
            widget.setVisible(bundle is not None)
        if bundle is None:
            return
        line = self.logic.connectomeLine(bundle)
        if self.logic.isSynthetic(bundle):
            line = f"{DEMO_LABEL} · {line}"
        self.connectomeLineLabel.setText(line)
        terms = (bundle.data_use_terms or "").strip()
        if terms:
            summary = terms.split("\n")[0]
            summary = summary if len(summary) <= 160 else summary[:157].rstrip() + "…"
            self.termsSummaryLabel.setText(_("Data use terms: {summary}").format(summary=summary))
        else:
            self.termsSummaryLabel.setText(_("This bundle states no data use terms. Accept only if you may use these data for this purpose."))
        self.termsButton.setVisible(bool(terms))
        wasBlocked = self.acceptTermsCheckBox.blockSignals(True)
        try:
            self.acceptTermsCheckBox.setChecked(self.logic.termsAccepted(bundle))
        except OSError:
            self.acceptTermsCheckBox.setChecked(False)
        self.acceptTermsCheckBox.blockSignals(wasBlocked)

    def onShowTerms(self):
        """The full data use terms in a popover (a Qt popup: Esc or a click outside closes it)."""
        if self.bundle is None:
            return
        popup = qt.QFrame(self.termsButton)
        popup.setWindowFlags(qt.Qt.Popup)
        popup.setAttribute(qt.Qt.WA_DeleteOnClose)  # one popover per click, deleted when it closes
        popup.setObjectName("LNMTermsPopover")
        popup.setFrameShape(qt.QFrame.StyledPanel)
        layout = qt.QVBoxLayout(popup)
        title = qt.QLabel(_("Data use terms · {name}").format(name=self.bundle.name))
        font = qt.QFont(title.font)
        font.setBold(True)
        title.setFont(font)
        layout.addWidget(title)
        browser = qt.QTextBrowser()
        browser.setPlainText(self.bundle.data_use_terms or "")
        browser.setMinimumSize(360, 220)
        layout.addWidget(browser)
        position = self.termsButton.mapToGlobal(qt.QPoint(0, self.termsButton.height))
        popup.move(position)
        popup.show()
        self._termsPopup = popup

    def onAcceptTermsToggled(self, checked):
        if self.bundle is None:
            return
        self.logic.setTermsAccepted(self.bundle, checked)
        self.updateComputeState()

    def onAddBundle(self):
        """Register a connectome bundle folder chosen by the user (validated by ``ConnectomeBundle.open``)."""
        start = os.path.dirname(self._connectomePath) if self._connectomePath else ""
        path = qt.QFileDialog.getExistingDirectory(slicer.util.mainWindow(), _("Choose a connectome bundle (.lnmc folder)"), start)
        if not path:
            return
        try:
            bundle = self.logic.registerConnectome(path)
        except Exception as exc:
            slicer.util.errorDisplay(_("This folder is not a connectome bundle: {error}").format(error=exc), windowTitle=_("Add connectome"))
            return
        self.refreshConnectomes(select=bundle.path)

    def onRemoveBundle(self):
        """Remove the selected connectome from the registered list (its files are kept).

        The open project keeps naming that connectome (it is shown as not registered, like a scene opened on a computer
        without it) and no other bundle is chosen silently. Return True when the project names it.
        """
        path = self._connectomePath
        if not path:
            return False
        self.logic.unregisterConnectome(path)
        node = self._parameterNode
        named = node is not None and bool(node.connectome)
        if node is not None and node.connectomePath:
            node.connectomePath = ""
        self.refreshConnectomes()
        return named

    def onCreateDemo(self):
        """Write and register the synthetic demo connectome (SYNTHETIC — not real data) in a job, with progress."""
        job = getattr(self, "_demoJob", None)
        if job is not None and not job.isFinished():
            return
        try:
            self._demoJob = self.logic.startDemoJob(onEvent=self._onDemoEvent, onDone=self._onDemoDone)
        except Exception as e:
            logging.exception("Lesion network mapping: the demo job could not be started")
            slicer.util.errorDisplay(_("The demo connectome could not be created."), detailedText=str(e))
            return
        self._updateDemoButton(_("Creating the demo…"))

    def _updateDemoButton(self, busyText=None):
        """The demo button shows the progress of the demo job and is disabled while it runs."""
        button = getattr(self, "demoButton", None)
        if button is None:
            return
        button.setEnabled(busyText is None)
        button.setText(busyText or _("Use the demo"))

    def _onDemoEvent(self, event):
        if event.get("event") == "progress" and event.get("total"):
            percent = int(100 * float(event.get("done") or 0) / float(event["total"]))
            self._updateDemoButton(_("Creating the demo… {percent}%").format(percent=percent))

    def _onDemoDone(self, job):
        from LesionNetworkMappingUI import jobrunner

        self._demoJob = None
        self._updateDemoButton()
        if not job.succeeded():
            if job.state == "failed":
                slicer.util.errorDisplay(_("The demo connectome could not be created."), detailedText=str(job.failureReason or ""))
            return
        try:
            path = self.logic.demoPath()
            self.logic._bundleCache.pop(os.path.abspath(path), None)
            self.logic.registerConnectome(path)
            self.refreshConnectomes(select=os.path.abspath(path))
            # The job runner shows "Done" for a few seconds (nothing was mapped): Map's own chip ("Ready") follows
            qt.QTimer.singleShot(jobrunner.FINISHED_CHIP_MS + 200, self._refreshStatusChip)
        except Exception as e:
            logging.exception("Lesion network mapping: the demo connectome could not be registered")
            slicer.util.errorDisplay(_("The demo connectome could not be created."), detailedText=str(e))
            return
        shell = self._shell()
        if shell is not None:
            shell.toast(_("Demo connectome created · SYNTHETIC — not real data"), 3000)

    #
    # Cards: Compute
    #

    def _buildComputeCard(self):
        card = self.widgets.card(_("Compute"), objectName="LNMComputeCard")
        layout = qt.QVBoxLayout(card)
        self.subjectsFrame, self.subjectsGroup = self.widgets.segmented([_("All"), _("Preview")])
        self.subjectsFrame.setObjectName("LNMSubjectsSegmented")
        self.subjectsGroup.connect("idClicked(int)", self.onSubjectsModeClicked)
        row = qt.QHBoxLayout()
        row.addWidget(self.subjectsFrame)
        self.subjectsLabel = self._label("", role="secondaryText", objectName="LNMSubjectsText")
        row.addWidget(self.subjectsLabel, 1)
        layout.addLayout(row)
        self.nullCheckBox = qt.QCheckBox(_("Specificity QA: 50 relocated lesions"))
        self.nullCheckBox.setObjectName("LNMNullCheckBox")
        self.nullCheckBox.setToolTip(_("Map 50 copies of the lesion moved elsewhere in the brain in the same pass, to compare the map with what any lesion of this shape gives"))
        self.nullCheckBox.connect("toggled(bool)", self.onNullToggled)
        layout.addWidget(self.nullCheckBox)
        # The family notice of the seed (A-10) also lives here: the Seed card collapses once the lesion is done
        self.computeFamilyLabel = self._label("", role="secondaryText", objectName="LNMComputeFamilyNotice")
        self.computeFamilyLabel.setWordWrap(True)
        self.computeFamilyLabel.hide()
        layout.addWidget(self.computeFamilyLabel)
        self.computeButton = qt.QPushButton(_("Map network"))
        self.computeButton.setObjectName("LNMComputeButton")
        self.computeButton.setProperty("slicerRole", "primary")
        self.computeButton.setMinimumHeight(36)
        self.computeButton.connect("clicked()", self.onPrimary)
        layout.addWidget(self.computeButton)
        #: The layout that holds the primary button and its reason line in the Compute card (Studio pins them in the sticky footer)
        self._computeCardLayout = layout
        # Seed = Cohort with a "Run everything" card (A-04c): the cohort maps alone are the secondary "Maps only"
        self.mapsOnlyButton = qt.QPushButton(_("Maps only"))
        self.mapsOnlyButton.setObjectName("LNMMapsOnlyButton")
        self.mapsOnlyButton.setProperty("slicerRole", "secondary")
        self.mapsOnlyButton.setToolTip(_("Compute the network map of every lesion of the study, without the group analyses"))
        self.mapsOnlyButton.connect("clicked()", self.computeCohort)
        self.mapsOnlyButton.hide()
        layout.addWidget(self.mapsOnlyButton)
        self.computeReasonLabel = self._label("", role="secondaryText", objectName="LNMComputeReason")
        layout.addWidget(self.computeReasonLabel)
        self.progress = self.widgets.progressRow(objectNamePrefix="LNM")
        self.progress.widget.hide()
        layout.addWidget(self.progress.widget)
        self.computeBanner = self.widgets.banner("", (), level="warn")
        self.computeBanner.hide()
        layout.addWidget(self.computeBanner)
        self.preflightLayout = qt.QVBoxLayout()
        layout.addLayout(self.preflightLayout)
        return card

    def onSubjectsModeClicked(self, index):
        if self._parameterNode is not None:
            self._parameterNode.subjectsMode = "preview" if index == 1 else "all"
        self._showSubjectsText()
        if self.seedMode() == "cohort":
            self._findCohortMaps()
            self._notifyControllers("onCohortMapsChanged", self.cohortMapsPath)
        self.refreshResult(reloadMaps=False)

    def onNullToggled(self, checked):
        if self._parameterNode is not None and not self._updatingGui:
            self._parameterNode.nullRelocations = 50 if checked else 0
        self._notifyControllers("onRunSettingsChanged")

    def plannedN(self):
        """N of the next run: the preview size, or all the bundle's subjects."""
        if self.bundle is None:
            return None
        node = self._parameterNode
        if node is not None and node.subjectsMode == "preview":
            return min(int(node.previewN), self.bundle.n_subjects)
        return self.bundle.n_subjects

    def _showSubjectsText(self):
        node = self._parameterNode
        if node is None:
            return
        if node.subjectsMode == "preview":
            self.subjectsLabel.setText(_("Preview · N={n} random subjects, seed {seed}").format(n=node.previewN, seed=node.previewSeed))
        elif self.bundle is not None:
            self.subjectsLabel.setText(_("All {n:,} subjects").format(n=self.bundle.n_subjects))
        else:
            self.subjectsLabel.setText(_("All subjects"))

    def computeState(self):
        """(enabled, reason) of Map network; the reason is shown under the button (never only in a tooltip)."""
        from LesionNetworkMappingUI import jobrunner

        mode = self.seedMode()
        override = self.ctx.primaryOverride(mode) if self.ctx is not None else None
        if override is not None:
            enabledFn = override[2]
            try:
                enabled = True if enabledFn is None else bool(enabledFn())
            except Exception:
                enabled = False
            return enabled, "" if enabled else _("Not ready")
        if self.job is not None and (self.job.isRunning() or self.job.isQueued()):
            return False, _("Mapping…")
        if mode == "cohort":
            return self.cohortComputeState()
        if mode in SEED_SET_MODES:
            return self.seedSetComputeState()
        if mode != "lesion":
            return False, _("This seed mode is not available yet.")
        if self.bundle is None:
            return False, _("Add a connectome, or use the demo, to map.")
        if not self.acceptTermsCheckBox.checked:
            return False, _("Accept the data use terms of {name} to map.").format(name=self.bundle.name)
        check = self.seedCheck
        if check is None:
            return False, _("Checking the lesion…")
        if not check.get("ok"):
            return False, check.get("reason") or _("Choose the lesion segment.")
        if not self.ctx.computeEnabled():
            return False, " ".join(self.ctx.computeDisabledReasons()) or _("Not ready")
        runner = jobrunner.instance()
        if runner.isBusy():
            return True, _("Another computation is running: this one will wait for it.")
        return True, ""

    def cohortComputeState(self):
        """(enabled, reason) of mapping the cohort's lesions (the cohort maps job); the seeds in Coordinates and Stimulation."""
        from LesionNetworkMappingUI import jobrunner

        if self.seedMode() in SEED_SET_MODES:
            return self.seedSetComputeState()
        if self.cohortJob is not None and (self.cohortJob.isRunning() or self.cohortJob.isQueued()):
            return False, _("Mapping the cohort…")
        if self.cohortStudy is None:
            return False, _("Open a study to map its lesions.")
        if self.bundle is None:
            return False, _("Add a connectome, or use the demo, to map.")
        if not self.acceptTermsCheckBox.checked:
            return False, _("Accept the data use terms of {name} to map.").format(name=self.bundle.name)
        if not self.cohortInfo or not self.cohortInfo.get("n"):
            return False, _("The study has no lesion to map (see the Seed card).")
        if not self.ctx.computeEnabled():
            return False, " ".join(self.ctx.computeDisabledReasons()) or _("Not ready")
        if jobrunner.instance().isBusy():
            return True, _("Another computation is running: this one will wait for it.")
        return True, ""

    def _cohortButtonText(self):
        n = (self.cohortInfo or {}).get("n") or 0
        return (_("Map the lesion") if n == 1 else _("Map all {n} lesions").format(n=n)) if n else _("Map all lesions")

    def updateComputeState(self):
        if not hasattr(self, "computeButton"):
            return
        mode = self.seedMode()
        override = self.ctx.primaryOverride(mode)
        if override is not None:
            self.computeButton.setText(override[0])
        else:
            self.computeButton.setText(self._cohortButtonText() if mode == "cohort" else self._seedSetButtonText() if mode in SEED_SET_MODES else _("Map network"))
        enabled, reason = self.computeState()
        self.computeButton.setEnabled(enabled)
        self.computeReasonLabel.setText(reason)
        self.computeReasonLabel.setVisible(bool(reason))
        if hasattr(self, "mapsOnlyButton"):
            self.mapsOnlyButton.setVisible(mode == "cohort" and override is not None)
            self.mapsOnlyButton.setEnabled(self.cohortComputeState()[0])
        self._updatePrimaryAction()
        self._updateStatusChip()
        self._updateSteps(enabled, reason)

    def _updateSteps(self, computeEnabled=None, computeReason=""):
        """The title rows of Seed, Connectome, Compute and Result as steps (VISUAL 4.5): a status circle (done, needs
        action, current) and a one-line summary of each.

        In Studio a step collapses to its 44 px row when it becomes done (or, for Compute, when the map was opened from a
        file) and opens again when it needs the user; a click on the row opens it in between (``_applyStepCollapse()``).
        """
        self._updateFamilyNotice()
        steps = {key: self._cardWidgets.get(key, (None, None))[1] for key in ("seed", "connectome", "compute", "result")}
        if any(card is None or card.property("collapsed") is None for card in steps.values()):
            return
        if computeEnabled is None:
            computeEnabled, computeReason = self.computeState()
        check = self.seedCheck or {}
        seedText = str(self.seedNameLabel.text) if hasattr(self, "seedNameLabel") else ""
        seedSpace = str(self.seedSpaceChip.text) if hasattr(self, "seedSpaceChip") and not self.seedSpaceChip.isHidden() else ""
        seedSelected = bool(seedText) and seedText != _("No lesion selected")
        if self.seedMode() == "lesion":
            seedState = "done" if check.get("ok") else ("action" if seedSelected else "current")
            seedSummary = " · ".join(part for part in (seedText, seedSpace) if part)
        else:
            seedState = "done" if computeEnabled else "current"
            seedSummary = {"cohort": _("Cohort"), "coordinates": _("Coordinates"), "stimulation": _("Stimulation")}.get(self.seedMode(), "")
        bundle = self.bundle
        connectomeSummary = str(self.connectomeCombo.currentText) if bundle is not None and hasattr(self, "connectomeCombo") else _("Needs a connectome")
        if bundle is not None and getattr(bundle, "n_subjects", None):
            connectomeSummary = _("{name} · {n} subjects").format(name=connectomeSummary, n=bundle.n_subjects)
        connectomeState = "done" if bundle is not None else "action"
        if bundle is not None and hasattr(self, "acceptTermsCheckBox") and not self.acceptTermsCheckBox.checked:
            # The data use terms are part of the step: it is done once they are accepted
            connectomeState = "action"
            connectomeSummary = _("{name} · accept the data use terms").format(name=str(self.connectomeCombo.currentText))
        hasResult = self.loadedMap is not None or bool(getattr(self, "runOutputs", None)) or (
            self._parameterNode is not None and self._parameterNode.resultVolume is not None)
        if self.loadedMap is not None and not getattr(self, "runOutputs", None):
            # A map opened from a file was not computed here: Compute is not "Done"
            computeState, computeSummary = "", _("Opened from a file")
        elif self._shownRunFailure() is not None:
            # A run that failed after a map is not "Done": the step opens on its failure banner
            computeState, computeSummary = "action", _("Run failed: {reason}").format(reason=self._shownRunFailure()["reason"] or _("unknown error"))
        elif hasResult and self.loadedMap is None and self.runPartial and getattr(self, "runOutputs", None) and not (self.job is not None and not self.job.isFinished()):
            # A stopped run keeps its latest snapshot: it is not "Done" and its specificity check did not finish. The card stays open
            # (a rerun is the next action)
            computeState, computeSummary = "current", _("Stopped · partial map, N = {n:,}").format(n=self.runN or 0)
        elif hasResult:
            computeState, computeSummary = "done", _("Done")
            if getattr(self, "nullCheckBox", None) is not None and self.nullCheckBox.checked and self.seedMode() == "lesion":
                computeSummary = _("Done · specificity check: 50 relocated lesions")
        elif computeEnabled:
            computeState, computeSummary = "current", _("Ready")
        else:
            computeState, computeSummary = "", computeReason or ""
        resultState = "current" if hasResult else ""
        resultSummary = ""
        if self.loadedMap is not None:
            resultSummary = str(self.loadedMap.get("label") or self.loadedMap.get("name") or "")
        if hasResult:
            n = self._resultN() if hasattr(self, "_resultN") else None
            nText = _("N = {n:,}").format(n=n) if n else _("N unknown")
            if n and self.loadedMap is None and self.runPartial and getattr(self, "runOutputs", None):
                nText = _("N = {n:,} (partial)").format(n=n)
            elif n and self.loadedMap is None and self.runPreviewN and getattr(self, "runOutputs", None):
                nText = _("N = {n:,} · Preview").format(n=n)
            resultSummary = " · ".join(part for part in (nText, self.currentStatistic(), resultSummary) if part)
        for number, (key, state, summary) in enumerate((("seed", seedState, seedSummary), ("connectome", connectomeState, connectomeSummary),
                                                         ("compute", computeState, computeSummary), ("result", resultState, resultSummary)), start=1):
            self.widgets.setStep(steps[key], number, state, summary.split("\n")[0])
            self._applyStepCollapse(key, steps[key], state, summary)
        self._showSeedModeFrame()

    def _applyStepCollapse(self, key, card, state, summary):
        """Studio: a step whose state changed collapses when it is done (or neutral, a map opened from a file) and opens when
        it needs the user (current or action). Result stays open. Classic keeps the cards as the user left them.
        """
        previous = self._stepStates.get(key)
        self._stepStates[key] = (state, summary if key == "compute" else None)
        if not self._studioLook or key == "result" or previous == self._stepStates[key]:
            return
        if state in ("current", "action"):
            collapse = False
        elif state == "done" or (key == "compute" and summary == _("Opened from a file")):
            collapse = True
        else:
            return
        if bool(card.collapsed) != collapse:
            card.collapsed = collapse

    def onPrimary(self):
        """The primary action (the button and Ctrl+Enter in Studio): preflight checks, then Map network."""
        mode = self.seedMode()
        override = self.ctx.primaryOverride(mode)
        if override is not None:
            override[1]()
            return
        if mode == "cohort":
            self.computeCohort()
            return
        if mode in SEED_SET_MODES:
            self.computeSeedSet()
            return
        if self._seedDirty or self.seedTimer.isActive() or self.seedCheck is None:
            self.updateSeed()
        enabled, reason = self.computeState()
        if not enabled:
            self.computeReasonLabel.setText(reason)
            self.computeReasonLabel.setVisible(bool(reason))
            return
        if not self._preflight():
            return
        self.compute()

    def _preflight(self):
        """Run the beforeCompute hooks; show failures with their fix actions; return whether Compute may go on."""
        while self.preflightLayout.count():
            item = self.preflightLayout.takeAt(0)
            if item.widget() is not None:
                item.widget().deleteLater()
        failures = [(message, fix) for ok, message, fix in self.ctx.checkBeforeCompute() if not ok]
        for message, fix in failures:
            actions = [fix] if fix else []
            self.preflightLayout.addWidget(self.widgets.banner(message, actions, level="warn"))
        return not failures

    def compute(self):
        """Export the seed lesion and start the engine (non-blocking); return the job."""
        from LesionNetworkMappingLib import thresholds

        node = self._parameterNode
        segNode, segmentId = self.ctx.seed()
        segmentName = segNode.GetSegmentation().GetSegment(segmentId).GetName()
        lesionName = _safeName(self._subjectLabel() or _lesionFallbackLabel(segNode, segmentName))
        runDir = self.logic.runDirectory(self.ctx, lesionName)
        lesionPath = os.path.join(runDir, "lesion", f"{lesionName}.nii.gz")
        self.logic.exportSeedLesion(segNode, segmentId, lesionPath)
        previewN = self.plannedN() if node.subjectsMode == "preview" and self.plannedN() < self.bundle.n_subjects else None
        rule = self.currentRule()
        # The shown result is kept, untouched, until the new run has a map; it comes back if the run ends without one
        self._previousRun = {"volume": node.resultVolume, "ctxVolume": self.ctx.resultVolume, "run": self.ctx.currentRun, "mapStamp": dict(self._mapStamp),
                             "state": self._runState(), "loadedMap": self.loadedMap, "runBundle": self._runBundle}
        self.loadedMap = None
        self._runBundle = self.bundle
        self._parkedRuns.pop(self._connectomeKey(self.bundle.path), None)  # the new run replaces a parked run of this connectome
        self.lesionName, self.runDir = lesionName, runDir
        self.runOutputs, self.runN, self.runPartial = {}, None, False
        self.runPreviewN = previewN
        self.runDescSuffix = f"PreviewN{previewN}" if previewN else ""
        self._mapStamp.clear()
        self._valuesCache.clear()
        self.widgets.setBannerText(self.computeBanner, "")
        self.computeBanner.hide()
        config = {"bundlePath": self.bundle.path, "lesionPath": lesionPath, "runDir": runDir, "previewN": previewN, "previewSeed": node.previewSeed,
                  "nullRelocations": node.nullRelocations, "rule": thresholds.normalize_rule(rule)}
        self._prepareResultVolume()
        self.ctx.setCurrentRun(None)
        self.refreshResult()  # the Result card waits for the new map (no title, rule or Export of the previous run)
        try:
            self.job = self.logic.startRun(config, onEvent=self.onRunEvent, onDone=self.onRunDone, context=self.ctx)
        except Exception:
            self._restorePreviousRun()
            raise
        self.progress.setJob(self.job)
        self.progress.widget.show()
        self.updateComputeState()
        return self.job

    #
    # Compute: cohort
    #

    def cohortOutputDir(self):
        """Where the cohort maps go: ``<study>/derivatives/lnm/conn-<label>[_n-<N>]/cohort`` (N for a Preview)."""
        if self.cohortStudy is None or self.bundle is None:
            return None
        previewN = self.plannedN() if self._parameterNode is not None and self._parameterNode.subjectsMode == "preview" and self.plannedN() < self.bundle.n_subjects else None
        return self.logic.cohortOutputDir(self.cohortStudy.path, self.bundle.name, previewN)

    def computeCohort(self):
        """Map every analysable lesion of the cohort's study with ``cohortmaps`` (batched, cached); return the job or None.

        In Coordinates and Stimulation (the Cohort card's Map button), the seeds of that mode are mapped instead.
        """
        if self.seedMode() in SEED_SET_MODES:
            return self.computeSeedSet()
        if self.seedMode() != "cohort":
            self._parameterNode.seedMode = "cohort"
            self.updateGUIFromParameterNode()
        if self.cohortInfo is None:
            self.refreshCohort()
        enabled, reason = self.cohortComputeState()
        if not enabled:
            self.computeReasonLabel.setText(reason)
            self.computeReasonLabel.setVisible(bool(reason))
            return None
        if not self._preflight():
            return None
        node = self._parameterNode
        outDir = self.cohortOutputDir()
        previewN = self.plannedN() if node.subjectsMode == "preview" and self.plannedN() < self.bundle.n_subjects else None
        config = {"studyPath": self.cohortStudy.path, "bundlePath": self.bundle.path, "outDir": outDir, "lesions": self.cohortInfo["lesions"],
                  "previewN": previewN, "previewSeed": node.previewSeed}
        self.widgets.setBannerText(self.computeBanner, "")
        self.computeBanner.hide()
        self.cohortJob = self.logic.startCohortMaps(config, onEvent=self.onCohortEvent, onDone=self.onCohortDone, context=self.ctx)
        self.progress.setJob(self.cohortJob)
        self.progress.widget.show()
        self.updateComputeState()
        self._notifyControllers("onCohortJobStarted", self.cohortJob)
        return self.cohortJob

    def onCohortEvent(self, event):
        kind = event.get("event")
        if kind in ("progress", "stage", "queued", "start"):
            updateProgressQuietly(self.progress, force=kind != "progress")
        self._notifyControllers("onCohortEvent", event)

    def onCohortDone(self, job):
        from LesionNetworkMappingUI import jobrunner

        updateProgressQuietly(self.progress, force=True)
        if job.state == "failed":
            self._showRunFailure(job)
        self._findCohortMaps()
        qt.QTimer.singleShot(jobrunner.FINISHED_CHIP_MS + 200, self._refreshStatusChip)
        self.updateComputeState()
        self._notifyControllers("onCohortMapsChanged", self.cohortMapsPath)
        shell = self._shell()
        if shell is not None and job.state == "done" and self.cohortMapsPath:
            done = job.doneEvent or {}
            shell.toast((_("{n} lesion map ready · {hits} from the cache") if done.get("n") == 1 else _("{n} lesion maps ready · {hits} from the cache")).format(n=done.get("n", "?"), hits=done.get("cache_hits", 0)), 3000)

    def _prepareResultVolume(self):
        """Set up the result volume on the connectome grid before the run (empty, with the colour table and the
        layers), so that each partial map only updates its voxels: one render per map while the engine runs.

        A new volume, so that an earlier result is never overwritten (SPEC 7.2); only the temporary volume of a
        run that never produced a map (``LNM.Computing``) is reused.
        """
        import numpy as np

        from LesionNetworkMappingLib import display

        node = self._parameterNode
        volume = node.resultVolume if node is not None else None
        bundle = self.bundle
        name = f"{self.lesionName} LNM {self.currentStatistic()} " + _("(computing…)")
        zeros = np.zeros(tuple(reversed(bundle.shape)), dtype=np.float32)
        reuse = (volume is not None and volume.GetScene() is not None and volume.GetAttribute(COMPUTING_ATTRIBUTE) == "1" and not volume.GetSaveWithScene()
                 and volume.GetImageData() is not None and tuple(volume.GetImageData().GetDimensions()) == tuple(bundle.shape))
        if not reuse:
            volume = slicer.util.addVolumeFromArray(zeros, ijkToRAS=bundle.affine, name=name, nodeClassName="vtkMRMLScalarVolumeNode")
        else:
            volume.SetName(name)
        volume.SetAttribute(display.RESULT_ATTRIBUTE, "1")
        volume.SetAttribute(COMPUTING_ATTRIBUTE, "1")
        volume.SetSaveWithScene(False)  # a temporary until the map is complete (also kept out of autosave)
        display.applyResultDisplay(volume, window=float(volume.GetAttribute(display.WINDOW_ATTRIBUTE) or 1.0), threshold=float("inf"), sign=self._sign())
        if node is not None and node.resultVolume is not volume:
            node.resultVolume = volume
        self._mapStamp.clear()
        self._showLayers(volume)

    def _subjectLabel(self):
        shell = self._shell()
        session = getattr(shell, "studySession", None) if shell is not None else None
        try:
            current = session.current() if session is not None else None
        except Exception:
            current = None
        if isinstance(current, str) and current:
            return current if current.startswith("sub-") else f"sub-{current}"
        return None

    def onRunEvent(self, event):
        kind = event.get("event")
        if kind == "progress":
            # Shown at most every 100 ms: an engine reports every subject
            self._pendingProgress = event
            if not self.progressTimer.isActive():
                self.progressTimer.start()
            return
        if kind == "start":
            names = event.get("lesions") or []
            if names:
                self.lesionName = names[0]
            self.progress.update()
        elif kind == "snapshot":
            self.runN = int(event.get("n") or 0)
            self.runPartial = True
            self.runOutputs = self._outputsByKey(event.get("outputs") or [])
            self.scheduleRefresh(reloadMaps=True)
        elif kind == "done":
            self.runN = int(event.get("n") or 0)
            self.runPartial = False
            self.runOutputs = self._outputsByKey(event.get("outputs") or [])
        elif kind == "queued":
            self.progress.update()
        self._notifyControllers("onRunEvent", event)

    def _showPendingProgress(self):
        from LesionNetworkMappingUI import jobrunner

        event, self._pendingProgress = self._pendingProgress, None
        if event is None or self.job is None or not self.job.isRunning():
            return
        done, total = event.get("done"), event.get("total")
        eta = jobrunner.formatEta(event.get("eta"))
        text = _("{done:,} / {total:,} subjects").format(done=int(done or 0), total=int(total or 0)) + (f" · ~{eta}" if eta else "")
        bar = self.progress.bar
        bar.setUpdatesEnabled(False)  # repainted later, not inside setValue (about 30 ms each in the Studio inspector)
        try:
            self.progress.setProgress((done or 0) / total if total else None, text)
        finally:
            bar.setUpdatesEnabled(True)

    def _outputsByKey(self, outputs):
        """{"T", "AvgFz", "AvgR": path} of the run's lesion from an event's output list."""
        bundle = self._runBundle or self.bundle
        if bundle is None or not self.lesionName:
            return {}
        expected = self.logic.mapPaths(self.runDir, self.lesionName, bundle.name, self.runDescSuffix)
        normalized = {os.path.normpath(path) for path in outputs}
        return {key: path for key, path in expected.items() if os.path.normpath(path) in normalized}

    def onRunDone(self, job):
        from LesionNetworkMappingUI import context as contextModule, jobrunner

        self.progress.update()
        runJson = {}
        try:
            with open(os.path.join(self.runDir, "run.json"), encoding="utf-8") as f:
                runJson = json.load(f)
        except (OSError, ValueError, TypeError):
            pass
        self.progressTimer.stop()
        self._pendingProgress = None
        if job.state == "done" and not self.runOutputs:
            self.runOutputs = self._outputsByKey(job.outputs)
        if not self.runOutputs:
            # Stopped before the first partial map, or failed without one: the previous result comes back
            self._restorePreviousRun()
            if job.state != "cancelled":
                self._showRunFailure(job)
            qt.QTimer.singleShot(jobrunner.FINISHED_CHIP_MS + 200, self._refreshStatusChip)
            self.updateComputeState()
            self._notifyControllers("onRunDone", job)
            return
        self._previousRun = None
        if job.state == "done":
            self.runPartial = False
            self.scheduleRefresh(reloadMaps=True)
        elif job.state == "cancelled":
            # Stop keeps the latest snapshot, labelled "N=<n> (partial)"
            self.runPartial = True
            self.scheduleRefresh(reloadMaps=True)
        else:
            # Failed after a partial map: like Stop, the latest snapshot is kept, labelled "N=<n> (partial)". The Compute step
            # says the run failed; when the engine finished but its maps failed the post-run checks (a constant map...), they
            # cannot be exported
            self.runPartial = True
            self._runFailure = {"runDir": self.runDir, "reason": job.failureReason or "", "outputsFailed": getattr(job, "doneEvent", None) is not None}
            self.scheduleRefresh(reloadMaps=True)
            self._showRunFailure(job)
        # The job runner shows "Done" for a few seconds; Map's own chip ("Done · N=1000") follows
        qt.QTimer.singleShot(jobrunner.FINISHED_CHIP_MS + 200, self._refreshStatusChip)
        if self.runOutputs:
            run = contextModule.RunInfo(self.runDir, runJson, list(self.runOutputs.values()), self.runN, self.currentStatistic(), job, self.runPartial)
            self.ctx.setCurrentRun(run)
        if self._parkRunOfOtherConnectome():
            self._refreshAfterPark()  # another connectome was chosen while it ran
        self.updateComputeState()
        self._notifyControllers("onRunDone", job)

    def _shownRunFailure(self):
        """The failure of the shown run (a run that failed after a map, ``onRunDone()``), or None."""
        failure = self._runFailure
        if failure is None or self.loadedMap is not None or not self.runOutputs or not self.runDir or failure["runDir"] != self.runDir:
            return None
        return failure

    def _showRunFailure(self, job):
        reason = job.failureReason or _("unknown error")
        self.widgets.setBannerText(self.computeBanner, _("Run failed: {reason}").format(reason=reason) + (f"\n{_('Log')}: {job.logPath}" if job.logPath else ""))
        self.computeBanner.show()

    def _restorePreviousRun(self):
        """Undo ``compute()`` for a run that ended without a map: remove its temporary volume and show the
        previous result again, as it was (name, saved with the scene, its rule and colour table alphas).
        """
        previous, self._previousRun = self._previousRun, None
        node = self._parameterNode
        temporary = node.resultVolume if node is not None else None
        if temporary is not None and temporary.GetScene() is not None and temporary.GetAttribute(COMPUTING_ATTRIBUTE) == "1":
            scene = temporary.GetScene()
            for index in reversed(range(temporary.GetNumberOfDisplayNodes())):
                if temporary.GetNthDisplayNode(index) is not None:
                    scene.RemoveNode(temporary.GetNthDisplayNode(index))
            if temporary.GetStorageNode() is not None:
                scene.RemoveNode(temporary.GetStorageNode())
            scene.RemoveNode(temporary)
        volume = previous["volume"] if previous is not None else None
        if volume is not None and volume.GetScene() is None:
            volume = None  # removed during the run
        if volume is not None:
            (self.lesionName, self.runDir, self.runOutputs, self.runN, self.runPartial, self.runPreviewN, self.runDescSuffix) = previous["state"]
            self._runBundle = previous.get("runBundle")
            self.loadedMap = previous.get("loadedMap")
            self._mapStamp.clear()
            self._mapStamp.update(previous["mapStamp"])
            run, ctxVolume = previous["run"], previous["ctxVolume"]
        else:
            self.runOutputs, self.runN, self.runPartial, self.runPreviewN, self.runDescSuffix = {}, None, False, None, ""
            self._runBundle = None
            self._mapStamp.clear()
            run, ctxVolume = None, None
        self._valuesCache.clear()
        if node is not None:
            node.resultVolume = volume
        self.ctx.setResultVolume(ctxVolume if ctxVolume is None or ctxVolume.GetScene() is not None else None)
        self.ctx.setCurrentRun(run)
        if volume is not None:
            self._showLayers(volume)
        self._parkRunOfOtherConnectome()  # another connectome was chosen while it ran
        self.refreshResult()

    def stop(self):
        """Stop the running computation (the Stop button; never Esc)."""
        if self.job is not None:
            self.job.stop()

    #
    # Cards: Result
    #

    def _buildResultCard(self):
        card = self.widgets.card(_("Result"), objectName="LNMResultCard")
        layout = qt.QVBoxLayout(card)
        self.resultTitleLabel = self._label(_("No map yet: Map network computes it."), objectName="LNMResultTitle")
        layout.addWidget(self.resultTitleLabel)
        row = qt.QHBoxLayout()
        self.statisticFrame, self.statisticGroup = self.widgets.segmented(list(STATISTICS))
        self.statisticFrame.setObjectName("LNMStatisticSegmented")
        self.statisticGroup.connect("idClicked(int)", self.onStatisticClicked)
        row.addWidget(self.statisticFrame)
        row.addStretch(1)
        self.signFrame, self.signGroup = self.widgets.segmented([SIGN_LABELS[sign] for sign in SIGNS])
        self.signFrame.setObjectName("LNMSignSegmented")
        self.signFrame.setToolTip(_("Sign · ± both tails, + positive, − negative"))  # noqa: RUF001
        self.signGroup.connect("idClicked(int)", self.onSignClicked)
        row.addWidget(self.signFrame)
        layout.addLayout(row)

        form = qt.QFormLayout()
        ruleRow = qt.QHBoxLayout()
        self.ruleCombo = qt.QComboBox()
        self.ruleCombo.setObjectName("LNMRuleCombo")
        # The longest rule names do not set the width of the inspector (340 px): the combo shows them elided
        self.ruleCombo.setSizeAdjustPolicy(qt.QComboBox.AdjustToMinimumContentsLengthWithIcon)
        self.ruleCombo.setMinimumContentsLength(10)
        from LesionNetworkMappingLib import thresholds

        for kind in RULE_KINDS:
            self.ruleCombo.addItem(thresholds.RULE_LABELS[kind], kind)
        self.ruleCombo.connect("activated(int)", self.onRuleKindChanged)
        ruleRow.addWidget(self.ruleCombo, 1)
        self.ruleValueSpinBox = qt.QDoubleSpinBox()
        self.ruleValueSpinBox.setObjectName("LNMRuleValue")
        self.ruleValueSpinBox.setKeyboardTracking(False)
        self.ruleValueSpinBox.connect("valueChanged(double)", self.onRuleValueChanged)
        ruleRow.addWidget(self.ruleValueSpinBox)
        form.addRow(_("Threshold"), ruleRow)
        import ctk

        self.opacitySlider = ctk.ctkSliderWidget()
        self.opacitySlider.setObjectName("LNMOpacitySlider")
        self.opacitySlider.minimum = 0.0
        self.opacitySlider.maximum = 1.0
        self.opacitySlider.singleStep = 0.05
        self.opacitySlider.decimals = 2
        self.opacitySlider.connect("valueChanged(double)", self.onOpacityChanged)
        # Studio shows the opacity as a percentage after the slider (VISUAL 4.5); Classic keeps the spin box
        opacityRow = qt.QHBoxLayout()
        opacityRow.setSpacing(8)
        opacityRow.addWidget(self.opacitySlider, 1)
        self.opacityPercentLabel = self._label("", wrap=False, objectName="LNMOpacityPercent")
        self.opacityPercentLabel.setSizePolicy(qt.QSizePolicy.Fixed, qt.QSizePolicy.Preferred)
        self.opacityPercentLabel.setAlignment(qt.Qt.AlignRight | qt.Qt.AlignVCenter)
        self.opacityPercentLabel.setMinimumWidth(self.opacityPercentLabel.fontMetrics().horizontalAdvance("100%") + 4)
        self.opacityPercentLabel.hide()
        self.opacitySlider.connect("valueChanged(double)", self._showOpacityPercent)
        opacityRow.addWidget(self.opacityPercentLabel)
        form.addRow(_("Opacity"), opacityRow)
        layout.addLayout(form)
        self.derivedLabel = self._label("", role="secondaryText", objectName="LNMDerivedLine")
        self.derivedLabel.setTextInteractionFlags(qt.Qt.TextSelectableByMouse)
        layout.addWidget(self.derivedLabel)
        # The seed's family notice (A-10) stays visible with the map, after the Seed and Compute cards have collapsed
        self.resultFamilyLabel = self._label("", role="secondaryText", objectName="LNMResultFamilyNotice")
        self.resultFamilyLabel.setWordWrap(True)
        self.resultFamilyLabel.hide()
        layout.addWidget(self.resultFamilyLabel)
        # Studio: the explanations of the rule and the display (N unknown, shown unthresholded, notes) are one warning line
        # with "Details" (VISUAL 4.5); Classic shows them as paragraphs
        self.resultNotice = self.widgets.noticeLine("LNMResultNotice")
        layout.addWidget(self.resultNotice)
        self.ruleBanner = self.widgets.banner("", ((_("Switch to FWE"), self.onSwitchToFwe), (_("Keep"), self.onKeepRule)), level="warn")
        self.ruleBanner.setObjectName("LNMRuleBanner")
        self.ruleBanner.hide()
        layout.addWidget(self.ruleBanner)
        self.ruleNotesLabel = self._label("", role="caption", objectName="LNMRuleNotes")
        self.ruleNotesLabel.hide()
        layout.addWidget(self.ruleNotesLabel)
        self.emptyResultLabel = self._label("", role="secondaryText", objectName="LNMEmptyResult")
        self.emptyResultLabel.hide()
        layout.addWidget(self.emptyResultLabel)

        # Peak region (the cached atlases, looked up in the background), x, y, z (RAS mm) and the value, hot or cold (VISUAL 4.5)
        self.peaksTable = self.widgets.tableView([_("Peak region"), _("x, y, z"), _("value")])
        self.peaksTable.setObjectName("LNMPeaksTable")
        self.peaksTable.setToolTip(_("Top 5 peaks, at least 10 mm apart (RAS mm). Click a peak to go there."))
        header = self.peaksTable.horizontalHeader()
        header.setSectionResizeMode(0, qt.QHeaderView.Stretch)
        header.setSectionResizeMode(1, qt.QHeaderView.ResizeToContents)
        header.setSectionResizeMode(2, qt.QHeaderView.ResizeToContents)
        for column in range(3):
            headerItem = self.peaksTable.horizontalHeaderItem(column)
            if headerItem is not None:
                headerAlignment = (qt.Qt.AlignLeft if column == 0 else qt.Qt.AlignRight) | qt.Qt.AlignVCenter
                try:
                    headerItem.setTextAlignment(headerAlignment)
                except (TypeError, ValueError):
                    headerItem.setTextAlignment(int(headerAlignment))  # Qt 5 takes an int, Qt 6 the flags
        self._peakRegionJob = None
        self.peaksTable.setMaximumHeight(170)
        self.peaksTable.connect("cellClicked(int,int)", self.onPeakClicked)
        self.peaksTable.hide()
        layout.addWidget(self.peaksTable)
        buttons = qt.QHBoxLayout()
        self.binarizeButton = qt.QPushButton(_("Binarize"))
        self.binarizeButton.setObjectName("LNMBinarizeButton")
        self.binarizeButton.setProperty("slicerRole", "secondary")
        self.binarizeButton.setToolTip(_("Create a 0/1 volume of the voxels that pass the threshold"))
        self.binarizeButton.connect("clicked()", self.onBinarize)
        self.binarizeButton.setEnabled(False)
        buttons.addWidget(self.binarizeButton)
        self.resultExportButton = qt.QPushButton(_("Export…"))
        self.resultExportButton.setObjectName("LNMResultExportButton")
        self.resultExportButton.setProperty("slicerRole", "secondary")
        self.resultExportButton.connect("clicked()", self.onExport)
        self.resultExportButton.setEnabled(False)
        buttons.addWidget(self.resultExportButton)
        buttons.addStretch(1)
        layout.addLayout(buttons)
        self._peaks = []
        return card

    def currentRule(self):
        from LesionNetworkMappingLib import thresholds

        text = self._parameterNode.thresholdRule if self._parameterNode is not None else ""
        try:
            return thresholds.rule_from_json(text)
        except ValueError:
            return thresholds.normalize_rule(None)

    def setRule(self, rule, peaks=None):
        """Set the threshold rule (dict), store it in the parameter node and re-resolve it.

        ``peaks`` also recomputes the peak table (a rule change that comes with a new sign).
        """
        from LesionNetworkMappingLib import thresholds

        rule = thresholds.normalize_rule(rule)
        if self._parameterNode is not None:
            self._parameterNode.thresholdRule = thresholds.rule_to_json(rule)
        self.ctx.setRule(rule)
        self._showRuleControls(rule)
        self.refreshResult(reloadMaps=False, peaks=peaks)

    def _showRuleControls(self, rule):
        self._updatingGui = True
        try:
            self.ruleCombo.setCurrentIndex(max(0, self.ruleCombo.findData(rule["kind"])))
            spin = self.ruleValueSpinBox
            if rule["kind"] == "fwe_bonferroni":
                spin.setPrefix("α ")  # noqa: RUF001
                spin.setSuffix("")
                spin.setDecimals(3)
                spin.setRange(0.001, 0.5)
                spin.setSingleStep(0.01)
                spin.setValue(rule["alpha"])
            elif rule["kind"] == "top_pct":
                spin.setPrefix(_("top "))
                spin.setSuffix(" %")
                spin.setDecimals(1)
                spin.setRange(0.1, 99.9)
                spin.setSingleStep(1.0)
                spin.setValue(rule["value"])
            elif rule["kind"] == "fz_abs":
                spin.setPrefix("|Fz| ≥ ")
                spin.setSuffix("")
                spin.setDecimals(3)
                spin.setRange(0.001, 5.0)
                spin.setSingleStep(0.01)
                spin.setValue(rule["value"])
            else:
                spin.setPrefix("|T| ≥ ")
                spin.setSuffix("")
                spin.setDecimals(2)
                spin.setRange(0.1, 100.0)
                spin.setSingleStep(0.5)
                spin.setValue(rule["value"])
        finally:
            self._updatingGui = False

    def onRuleKindChanged(self, index):
        from LesionNetworkMappingLib import thresholds

        kind = self.ruleCombo.itemData(index)
        rule = {"kind": kind}
        if kind == "custom_t":
            rule["reference_n"] = self.runN or self.plannedN() or None
        if kind == "top_pct":
            rule["sign"] = self._sign()
            rule["statistic"] = "T" if self.currentStatistic() == "T" else "Fz"
        self._ruleOverride = False
        self.setRule(thresholds.normalize_rule(rule))

    def onRuleValueChanged(self, value):
        if self._updatingGui:
            return
        rule = dict(self.currentRule())
        if rule["kind"] == "fwe_bonferroni":
            rule["alpha"] = float(value)
        else:
            rule["value"] = float(value)
        self.setRule(rule)

    def onSwitchToFwe(self):
        self._ruleOverride = False
        self.setRule({"kind": "fwe_bonferroni", "alpha": 0.05})

    def onKeepRule(self):
        """Keep a rule defined for another N (the choice is recorded in the rule and in provenance)."""
        rule = dict(self.currentRule())
        rule["override"] = True
        self._ruleOverride = True
        self.setRule(rule)

    def _sign(self):
        node = self._parameterNode
        return node.sign if node is not None and node.sign in SIGNS else "both"

    def onSignClicked(self, index):
        if self._parameterNode is None:
            return
        self._parameterNode.sign = SIGNS[index]
        rule = self.currentRule()
        if rule["kind"] == "top_pct" and rule.get("sign") != SIGNS[index]:
            rule = dict(rule, sign=SIGNS[index])
            self.setRule(rule, peaks=True)  # the peak table follows the sign, as for the other rules
            return
        self.refreshResult(reloadMaps=False, peaks=True)

    def currentStatistic(self):
        node = self._parameterNode
        return node.statistic if node is not None and node.statistic in STATISTICS else "T"

    def onStatisticClicked(self, index):
        if self._parameterNode is None or self._updatingGui:
            return
        loaded = self.loadedMap
        if loaded is not None and STATISTICS[index] != loaded.get("statistic") and not (loaded.get("siblings") or {}).get(STATISTICS[index]):
            # A map shown from a file or a scene: only the statistics whose files are next to it can be shown
            self.statisticGroup.button(STATISTICS.index(loaded.get("statistic", "T"))).setChecked(True)
            shell = self._shell()
            if shell is not None:
                shell.toast(_("Only the {statistic} map is open: its {other} map is not next to it.").format(statistic=loaded.get("statistic"), other=STATISTICS[index]))
            return
        self._parameterNode.statistic = STATISTICS[index]
        self.refreshResult(reloadMaps=True)

    def _showOpacityPercent(self, value=None):
        value = self.opacitySlider.value if value is None else value
        self.opacityPercentLabel.setText(f"{round(100 * float(value))}%")

    def _applyResultPresentation(self, studio):
        """Studio: the opacity as a percentage (no spin box); Classic: the slider with its spin box."""
        if not hasattr(self, "opacitySlider"):
            return
        self.opacitySlider.spinBoxVisible = not studio
        self.opacityPercentLabel.setVisible(bool(studio))
        self._showOpacityPercent()

    def onOpacityChanged(self, value):
        if self._updatingGui or self._parameterNode is None:
            return
        self._parameterNode.opacity = float(value)
        from LesionNetworkMappingLib import display

        if self._parameterNode.resultVolume is not None:
            display.setForegroundOpacity(value)
        self._refreshMapOverlay()

    def _ruleAppliesToShownMap(self):
        """True when the resolved rule thresholds the map shown: it is applied (allowed, or kept with Keep), its value is
        finite, and it is a rule on the statistic shown (never r). The legend and Binarize use the same condition as the colours.
        """
        resolved = self.resolved
        if resolved is None or not math.isfinite(resolved.value):
            return False
        rule = self.currentRule()
        statistic = self.currentStatistic()
        return bool(resolved.allowed or rule.get("override")) and statistic != "r" and statistic == self._ruleStatistic(rule)

    def _ruleHidesShownMap(self):
        """True when the rule is on the statistic shown but is not applied to this map (or has no finite value): the colours
        then show nothing ("Nothing is shown: the rule is not applied to this map"; refreshResult).
        """
        resolved = self.resolved
        if resolved is None:
            return False
        rule = self.currentRule()
        statistic = self.currentStatistic()
        if statistic == "r" or statistic != self._ruleStatistic(rule):
            return False
        return not (resolved.allowed or rule.get("override")) or not math.isfinite(resolved.value)

    def _ruleStatistic(self, rule):
        if rule["kind"] == "top_pct":
            return rule.get("statistic", "Fz")
        return "Fz" if rule["kind"] == "fz_abs" else "T"

    def _hasResult(self):
        """True when the Result card has a map: a run's (with its connectome) or one shown from a file or a scene."""
        return (bool(self.runOutputs) and self.bundle is not None and self._runConnectomeSelected()) or self.loadedMap is not None

    def _loadedOnBundleGrid(self):
        """True when the loaded map lies on the grid of the open connectome (its mask then gives V and the voxels)."""
        node = self._parameterNode
        volume = node.resultVolume if node is not None else None
        if self.bundle is None or volume is None or volume.GetImageData() is None:
            return False
        if tuple(volume.GetImageData().GetDimensions()) != tuple(self.bundle.shape):
            return False
        import numpy as np

        matrix = vtk.vtkMatrix4x4()
        volume.GetIJKToRASMatrix(matrix)
        affine = np.array([[matrix.GetElement(row, column) for column in range(4)] for row in range(4)])
        return bool(np.allclose(affine, self.bundle.affine, atol=1e-4))

    def _loadedGeometry(self, array):
        """(grid, voxel indices) of a loaded map: the connectome mask on its grid, else the finite non-zero voxels of the map."""
        import numpy as np

        from LesionNetworkMappingLib.geometry import Grid

        if self._loadedOnBundleGrid():
            return self.bundle.grid, self.bundle.mask_indices
        node = self._parameterNode
        matrix = vtk.vtkMatrix4x4()
        node.resultVolume.GetIJKToRASMatrix(matrix)
        affine = np.array([[matrix.GetElement(row, column) for column in range(4)] for row in range(4)])
        ijk = np.transpose(np.asarray(array), (2, 1, 0))
        flat = ijk.ravel()
        indices = np.flatnonzero(np.isfinite(flat) & (flat != 0))
        return Grid(ijk.shape, affine), indices

    def _loadedValues(self, statistic):
        """Voxel values of the loaded map of ``statistic`` (the shown volume, or its sibling file), with their geometry."""
        import numpy as np

        node = self._parameterNode
        volume = node.resultVolume if node is not None else None
        if volume is None or volume.GetImageData() is None:
            return None
        if statistic == self.loadedMap.get("statistic"):
            stamp = ("loaded", statistic, volume.GetImageData().GetMTime())
            cached = self._valuesCache.get(statistic)
            if cached is not None and cached[0] == stamp:
                return cached[1]
            array = slicer.util.arrayFromVolume(volume)
        else:
            path = (self.loadedMap.get("siblings") or {}).get(statistic)
            if not path or not os.path.isfile(path):
                return None
            stamp = ("loaded", path, os.stat(path).st_mtime_ns)
            cached = self._valuesCache.get(statistic)
            if cached is not None and cached[0] == stamp:
                return cached[1]
            array, _affine = self.logic.readMap(path)
        grid, indices = self._loadedGeometry(slicer.util.arrayFromVolume(volume))
        values = np.transpose(np.asarray(array), (2, 1, 0)).ravel()[indices].astype(np.float64)
        self._valuesCache[statistic] = (stamp, (values, grid, indices))
        return values, grid, indices

    def _resultN(self):
        if self.loadedMap is not None:
            return self.loadedMap.get("n")
        return self.runN if self.runN else self.plannedN()

    def _mapValues(self, statistic):
        """In-mask values of the run's map of ``statistic`` (read from its file, cached per file version)."""
        if self.loadedMap is not None:
            loaded = self._loadedValues(statistic)
            return loaded[0] if loaded is not None else None
        path = self.runOutputs.get(STATISTIC_KEYS[statistic])
        if not path or self.bundle is None or not os.path.isfile(path):
            return None
        stamp = (path, os.stat(path).st_mtime_ns, self.runN)
        cached = self._valuesCache.get(statistic)
        if cached is not None and cached[0] == stamp:
            return cached[1]
        data, _affine = self.logic.readMap(path)
        values = self.logic.maskedValues(data, self.bundle)
        self._valuesCache[statistic] = (stamp, values)
        return values

    def _resultName(self, statistic):
        if self.loadedMap is not None:
            n = self.loadedMap.get("n")
            return f"{self.loadedMap.get('label') or self.loadedMap.get('name')} LNM {statistic}" + (f" N={n}" if n else "")
        name = f"{self.lesionName or 'lesion'} LNM {statistic} N={self.runN}"
        if self.runPreviewN:
            name += " Preview"
        if self.runPartial:
            name += " (partial)"
        return name

    def scheduleRefresh(self, reloadMaps=False):
        """Refresh the result on the next event loop turn (coalesced; used for engine events)."""
        self._pendingReload = self._pendingReload or reloadMaps
        self.refreshTimer.start()

    def _onRefreshTimer(self):
        if self.ctx is None or getattr(slicer.modules, "LesionNetworkMappingWidget", None) is not self:
            return
        reloadMaps, self._pendingReload = self._pendingReload, False
        self.refreshResult(reloadMaps=reloadMaps, deferred=True)

    def refreshResult(self, reloadMaps=False, peaks=None, deferred=False):
        """Show the current map: load it when needed, re-resolve the rule for its N and rewrite the colour table alphas.

        With ``deferred`` (engine events) the peak table is updated in a later event loop turn; the map and
        its colour table change in the same turn, so that the views render once per new map.
        """
        if not hasattr(self, "derivedLabel"):
            return
        node = self._parameterNode
        statistic = self.currentStatistic()
        resultVolume = node.resultVolume if node is not None else None
        hasMap = bool(self.runOutputs) and self.bundle is not None and self._runConnectomeSelected()
        self._refreshGeneration += 1

        # Map: load or update the volume (never on a pure threshold change)
        mapChanged = False
        loaded = self.loadedMap
        if loaded is not None and reloadMaps and statistic != loaded.get("statistic") and (loaded.get("siblings") or {}).get(statistic):
            # A map shown from a file: the other statistic of the same lesion, in the same volume
            self.showMapFile(loaded["siblings"][statistic], label=loaded.get("label"))
            return
        if hasMap and (reloadMaps or resultVolume is None):
            path = self.runOutputs.get(STATISTIC_KEYS[statistic])
            if path and os.path.isfile(path):
                stamp = (path, os.stat(path).st_mtime_ns, self.runN, self.runPartial)
                if reloadMaps or self._mapStamp.get("volume") != stamp or resultVolume is None:
                    saveWithScene = not self.runPartial or not (self.job is not None and self.job.isRunning())
                    saveWithScene = saveWithScene and not self.runPreviewN
                    # The map is in the connectome's template space (a code 4 file, as the engine wrote it)
                    attributes = {"LNM.Statistic": statistic, "LNM.N": self.runN, "LNM.Partial": "1" if self.runPartial else "0",
                                  "Studio.Space": self.logic.connectomeSpaceName(self._runBundle or self.bundle)}
                    newVolume = self.logic.loadMap(path, self._resultName(statistic), resultVolume, saveWithScene=saveWithScene, attributes=attributes)
                    self._mapStamp["volume"] = stamp
                    mapChanged = True
                    if newVolume.GetAttribute(COMPUTING_ATTRIBUTE) is not None:
                        newVolume.RemoveAttribute(COMPUTING_ATTRIBUTE)
                        self._revealCard("result")  # the run's first map: scroll the Result card into view
                    self._previousRun = None  # the new run has a map
                    if resultVolume is None or newVolume is not resultVolume:
                        resultVolume = newVolume
                        if node is not None:
                            node.resultVolume = newVolume
                        self._showLayers(newVolume)
                    self.ctx.setResultVolume(newVolume)
        elif hasMap and resultVolume is not None and resultVolume.GetName() != self._resultName(statistic):
            resultVolume.SetName(self._resultName(statistic))
        self._refreshRule(mapChanged, peaks, deferred)

    def _refreshRule(self, mapChanged, peaks, deferred):
        """Second step of ``refreshResult``: the rule for the current N, the colour table alphas, the peaks."""
        from LesionNetworkMappingLib import display, thresholds

        node = self._parameterNode
        rule = self.currentRule()
        statistic = self.currentStatistic()
        n = self._resultN()
        resultVolume = node.resultVolume if node is not None else None
        hasMap = self._hasResult()
        loaded = self.loadedMap
        self.binarizeButton.setEnabled(False)  # enabled below once the rule is resolved and applies to the map shown
        failure = self._shownRunFailure()
        self.resultExportButton.setEnabled(hasMap and resultVolume is not None and loaded is None and not (failure is not None and failure["outputsFailed"]))
        if loaded is not None:
            state = _("N={n}").format(n=n) if n else _("N unknown")
            if loaded.get("partial"):
                state = _("N={n} (partial)").format(n=n)
            source = _("from the scene") if loaded.get("fromScene") else _("opened from a file")
            self.resultTitleLabel.setText(f"{loaded.get('label') or loaded.get('name')} · {statistic} · {state} · {source}")
        elif hasMap:
            self.resultTitleLabel.setText(_("{name} · {state}").format(
                name=f"{self.lesionName} · {statistic}", state=(_("N={n} (partial)") if self.runPartial else _("N={n}")).format(n=self.runN)
                + (_(" · Preview") if self.runPreviewN else "")))
        elif resultVolume is not None and resultVolume.GetAttribute(COMPUTING_ATTRIBUTE) == "1":
            self.resultTitleLabel.setText(_("Mapping: the map appears with the first partial result."))
        elif self._parkedRunShown() is not None:
            parked = self._parkedRunShown()
            self.resultTitleLabel.setText(_("No map with this connectome yet: the map of {lesion} was computed with {connectome}; choose that connectome to show it again.").format(
                lesion=parked["state"][0] or _("the lesion"), connectome=parked["runBundle"].name))
        else:
            self.resultTitleLabel.setText(_("No map yet: Map network computes it."))
        # Studio: with a map the step row of Result names it (N, statistic, name); the line says what to do without one
        self.resultTitleLabel.setVisible(not self._studioLook or not hasMap)

        if not hasMap and self.bundle is not None and self._preloading and "scipy.stats" not in sys.modules and rule["kind"] in ("fwe_bonferroni", "t_convention", "custom_t"):
            # The planned threshold waits for the background import of scipy (never a long freeze on entering Map)
            self.derivedLabel.setText(_("Resolving the threshold rule…"))
            self.emptyResultLabel.hide()
            self.peaksTable.hide()
            self._showResultNotice()
            return

        # Rule: re-resolved for the current N on every update
        self.resolved = None
        banner, notes, empty = "", [], ""
        resolvable = (self.bundle is not None and n) or (loaded is not None and (n or rule["kind"] in thresholds.N_FREE_KINDS))
        if resolvable:
            ruleStatistic = self._ruleStatistic(rule)
            values = self._mapValues(ruleStatistic) if hasMap else None
            if loaded is not None:
                note = "partial" if loaded.get("partial") else ("preview" if loaded.get("preview") else None)
            else:
                note = "partial" if self.runPartial else ("preview" if (self.runPreviewN if hasMap else node is not None and node.subjectsMode == "preview") else None)
            try:
                self.resolved = self._resolveRule(rule, n, values, note)
            except ValueError as exc:
                self.derivedLabel.setText(str(exc))
            if self.resolved is not None:
                fraction = self.resolved.fraction
                line = thresholds.describe(self.resolved, fraction)
                if not hasMap:
                    line = _("Planned: {line}").format(line=line)
                self.derivedLabel.setText(line)
                banner = self.resolved.banner or ""
                if not self.resolved.allowed and not banner:
                    banner = _("This rule is not applied to this map.")
                notes = list(self.resolved.notes)
                if loaded is not None and not self._loadedOnBundleGrid():
                    notes.append(_("V = {v:,} non-zero voxels of this map (its connectome is not open).").format(v=self.resolved.v))
        elif loaded is not None:
            # A rule derived from N (FWE, the |T| >= 7 convention) cannot be resolved for a map whose N is unknown: say so
            self.derivedLabel.setText(_("The N of this map is unknown (no sidecar): {rule} needs N. Use Custom T, an Fz or a Top x% rule, or open its run.").format(
                rule=thresholds.RULE_LABELS.get(rule["kind"], rule["kind"])))
        else:
            self.derivedLabel.setText(_("Choose a connectome to resolve the threshold rule."))
        if loaded is not None and self.bundle is None and self.bundleError:
            notes.insert(0, _("Its connectome is not on this computer: {error}").format(error=self.bundleError))
        self.widgets.setBannerText(self.ruleBanner, banner)
        self.ruleBanner.setVisible(bool(banner))
        self.ruleNotesLabel.setText(" ".join(notes))
        self.ruleNotesLabel.setVisible(bool(notes))

        # Binarize makes a mask only of what the colours show: the rule applied to the map shown
        self.binarizeButton.setEnabled(bool(hasMap and resultVolume is not None and self._ruleAppliesToShownMap()))

        # Display: only the colour table alphas change
        self.lastPassing = None
        if hasMap and resultVolume is not None and self.resolved is not None:
            sign = self._sign()
            ruleStatistic = self._ruleStatistic(rule)
            applied = self.resolved.allowed or rule.get("override")
            if statistic == "r" or statistic != ruleStatistic:
                window = self._displayWindow(resultVolume, mapChanged)
                threshold = window / 64.0  # near-zero values hidden; the rule applies to another statistic
                display.applyResultDisplay(resultVolume, window=window, threshold=threshold, sign=sign)
                empty = _("The {statistic} map is shown unthresholded; the rule applies to the {rule} map.").format(statistic=statistic, rule=ruleStatistic)
            elif not applied or not math.isfinite(self.resolved.value):
                window = self._displayWindow(resultVolume, mapChanged)
                display.applyResultDisplay(resultVolume, window=window, threshold=window * 2.0 + 1.0, sign=sign)
                empty = _("Nothing is shown: the rule is not applied to this map. Choose Switch to FWE or Keep.")
            else:
                window = self._displayWindow(resultVolume, mapChanged)
                _window, passing = display.applyTwoSidedThreshold(resultVolume, self.resolved.value, window=window, sign=sign)
                self.lastPassing = passing
                if passing == 0:
                    quantity = {"both": f"|{ruleStatistic}|", "pos": ruleStatistic, "neg": f"−{ruleStatistic}"}[sign]  # noqa: RUF001
                    advice = _("switch to the Fz rule or use a larger connectome") if ruleStatistic == "T" else _("lower the threshold")
                    atN = _("at N={n}").format(n=n) if n else _("at N unknown")
                    empty = _("0 voxels pass {quantity} ≥ {value:.2f} {atN}: {advice}.").format(quantity=quantity, value=self.resolved.value, atN=atN, advice=advice)
        elif hasMap and resultVolume is not None and loaded is not None:
            # A map shown from a file whose N is unknown, with a rule that needs N: the module colour table, unthresholded
            window = self._displayWindow(resultVolume, mapChanged)
            display.applyResultDisplay(resultVolume, window=window, threshold=window / 64.0, sign=self._sign())
            empty = _("The map is shown unthresholded: choose Custom T and type the threshold, or an Fz or Top x% rule.")
        self.emptyResultLabel.setText(empty)
        self.emptyResultLabel.setVisible(bool(empty))
        self._showResultNotice()
        if hasMap and (mapChanged or peaks):
            if deferred:
                generation = self._refreshGeneration
                qt.QTimer.singleShot(DEFERRED_STEP_MS, lambda: generation == self._refreshGeneration and self._updatePeaks(statistic))
            else:
                self._updatePeaks(statistic)
        elif not hasMap:
            self.peaksTable.hide()
        self._updateStatusChip()
        # A map opened or computed changes the steps (Compute "Opened from a file", the N of Result)
        self._updateSteps()
        self._refreshMapOverlay()

    def _showResultNotice(self):
        """Studio (VISUAL 4.5): the explanations of the Result card (an unknown N, a map shown unthresholded, the rule's notes)
        are one warning line with "Details"; the derived threshold line stays when it is one line. Classic keeps the
        paragraphs. The labels keep their texts either way (scripts and tests read them).
        """
        notice = getattr(self, "resultNotice", None)
        if notice is None:
            return
        if not self._studioLook:
            self.widgets.setNoticeLine(notice, "")
            self.derivedLabel.show()
            return
        derived = str(self.derivedLabel.text)
        explanations = []
        derivedIsLine = derived.startswith(("⇒", _("Planned:"))) or len(derived) <= 80
        if derived and not derivedIsLine:
            explanations.append(derived)
            self.derivedLabel.hide()
        else:
            self.derivedLabel.setVisible(bool(derived))
        for label in (self.emptyResultLabel, self.ruleNotesLabel):
            if not label.isHidden() and str(label.text):
                explanations.append(str(label.text))
            label.hide()
        if not explanations:
            self.widgets.setNoticeLine(notice, "")
            return
        first = explanations[0]
        if first.startswith(_("The N of this map is unknown")):
            unthresholded = any(_("unthresholded") in text for text in explanations)
            headline = _("N unknown: the map is shown unthresholded") if unthresholded else _("N unknown: this rule needs N")
        else:
            cut = min((index for index in (first.find(": "), first.find(". "), first.find("; ")) if index > 0), default=len(first))
            headline = first[:cut].rstrip(".")
        self.widgets.setNoticeLine(notice, headline, "\n\n".join(explanations))

    def _resolveRule(self, rule, n, values, note):
        """The rule for a map with ``n`` subjects: V and the GSR flag of the connectome, or for a loaded map that is
        not on the open connectome's grid, V = its non-zero voxels. ``n`` is None for a loaded map whose N is unknown:
        only the rules that do not need N resolve (``thresholds.resolve_unknown_n``; a custom T is applied as typed).
        """
        from LesionNetworkMappingLib import thresholds

        if self.loadedMap is not None and not self._loadedOnBundleGrid():
            v = len(values) if values is not None else 0
            if not v:
                loaded = self._loadedValues(self.loadedMap.get("statistic"))
                v = len(loaded[0]) if loaded is not None else 1
            if not n:
                return thresholds.resolve_unknown_n(rule, max(int(v), 1), values=values)
            return thresholds.resolve(rule, n, max(int(v), 1), note=note, values=values)
        if self.loadedMap is not None and not n:
            return thresholds.resolve_unknown_n(rule, self.bundle.n_voxels, values=values)
        return self.logic.resolveRule(rule, n, self.bundle, values=values, note=note)

    def _displayWindow(self, volume, recompute):
        from LesionNetworkMappingLib import display

        recorded = volume.GetAttribute(display.WINDOW_ATTRIBUTE)
        if recorded and not recompute:
            try:
                return float(recorded)
            except ValueError:
                pass
        window = display.symmetricWindow(volume)
        volume.SetAttribute(display.WINDOW_ATTRIBUTE, f"{window:.6g}")
        return window

    def _refreshMapOverlay(self):
        """Studio: the map legend and the layer chips over the main view follow the map, its threshold and opacity."""
        mappage = self._mappage()
        if mappage is not None and hasattr(mappage, "refreshOverlay"):
            try:
                mappage.refreshOverlay()
            except Exception:
                logging.exception("Lesion network mapping: the map legend could not be updated")

    def _mappage(self):
        """``StudioLib.mappage`` while Studio is active (it saves and restores the layers of Map), else None."""
        if self._shell() is None:
            return None
        try:
            from StudioLib import mappage
        except ImportError:
            return None
        return mappage

    def _templateUnderMaps(self, load):
        mappage = self._mappage()
        if mappage is not None:
            return mappage.templateVolume(self.bundle, load=load)
        return self.logic.templateVolume()

    def _showLayers(self, volume):
        from LesionNetworkMappingLib import display

        mappage = self._mappage()
        if mappage is not None:
            mappage.captureLayers()  # the layers seen before Map come back when Map is left
        node = self._parameterNode
        display.showLayers(self._templateUnderMaps(load=True), volume, node.opacity if node is not None else 0.8)
        segNode, segmentId = self.ctx.seed()
        if segNode is not None and self._outlineState is None and self.seedMode() == "lesion":
            self._outlineState = display.lesionOutline(segNode, segmentId)

    def showMapLayers(self):
        """Studio Map entered (``mappage.enter``): with a result, the template, the result at 0.8 with the module colour
        table and no label layer; the lesion as a white outline. Without a result the views keep their layers (the
        lesion's own scan, which may be in native space) and nothing is loaded.
        """
        from LesionNetworkMappingLib import display

        node = self._parameterNode
        volume = node.resultVolume if node is not None else None
        if volume is not None and volume.GetScene() is None:
            volume = None
        if volume is not None:
            display.showLayers(self._templateUnderMaps(load=True), volume, node.opacity if node is not None else 0.8)
        segNode, segmentId = self.ctx.seed()
        if segNode is not None and self.seedMode() == "lesion" and self._outlineState is None:
            self._outlineState = display.lesionOutline(segNode, segmentId)

    def restoreLesionDisplay(self):
        """Give the lesion its own look back (Map left)."""
        if self._outlineState is not None:
            from LesionNetworkMappingLib import display

            display.restoreLesionDisplay(self._outlineState)
            self._outlineState = None

    #
    # Maps shown from files (Library, browsing) and from scenes
    #

    def _loadedVolume(self):
        """The volume of maps shown from files (reused, so that browsing keeps one volume in the scene), or None."""
        node = self._parameterNode
        volume = node.resultVolume if node is not None else None
        if volume is not None and volume.GetScene() is not None and volume.GetAttribute(LOADED_MAP_ATTRIBUTE):
            return volume
        for candidate in slicer.util.getNodesByClass("vtkMRMLScalarVolumeNode"):
            if candidate.GetAttribute(LOADED_MAP_ATTRIBUTE):
                return candidate
        return None

    def showMapFile(self, path, label=None):
        """Show a network or statistical map file as the Result card's map; return its volume node.

        Used for maps opened from Library or dropped (``mappage.loadMap``) and for browsing a set of maps one at a
        time: every file shown this way reuses one volume (``LNM.LoadedMap``), so the scene does not grow with the
        number of maps. The volume is a statistical map for Studio (``Studio.Role`` = "statmap": Draw never takes it
        as a scan, no segmentation is created on it) and a result for Draw (``LNM.Result``). N comes from the map's
        sidecar or its NIfTI header; the threshold rule is resolved for it as for a run.
        """
        if self.job is not None and (self.job.isRunning() or self.job.isQueued()):
            raise RuntimeError(_("A map is being computed: stop it before showing another map."))
        info = self.logic.mapFileInfo(path)
        info["label"] = label or info.get("name")
        node = self._parameterNode
        if node is None:
            self.initializeParameterNode()
            node = self._parameterNode
        statistic = info["statistic"]
        attributes = {"LNM.Statistic": statistic, "LNM.N": info["n"] or "", "LNM.Partial": "0", LOADED_MAP_ATTRIBUTE: os.path.basename(path), "Studio.Role": "statmap",
                      "Studio.Space": info.get("space")}
        name = f"{info['label']} LNM {statistic}" + (f" N={info['n']}" if info["n"] else "")
        previous = self._loadedVolume()
        volume = self.logic.loadMap(path, name, previous, saveWithScene=True, attributes=attributes)
        if volume.GetAttribute(COMPUTING_ATTRIBUTE) is not None:
            volume.RemoveAttribute(COMPUTING_ATTRIBUTE)
        # The Result card follows this map; an earlier run's map stays in the scene
        self.runOutputs, self.runN, self.runPartial, self.runPreviewN, self.runDescSuffix, self.runDir = {}, None, False, None, "", None
        self._runBundle = None
        self.loadedMap = info
        self._valuesCache.clear()
        self._mapStamp.clear()
        self._updatingGui = True
        try:
            node.statistic = statistic if statistic in STATISTICS else "T"
            self.statisticGroup.button(STATISTICS.index(self.currentStatistic())).setChecked(True)
        finally:
            self._updatingGui = False
        node.resultVolume = volume
        self.ctx.setCurrentRun(None)
        self.ctx.setResultVolume(volume)
        self._displayWindow(volume, True)
        self._showLayers(volume)
        self.updateCardVisibility()
        self.refreshResult(reloadMaps=False, peaks=True)
        return volume

    def _adoptSceneResult(self):
        """A result volume of the scene without a run of this session (a reloaded scene): the Result card shows it,
        with what its attributes say (statistic, N), also when its connectome is not on this computer.
        """
        node = self._parameterNode
        volume = node.resultVolume if node is not None else None
        if self.runOutputs or self.loadedMap is not None or volume is None or volume.GetScene() is None or volume.GetImageData() is None:
            return False
        if volume.GetAttribute(COMPUTING_ATTRIBUTE) == "1" or (self.job is not None and not self.job.isFinished()):
            return False
        statistic = volume.GetAttribute("LNM.Statistic") or self.currentStatistic()
        try:
            n = int(float(volume.GetAttribute("LNM.N") or 0)) or None
        except ValueError:
            n = None
        name = re.sub(r" LNM .*$", "", volume.GetName()) or volume.GetName()
        self.loadedMap = {"path": None, "statistic": statistic if statistic in STATISTICS else "T", "n": n, "name": name, "label": name, "siblings": {},
                          "sidecar": None, "lesion": None, "preview": "Preview" in volume.GetName(), "partial": volume.GetAttribute("LNM.Partial") == "1",
                          "fromScene": True}
        self.ctx.setResultVolume(volume)
        return True

    def _updatePeaks(self, statistic):
        from LesionNetworkMappingLib import stats

        self._peaks = []
        if self.loadedMap is not None:
            loaded = self._loadedValues(statistic)
            values, grid, indices = loaded if loaded is not None else (None, None, None)
        else:
            values = self._mapValues(statistic)
            grid, indices = (self.bundle.grid, self.bundle.mask_indices) if self.bundle is not None else (None, None)
        if values is not None and grid is not None:
            try:
                self._peaks = stats.peak_table(values, grid, top_k=5, min_distance_mm=10.0, mask_indices=indices, sign=self._sign())
            except Exception:
                logging.exception("Lesion network mapping: the peak table could not be computed")
        table = self.peaksTable
        self._setPeakValueHeader(statistic)
        table.setRowCount(len(self._peaks))
        for row, peak in enumerate(self._peaks):
            x, y, z = peak["world"]
            cells = ("…", f"{x:.0f}, {y:.0f}, {z:.0f}", f"{peak['value']:.2f}")
            for column, text in enumerate(cells):
                item = qt.QTableWidgetItem(text)
                if column == 2:
                    # Hot and cold values (VISUAL 4.5)
                    item.setForeground(qt.QBrush(self.widgets.valueColor(peak["value"])))
                if column == 0:
                    item.setToolTip(_("Looking up the region…"))
                alignment = (qt.Qt.AlignLeft if column == 0 else qt.Qt.AlignRight) | qt.Qt.AlignVCenter
                try:
                    item.setTextAlignment(alignment)
                except (TypeError, ValueError):
                    item.setTextAlignment(int(alignment))  # Qt 5 takes an int, Qt 6 the flags
                table.setItem(row, column, item)
        table.setVisible(bool(self._peaks))
        if self._peaks:
            self._lookupPeakRegions(self._peaks, grid)

    def _peakSpace(self, grid):
        """The template space of the peaks' grid (to keep the atlases of its family), or None when it cannot be told."""
        try:
            from LesionNetworkMappingLib import geometry

            return geometry.detect_space((tuple(grid.shape), grid.affine)) if grid is not None else None
        except Exception:
            return None

    def _lookupPeakRegions(self, peaks, grid):
        """Fill the Peak region column from the cached atlases in a background thread (numpy and files only, D19): the
        Result card is never held up by reading an atlas. Only the latest lookup fills the table.
        """
        from concurrent.futures import ThreadPoolExecutor

        from LesionNetworkMappingLib import atlases, fetch

        explicit = os.environ.get(fetch.CACHE_ENV)
        cache = explicit or (os.path.join(slicer.app.cachePath, "LNM") if slicer.app.cachePath else None)
        points = [peak["world"] for peak in peaks]
        space = self._peakSpace(grid)
        executor = getattr(LesionNetworkMappingWidget, "_regionExecutor", None)
        if executor is None:
            executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix="LNMPeakRegions")
            LesionNetworkMappingWidget._regionExecutor = executor
        future = executor.submit(atlases.peak_regions, points, space, cache)
        previous = getattr(self, "_peakRegionJob", None)
        if previous is not None:
            self._endPeakRegionPoll(previous)
        job = {"future": future, "peaks": peaks}
        self._peakRegionJob = job
        # Parented to the panel and deleted when the poll ends: no timer (and its Python slot) is left behind
        timer = qt.QTimer(self.parent) if self.parent is not None else qt.QTimer()
        timer.setInterval(30)

        def poll():
            if not future.done():
                return
            self._endPeakRegionPoll(job)
            if self._peakRegionJob is not job:
                return
            self._peakRegionJob = None
            try:
                regions = future.result()
            except Exception:
                logging.exception("Lesion network mapping: the peak regions could not be looked up")
                regions = None
            self._showPeakRegions(peaks, regions)

        timer.connect("timeout()", poll)
        job["timer"] = timer
        timer.start()

    @staticmethod
    def _endPeakRegionPoll(job):
        """Stop and delete the poll timer of a peak region lookup (the lookup itself ends on its own)."""
        timer = job.pop("timer", None)
        if timer is None:
            return
        try:
            timer.stop()
            # Deleting the timer also drops its connection to the Python slot
            timer.deleteLater()
        except Exception:
            pass

    def _showPeakRegions(self, peaks, regions):
        """The Peak region column: the region names, or "—" when no atlas is downloaded (the tooltip says how to get one)."""
        if peaks is not self._peaks or not hasattr(self, "peaksTable"):
            return
        noAtlas = _("No atlas downloaded: Get atlases (the Lesion card of Draw, or the Clusters card) names the peak regions")
        for row in range(min(len(peaks), self.peaksTable.rowCount)):
            item = self.peaksTable.item(row, 0)
            if item is None:
                continue
            item.setText(regions[row] if regions is not None else "—")
            item.setToolTip(noAtlas if regions is None else regions[row])
        header = self.peaksTable.horizontalHeaderItem(0)
        if header is not None:
            header.setToolTip(noAtlas if regions is None else _("The region at the peak in the downloaded atlases (Harvard-Oxford first)"))

    def onPeakClicked(self, row, column):
        if 0 <= row < len(self._peaks):
            x, y, z = self._peaks[row]["world"]
            slicer.modules.markups.logic().JumpSlicesToLocation(x, y, z, True)

    def onBinarize(self):
        """A new 0/1 volume of the voxels that pass the current threshold (same grid and affine as the map)."""
        import numpy as np

        node = self._parameterNode
        volume = node.resultVolume if node is not None else None
        if volume is None or not self._ruleAppliesToShownMap():
            # The rule applies to another statistic's map, or is not applied (the map is shown unthresholded or empty)
            return None
        array = slicer.util.arrayFromVolume(volume)
        sign, value = self._sign(), self.resolved.value
        passing = array >= value if sign == "pos" else array <= -value if sign == "neg" else np.abs(array) >= value
        matrix = vtk.vtkMatrix4x4()
        volume.GetIJKToRASMatrix(matrix)
        name = f"{volume.GetName()} mask {SIGN_LABELS[sign]}{self.currentStatistic()}≥{value:.2f}"
        binary = slicer.util.addVolumeFromArray(passing.astype(np.uint8), ijkToRAS=matrix, name=name, nodeClassName="vtkMRMLScalarVolumeNode")
        binary.SetAttribute("LNM.Result", "1")
        return binary

    def onExport(self):
        controller = self.ctx.card("export")
        if controller is not None and hasattr(controller, "export"):
            self.ctx.focusCard("export")
            controller.export()

    def _updatePrimaryAction(self):
        shell = self._shell()
        if shell is None or not getattr(self, "_entered", False):
            return
        try:
            label = self.computeButton.text
            shell.setPrimaryAction(self.onPrimary, label)
        except Exception:
            logging.exception("Lesion network mapping: the primary action could not be set")

    def _refreshStatusChip(self):
        self._statusChipText = None
        self._updateStatusChip()

    def _updateStatusChip(self):
        """Studio status chip of Map when no job owns it: "No connectome", "Ready", "Done · N=1000"."""
        from LesionNetworkMappingUI import jobrunner

        shell = self._shell()
        if shell is None or not getattr(self, "_entered", False) or jobrunner.instance().ownsStatusChip():
            return
        cohortDone = self.cohortMapsPath and self.cohortInfo
        if self.bundle is None and self.loadedMap is None:
            text, level = _("No connectome"), "neutral"
        elif self.seedMode() == "cohort":
            if cohortDone:
                text, level = (_("Done · 1 lesion map") if self.cohortInfo.get("n", 0) == 1 else _("Done · {n} lesion maps").format(n=self.cohortInfo.get("n", 0))), "ok"
            elif self.bundle is None:
                text, level = _("No connectome"), "neutral"
            else:
                text, level = _("Ready"), "neutral"
        elif self.seedMode() in SEED_SET_MODES and self.loadedMap is None:
            n = self.seedSetCount()
            if self._seedSetMaps(self.seedMode()):
                text, level = _("Done · {n} seed maps").format(n=n), "ok"
            else:
                text, level = (_("Ready") if n and self.bundle is not None else _("No seeds") if not n else _("No connectome")), "neutral"
        elif self.loadedMap is not None:
            n = self.loadedMap.get("n")
            text, level = (_("Map · N={n:,}").format(n=n) if n else _("Map")), "neutral"
        elif self.runOutputs and self.runN:
            if self._shownRunFailure() is not None:
                text, level = _("Run failed · N={n} (partial)").format(n=self.runN), "warn"
            elif self.runPartial:
                text, level = _("Stopped · N={n} (partial)").format(n=self.runN), "neutral"
            elif self.runPreviewN:
                text, level = _("Done · Preview N={n}").format(n=self.runN), "ok"
            else:
                text, level = _("Done · N={n:,}").format(n=self.runN), "ok"
        else:
            text, level = _("Ready"), "neutral"
        if text != self._statusChipText:
            self._statusChipText = text
            try:
                shell.setStatusChip(text, level)
            except Exception:
                logging.exception("Lesion network mapping: the status chip could not be set")

    #
    # Module enter / exit and scene
    #

    def enter(self):
        self._entered = True
        self.initializeParameterNode()
        self._syncStudy()
        self.refreshConnectomes()
        adopted = self._adoptSceneResult() or self._peaksPending
        self._peaksPending = False
        if adopted:
            self._displayWindow(self._parameterNode.resultVolume, False)
        if self.seedMode() == "cohort":
            self.refreshCohort()
        shell = self._shell()
        if shell is not None:
            # The result is refreshed at the end of enter(); StudioLib.mappage sets the look too (with the shell that shows
            # Map) and gives the Classic look back when Studio is left
            self.setStudioPresentation(True, refresh=False)
        if shell is not None:
            # The primary button and the disclaimer stay visible below the inspector (the sticky footer slot) while Map is shown
            if self.shellFooter is None:
                self.shellFooter = self._buildShellFooter()
            try:
                self._pinPrimary(True)
                shell.setInspectorFooter(self.shellFooter)
                self._footerInShell = True
                self.footer.hide()
            except Exception:
                logging.exception("Lesion network mapping: the inspector footer could not be set")
        self._statusChipText = None
        self.updateComputeState()
        self._preloadScientificModules()
        # A map adopted from the scene has no peak table yet (the map did not change in this session): compute it now
        self.refreshResult(reloadMaps=False, peaks=True if adopted else None)

    def _preloadScientificModules(self):
        """Import scipy.stats (about 2 s) in a background thread on the first visit, so that resolving the
        first threshold rule never freezes the application.

        Python threads only run while the main thread runs Python, so a 15 ms timer lends them the
        interpreter until the import is done.
        """
        if "scipy.stats" in sys.modules or self._preloading:
            return
        import threading

        self._preloading = True
        finished = threading.Event()

        def work():
            try:
                import scipy.stats  # noqa: F401
            except Exception:
                logging.exception("Lesion network mapping: scipy.stats could not be imported")
            finished.set()

        def pump():
            if finished.is_set():
                self._pumpTimer.stop()
                self._preloading = False
                self.refreshResult(reloadMaps=False)
                return
            time.sleep(0.003)  # releases the interpreter to the import thread

        self._pumpTimer = qt.QTimer()
        self._pumpTimer.setInterval(15)
        self._pumpTimer.connect("timeout()", pump)
        threading.Thread(target=work, name="lnm-preload", daemon=True).start()
        self._pumpTimer.start()

    def _syncStudy(self):
        """The open study: the Studio study session's, else the parameter node's studyPath (None without one)."""
        shell = self._shell()
        session = getattr(shell, "studySession", None) if shell is not None else None
        study = getattr(session, "study", None) if session is not None else None
        node = self._parameterNode
        if study is None and node is not None and node.studyPath and os.path.isfile(os.path.join(node.studyPath, "study.json")):
            try:
                from LesionNetworkMappingLib.study import Study

                study = self.ctx.study if getattr(self.ctx.study, "path", None) == node.studyPath else Study.open(node.studyPath)
            except Exception:
                logging.exception("Lesion network mapping: the study could not be opened")
                study = None
        if study is not self.ctx.study:
            self.ctx.setStudy(study)
            self._notifyControllers("onStudyChanged")

    def _buildShellFooter(self):
        """The sticky footer of the Studio inspector while Map is shown: the primary button with its reason line, and the
        disclaimer.

        The primary button is pinned there (USABILITY P5, stable layout): in a long panel (Seed = Cohort) it would otherwise be
        below the visible part of the inspector, and move when a card above it changes height (the Preflight card after the
        data use terms are accepted). ``LNMComputeButton`` keeps its object name; it goes back to the Compute card on exit.
        """
        from StudioLib import ui

        footer = qt.QWidget()
        footer.setObjectName("LNMStudioFooter")
        footer.setAttribute(qt.Qt.WA_StyledBackground, True)
        ui.bindStyleSheet(footer, lambda: (
            f"QWidget#LNMStudioFooter {{ background-color: {ui.token('window').name()}; border-top: 1px solid {ui.token('hairline').name()}; }}"))
        layout = qt.QVBoxLayout(footer)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)
        # The stretches above the button (here and in the slot) take the space that the reason line leaves while the
        # layouts settle: the footer is anchored to the bottom, so the button does not move, not even for one frame. The
        # footer never grows past its size hint (a layout with a stretch would make it take room from the inspector).
        footer.setSizePolicy(qt.QSizePolicy.Preferred, qt.QSizePolicy.Maximum)
        layout.addStretch(1)
        self._pinnedPrimarySlot = qt.QWidget()
        self._pinnedPrimarySlot.setObjectName("LNMPinnedPrimary")
        self._pinnedPrimarySlot.setSizePolicy(qt.QSizePolicy.Preferred, qt.QSizePolicy.Maximum)
        slotLayout = qt.QVBoxLayout(self._pinnedPrimarySlot)
        slotLayout.setContentsMargins(16, 8, 16, 0)
        slotLayout.setSpacing(4)
        slotLayout.addStretch(1)
        layout.addWidget(self._pinnedPrimarySlot)
        # One line (VISUAL 4.5): "Research use only. Lesion network mapping specificity is debated. Read more"; the whole
        # disclaimer with its references is behind "Read more" (and in Classic, under the cards)
        self.shellDisclaimer = self.widgets.disclaimerLine()
        self.shellDisclaimer.setContentsMargins(16, 6, 16, 6)
        layout.addWidget(self.shellDisclaimer)
        return footer

    def releaseShellFooter(self, shell=None):
        """Give the sticky footer back (Map left in Studio, or Studio switched to Classic while Map is shown): the primary
        button returns to the Compute card and the disclaimer below the cards is shown again.
        """
        if shell is not None and self._footerInShell and shell.inspectorFooter() is self.shellFooter:
            shell.setInspectorFooter(None)
        self._pinPrimary(False)
        self._footerInShell = False
        self.footer.show()

    def _pinPrimary(self, pinned):
        """Move the primary button and its reason line to the sticky footer (``pinned``) or back to the Compute card."""
        slot = self._pinnedPrimarySlot
        cardLayout = getattr(self, "_computeCardLayout", None)
        if slot is None or cardLayout is None or pinned == (self._pinnedIndexes is not None):
            return
        widgets = (self.computeButton, self.computeReasonLabel)
        if pinned:
            self._pinnedIndexes = tuple(cardLayout.indexOf(widget) for widget in widgets)
            for widget in widgets:
                cardLayout.removeWidget(widget)
                # The Compute card (ctkCollapsibleButton) filters the show events of its children and keeps the event filter
                # after a reparenting: while the card is collapsed (a map opened from a file), it would hide the pinned button
                parent = widget.parentWidget()
                if parent is not None:
                    widget.removeEventFilter(parent)
            # The reason line above the button: the footer is anchored to the bottom, so the line going away (preflight
            # finished, just before a click) changes the footer above the button and the button does not move under the
            # cursor (USABILITY 6, stable layout)
            slot.layout().addWidget(self.computeReasonLabel)
            slot.layout().addWidget(self.computeButton)
        else:
            for widget, index in zip(widgets, self._pinnedIndexes, strict=True):
                slot.layout().removeWidget(widget)
                cardLayout.insertWidget(index, widget)
            self._pinnedIndexes = None
        # Hidden by the reparenting: shown again as updateComputeState() shows them (the reason line only with a reason)
        self.computeButton.show()
        self.computeReasonLabel.setVisible(bool(str(self.computeReasonLabel.text)))
        self.ctx.primaryPinned = bool(pinned)
        self.ctx._notify("primaryPinnedChanged")

    def exit(self):
        self._entered = False
        shell = self._shell()
        if shell is not None:
            try:
                self.releaseShellFooter(shell)
                if getattr(shell, "_primaryAction", None) == self.onPrimary:
                    shell.setPrimaryAction(None, "")
                chip = getattr(getattr(shell, "topBar", None), "statusChip", None)
                from LesionNetworkMappingUI import jobrunner

                if self._statusChipText and chip is not None and str(chip.text) == self._statusChipText and not jobrunner.instance().ownsStatusChip():
                    shell.setStatusChip(None)
            except Exception:
                logging.exception("Lesion network mapping: leaving Map failed")
        self.releaseShellFooter(None)
        self._statusChipText = None
        self.restoreLesionDisplay()

    def cleanup(self):
        self._refreshGeneration += 1
        if self.managerDialog is not None:
            self.managerDialog.detachJobs()
            self.managerDialog.close()
            self.managerDialog.deleteLater()
            self.managerDialog = None
        for timer in (self.seedTimer, self.progressTimer, self.refreshTimer, self._pumpTimer):
            if timer is not None:
                timer.stop()
        self.removeObservers()
        self._notifyControllers("cleanup")
        if self.ctx is not None:
            self.ctx.cleanup()
        if getattr(slicer.modules, "LesionNetworkMappingWidget", None) is self:
            del slicer.modules.LesionNetworkMappingWidget

    def onSceneStartClose(self, caller, event):
        self._outlineState = None
        self._previousRun = None
        self._observeSeed(None)
        self.setParameterNode(None)

    def onSceneEndClose(self, caller, event):
        self.runOutputs, self.runN, self.runPartial, self.runDir = {}, None, False, None
        self._runBundle = None
        self._parkedRuns.clear()
        self.loadedMap = None
        self._peaksPending = False
        self._valuesCache.clear()
        self._mapStamp.clear()
        self.ctx.setResultVolume(None)
        self.ctx.setCurrentRun(None)
        if self.parent.isEntered:
            self.initializeParameterNode()

    @vtk.calldata_type(vtk.VTK_OBJECT)
    def onNodeAdded(self, caller, event, node):
        if node is not None and node.IsA("vtkMRMLSegmentationNode") and self._parameterNode is not None and self._parameterNode.seedSegmentation is None:
            qt.QTimer.singleShot(0, self._adoptDefaultSeed)

    def _adoptDefaultSeed(self):
        if self._parameterNode is None or self._parameterNode.seedSegmentation is not None:
            return
        segNode, segmentId = self.logic.defaultSeed()
        if segNode is not None:
            self.ctx.setSeed(segNode, segmentId)
            self.updateGUIFromParameterNode()

    def initializeParameterNode(self):
        self.setParameterNode(self.logic.getParameterNode())
        node = self._parameterNode
        if node.seedSegmentation is None:
            segNode, segmentId = self.logic.defaultSeed()
            if segNode is not None:
                node.seedSegmentation = segNode
                node.seedSegmentId = segmentId
        self.updateGUIFromParameterNode()

    def setParameterNode(self, inputParameterNode):
        self._parameterNode = inputParameterNode
        if self.ctx is not None:
            self.ctx.parameterNode = inputParameterNode

    def updateGUIFromParameterNode(self):
        node = self._parameterNode
        if node is None:
            return
        self._updatingGui = True
        try:
            if node.seedMode in self.seedModes:
                self.seedModeGroup.button(self.seedModes.index(node.seedMode)).setChecked(True)
            self.segmentationSelector.setCurrentNode(node.seedSegmentation)
            self._populateSegments(node.seedSegmentation, node.seedSegmentId)
            self.subjectsGroup.button(1 if node.subjectsMode == "preview" else 0).setChecked(True)
            self.nullCheckBox.setChecked(node.nullRelocations > 0)
            self.statisticGroup.button(STATISTICS.index(self.currentStatistic())).setChecked(True)
            self.signGroup.button(SIGNS.index(self._sign())).setChecked(True)
            self.opacitySlider.value = node.opacity
            self.coordNullCheckBox.setChecked(bool(node.coordinateNull))
            self.coordNullKSpin.setValue(int(node.coordinateNullK))
            kindIndex = self.stimKindCombo.findData(node.stimulationKind or "points")
            self.stimKindCombo.setCurrentIndex(max(kindIndex, 0))
        finally:
            self._updatingGui = False
        self._fillStimulationWeightings(self.stimulationKind())
        self._showSphere()
        self._showCoordinates()
        self._showStimulation()
        self._observeSeed(node.seedSegmentation)
        self._showRuleControls(self.currentRule())
        self._showSubjectsText()
        self._showSeedMode()
        self.updateCardVisibility()
        self.scheduleSeedUpdate()
        self.updateComputeState()


